export const QUESTIONS = [
  { id:1, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Where in the cell does glycolysis take place?", opts:["Mitochondrial matrix","Inner mitochondrial membrane","Cytoplasm","Nucleus","Smooth endoplasmic reticulum"], ans:2, exp:"Glycolysis occurs in the cytoplasm and does not require oxygen, so it can run in both aerobic and anaerobic conditions.", optExp: ["The matrix hosts the TCA cycle and link reaction, not glycolysis.","ETC complexes sit here; glycolysis is cytosolic.",null,"DNA replication/transcription happens here, not glycolysis.","The smooth ER handles lipid synthesis, not glucose breakdown."] },
  { id:2, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What is the NET ATP yield from glycolysis of one glucose molecule?", opts:["4 ATP","8 ATP","2 ATP","6 ATP","38 ATP"], ans:2, exp:"Glycolysis invests 2 ATP and generates 4 ATP, giving a net gain of 2 ATP per glucose.", optExp: ["4 is the gross production, not the net yield.","8 ATP exceeds glycolytic output; this is closer to total NADH equivalents.",null,"6 ATP would require including TCA-derived molecules.","38 ATP is the approximate yield from complete glucose oxidation, not glycolysis alone."] },
  { id:3, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme catalyses the rate-limiting step of glycolysis?", opts:["Hexokinase catalyses initial glucose phosphorylation","Phosphofructokinase-1 catalyses the rate-limiting step","Pyruvate kinase catalyses final pyruvate formation","Aldolase catalyses aldol cleavage of fructose-1,6-bisphosphate","Phosphoglyceromutase catalyses phosphate group transfer"], ans:1, exp:"PFK-1 catalyses the irreversible conversion of F6P to F1,6BP and is allosterically regulated by ATP, AMP, citrate, and F2,6BP — making it the rate-limiting step.", optExp: ["Hexokinase is irreversible but not the rate-limiting committed step.",null,"Pyruvate kinase is irreversible but not rate-limiting.","Aldolase catalyses a reversible cleavage and is not regulated.","Phosphoglyceromutase is a reversible enzyme and not the rate-limiting step."] },
  { id:4, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"PFK-1 is allosterically INHIBITED by which of the following?", opts:["AMP","ADP","High ATP concentration","Fructose-2,6-bisphosphate","Insulin"], ans:2, exp:"When ATP is abundant the cell does not need to make more, so high ATP allosterically inhibits PFK-1, slowing glycolysis.", optExp: ["AMP activates PFK-1, signalling low energy.","ADP also activates PFK-1.",null,"F2,6BP is the most potent activator of PFK-1.","Insulin upregulates glycolysis, not inhibits it."] },
  { id:5, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What are the NET products of glycolysis from one glucose molecule?", opts:["2 Pyruvate, 4 ATP, 4 NADH","2 Pyruvate, 2 ATP, 2 NADH","1 Pyruvate, 2 ATP, 1 NADH","2 Acetyl-CoA, 2 ATP, 2 NADH","2 Pyruvate, 2 ATP, 2 FADH₂"], ans:1, exp:"Per glucose: 2 pyruvate, net 2 ATP (4 made − 2 invested), and 2 NADH are produced.", optExp: ["4 ATP is gross output; 4 NADH overstates yield.",null,"Glucose (6C) splits into 2 pyruvate (3C each).","Acetyl-CoA is the product of the link reaction, not glycolysis.","FADH₂ is produced in the TCA cycle, not glycolysis."] },
  { id:6, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many ATP are consumed in the investment phase of glycolysis?", opts:["0 ATP","1 ATP","2 ATP","3 ATP","4 ATP"], ans:2, exp:"Two ATP are invested: one by hexokinase (glucose → G6P) and one by PFK-1 (F6P → F1,6BP).", optExp: ["At least 1 ATP is needed for glucose phosphorylation.","Only one phosphorylation step would leave glucose unable to split.",null,"3 ATP overstates the investment.","4 ATP describes the gross gain, not investment."] },
  { id:7, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme converts phosphoenolpyruvate (PEP) to pyruvate in the final step of glycolysis?", opts:["Phosphofructokinase","Aldolase","Triose phosphate isomerase","Pyruvate kinase","Hexokinase"], ans:3, exp:"Pyruvate kinase catalyses the irreversible transfer of phosphate from PEP to ADP, producing ATP and pyruvate.", optExp: ["PFK acts earlier on F6P.","Aldolase cleaves F1,6BP into two trioses.","Enolase converts 2-phosphoglycerate to PEP (the step before).",null,"Hexokinase acts at the start, phosphorylating glucose."] },
  { id:8, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In anaerobic conditions, how is NAD⁺ regenerated so glycolysis can continue?", opts:["Tricarboxylic acid cycle regenerates NAD⁺","Electron transport chain regenerates NAD⁺","Lactate dehydrogenase catalyses pyruvate to lactate conversion","Beta-oxidation regenerates NAD⁺","Gluconeogenesis pathway regenerates NAD⁺"], ans:2, exp:"Lactate dehydrogenase reduces pyruvate to lactate, oxidising NADH back to NAD⁺ so glycolysis can keep producing ATP.", optExp: ["The TCA cycle requires oxygen indirectly via NADH reoxidation.","The ETC requires O₂ as the terminal electron acceptor.",null,"Beta-oxidation produces NADH, it does not regenerate NAD⁺.","Gluconeogenesis consumes NADH/NADPH."] },
  { id:9, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"ATP hydrolysis (ATP → ADP + Pi) releases approximately how much free energy?", opts:["−2.3 kcal/mol","−7.3 kcal/mol","−14 kcal/mol","−3.5 kcal/mol","−20 kcal/mol"], ans:1, exp:"Hydrolysis of the terminal phosphoanhydride bond of ATP releases about −7.3 kcal/mol under standard conditions.", optExp: ["Too low — this is closer to weaker bond energies.",null,"Roughly double; this is too high for a single phosphate hydrolysis.","Too low to drive most endergonic biological reactions.","Far too high; no single ATP bond releases this much."] },
  { id:10, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which best describes an exergonic reaction?", opts:["ΔG > 0, requires energy input, non-spontaneous","ΔG < 0, releases energy, spontaneous","ΔG = 0, at thermodynamic equilibrium","ΔG > 0, releases energy, spontaneous","ΔG < 0, requires energy input, non-spontaneous"], ans:1, exp:"Exergonic reactions are spontaneous, release free energy, and have a negative ΔG.", optExp: ["This describes endergonic reactions.",null,"ΔG = 0 means equilibrium, not exergonic.","Contradictory: positive ΔG cannot release energy.","Contradictory: negative ΔG cannot require energy input."] },
  { id:11, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which of the following best describes anabolism?", opts:["Breaking down complex molecules into simpler units","Synthesizing complex molecules from simpler precursors","Converting glucose to pyruvate in glycolysis","Producing NADH in the tricarboxylic acid cycle","Generating ATP via oxidative phosphorylation"], ans:1, exp:"Anabolism builds larger molecules from smaller precursors and requires ATP input (endergonic).", optExp: ["This describes catabolism.",null,"Glycolysis is catabolic.","TCA cycle is catabolic.","Oxidative phosphorylation is catabolic energy production."] },
  { id:12, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Hexokinase differs from glucokinase in that hexokinase:", opts:["Found mainly in hepatocytes and pancreatic beta cells","Has high Km for glucose and lower substrate affinity","Has low Km and high affinity for glucose","Inducible by insulin in response to feeding","Not inhibited by its product glucose-6-phosphate"], ans:2, exp:"Hexokinase is present in most tissues with a low Km, ensuring efficient glucose uptake even at low blood glucose. Glucokinase (liver/β-cells) has a high Km and works after meals.", optExp: ["Glucokinase is the liver isoform.","High Km describes glucokinase.",null,"Glucokinase is insulin-induced, not hexokinase.","Hexokinase IS inhibited by glucose-6-phosphate (product inhibition)."] },
  { id:14, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In red blood cells, why does glycolysis end with lactate production even when oxygen is available?", opts:["Red blood cells lack mitochondria and cannot perform oxidative phosphorylation","Red blood cells lack glucose transporters on their membranes","Red blood cells have very high ATP demand relative to their size","Red blood cells cannot synthesize NADH from glycolysis","Red blood cells exclusively metabolize fatty acids for energy"], ans:0, exp:"Erythrocytes lack mitochondria, so they cannot perform oxidative phosphorylation and must regenerate NAD⁺ via lactate production.", optExp: [null,"RBCs express GLUT1 transporters abundantly.","RBC ATP demand is modest, but they still rely on glycolysis.","RBCs do make NADH in glycolysis.","RBCs rely on glucose, not fatty acids, for energy."] },
  { id:16, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The Gibbs free energy change (ΔG) of a reaction with ΔG < 0 is:", opts:["Exergonic reaction, spontaneous under standard conditions","Endergonic reaction, non-spontaneous under standard conditions","Reaction at thermodynamic equilibrium","Endergonic reaction, spontaneous under standard conditions","Exergonic reaction, non-spontaneous under standard conditions"], ans:0, exp:"Negative ΔG means the reaction is spontaneous and releases free energy.", optExp: [null,"Endergonic = positive ΔG.","Equilibrium means ΔG = 0.","Contradictory.","Contradictory."] },
  { id:17, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which molecule is the most potent allosteric ACTIVATOR of PFK-1?", opts:["Fructose-2,6-bisphosphate is the most potent allosteric activator","ATP is a potent allosteric inhibitor of PFK-1","Citrate is a potent allosteric inhibitor of PFK-1","NADH is a potent allosteric inhibitor of PFK-1","Acetyl-CoA is a potent allosteric inhibitor of PFK-1"], ans:0, exp:"F2,6BP, produced by PFK-2 in response to insulin, is the most potent activator of PFK-1 and stimulates glycolysis after meals.", optExp: [null,"ATP inhibits PFK-1.","Citrate (high TCA output) inhibits PFK-1.","NADH is not a PFK regulator.","Acetyl-CoA does not regulate PFK-1 directly."] },
  { id:18, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What is the immediate product of pyruvate kinase?", opts:["Pyruvate and ATP","Lactate from pyruvate","Acetyl-CoA from pyruvate","Phosphoenolpyruvate","Oxaloacetate from pyruvate"], ans:0, exp:"Pyruvate kinase transfers a phosphate from PEP to ADP, producing pyruvate and ATP.", optExp: [null,"Lactate is produced later by LDH if anaerobic.","Acetyl-CoA is from the link reaction.","PEP is the SUBSTRATE, not the product.","OAA is a TCA intermediate, not a glycolysis product."] },
  { id:19, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What is the role of NAD⁺ in glycolysis?", opts:["Accepts electrons from GAPDH","Donates electrons to GAPDH","Acts as a phosphate donor","Phosphorylates ADP to ATP","Stabilizes pyruvate"], ans:1, exp:"GAPDH oxidises glyceraldehyde-3-phosphate, reducing NAD⁺ to NADH.", optExp: ["NAD⁺ accepts (does not donate) electrons.",null,"NAD⁺ is an electron carrier, not a phosphate donor.","Substrate-level phosphorylation involves PGK/PK, not NAD⁺.","NAD⁺ has no structural role with pyruvate."] },
  { id:20, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Catabolism is best described as:", opts:["Breaking down molecules for energy","Building up complex molecules","Synthesizing nucleic acid polymers","Phosphorylating various substrates","Reducing oxygen to water"], ans:0, exp:"Catabolism breaks larger molecules into smaller units, releasing energy in the form of ATP and reducing equivalents.", optExp: [null,"This is anabolism.","Nucleic acid synthesis is anabolic.","Phosphorylation can be either anabolic or catabolic.","This is one specific step in oxidative phosphorylation."] },
  { id:21, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Where does the TCA cycle take place?", opts:["Cytoplasm","Intermembrane space","Inner mitochondrial membrane","Mitochondrial matrix","Outer mitochondrial membrane"], ans:3, exp:"Both the link reaction and the TCA cycle occur in the mitochondrial matrix.", optExp: ["The cytoplasm hosts glycolysis.","ETC pumps protons here; TCA does not run here.","The ETC sits here, not TCA enzymes.",null,"Only the outer membrane sits here; no TCA reactions."] },
  { id:22, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme catalyses the link reaction (pyruvate → acetyl-CoA)?", opts:["Pyruvate kinase","Isocitrate dehydrogenase","Pyruvate dehydrogenase","Citrate synthase","α-ketoglutarate dehydrogenase"], ans:2, exp:"PDH oxidatively decarboxylates pyruvate, producing acetyl-CoA, CO₂, and NADH.", optExp: ["Pyruvate kinase acts in glycolysis, making pyruvate from PEP.","IDH is the TCA rate-limiting enzyme; comes later.",null,"Citrate synthase joins acetyl-CoA to OAA inside the TCA.","α-KG dehydrogenase acts on α-KG within the TCA cycle."] },
  { id:23, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What are the products of the link reaction?", opts:["Acetyl-CoA, CO₂, and NADH","Acetyl-CoA and FADH₂ with CO₂","Acetyl-CoA, H₂O, and NADH","Acetyl-CoA, ATP, and CO₂","Acetyl-CoA, 2 NADH, and CO₂"], ans:0, exp:"PDH converts pyruvate to acetyl-CoA, releasing one CO₂ and producing one NADH per pyruvate.", optExp: [null,"FADH₂ is not produced by PDH.","No water is produced as a labelled product here.","PDH does not produce ATP.","Only one NADH per pyruvate."] },
  { id:24, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What is the rate-limiting enzyme of the TCA cycle?", opts:["Enzyme that catalyzes isocitrate oxidation","Enzyme that catalyzes citrate formation","Enzyme that catalyzes succinate oxidation","Enzyme that catalyzes malate conversion","Enzyme that catalyzes aconitase conversion"], ans:0, exp:"Isocitrate dehydrogenase catalyses the rate-limiting step. It is activated by ADP and inhibited by ATP/NADH.", optExp: [null,"Citrate synthase is regulated but not the rate-limiting step.","SDH (Complex II) is unregulated allosterically.","MDH catalyses the last step but is not rate-limiting.","Aconitase is a freely reversible isomerisation step."] },
  { id:25, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What are the products of ONE complete turn of the TCA cycle?", opts:["3 NADH, 1 FADH₂, 1 GTP, 2 CO₂","2 NADH, 2 FADH₂, 1 ATP, 2 CO₂","4 NADH, 1 FADH₂, 1 ATP, 3 CO₂","3 NADH, 2 FADH₂, 2 ATP, 2 CO₂","2 NADH, 1 FADH₂, 2 ATP, 2 CO₂"], ans:0, exp:"Per acetyl-CoA: 3 NADH, 1 FADH₂, 1 GTP/ATP, 2 CO₂ — the '3211' rule.", optExp: [null,"Only 1 FADH₂ per turn (from succinate→fumarate).","4 NADH overstates yield.","Only 1 GTP per turn.","Only 2 NADH is too few."] },
  { id:26, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Isocitrate dehydrogenase is allosterically activated by:", opts:["High ADP levels","High NADH levels","High ATP levels","High Acetyl-CoA levels","High oxaloacetate levels"], ans:0, exp:"ADP signals low cellular energy and activates IDH, accelerating the TCA cycle.", optExp: [null,"NADH inhibits IDH.","ATP inhibits IDH.","Acetyl-CoA activates PDH but not IDH directly.","OAA is a substrate downstream, not an allosteric activator."] },
  { id:27, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme joins oxaloacetate with acetyl-CoA at the start of the TCA cycle?", opts:["Citrate synthase","Isocitrate dehydrogenase","Aconitase","Succinyl-CoA synthetase","Fumarase"], ans:0, exp:"Citrate synthase condenses 4C OAA with 2C acetyl-CoA to form 6C citrate.", optExp: [null,"Isocitrate dehydrogenase acts later, on isocitrate.","Aconitase isomerises citrate to isocitrate — it does not form citrate.","Succinyl-CoA synthetase makes GTP further along.","Fumarase converts fumarate to malate."] },
  { id:28, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The Cori cycle transports which substrate from muscle to liver for re-conversion to glucose?", opts:["Lactate","Fatty acids","Acetyl-CoA","Alanine","Glycerol"], ans:0, exp:"Lactate produced by anaerobic glycolysis in muscle is exported to the liver, where gluconeogenesis converts it back to glucose.", optExp: [null,"Fatty acids are not part of the Cori cycle.","Acetyl-CoA cannot be converted back to glucose — it is irreversibly committed to the TCA cycle.","Alanine is the substrate of the glucose-alanine cycle, not the Cori cycle.","Glycerol enters gluconeogenesis but is not exported from muscle via the Cori cycle."] },
  { id:29, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Acetyl-CoA entering the TCA cycle can come from each of the following EXCEPT:", opts:["Direct conversion from lactate","Pyruvate via the link reaction","Beta-oxidation of fatty acids","Ketogenic amino acids","Ketone bodies"], ans:0, exp:"Lactate must first be converted back to pyruvate, then via PDH to acetyl-CoA — there is no direct lactate → acetyl-CoA step.", optExp: [null,"This is the standard PDH route.","Beta-oxidation produces acetyl-CoA in mitochondria.","Ketogenic amino acids (leucine, lysine) yield acetyl-CoA.","Ketone bodies can be reconverted to acetyl-CoA in extrahepatic tissues."] },
  { id:34, cat:"TCA Cycle & Link Reaction", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many CO₂ molecules are released per turn of the TCA cycle (excluding link reaction)?", opts:["2 CO₂ molecules","1 CO₂ molecule","3 CO₂ molecules","4 CO₂ molecules","0 CO₂ molecules"], ans:0, exp:"Two CO₂ molecules are released per turn — by IDH (isocitrate → α-KG) and α-KG dehydrogenase (α-KG → succinyl-CoA).", optExp: [null,"Two decarboxylations occur per turn.","3 would include the link reaction's CO₂.","Excessive; only 2 decarboxylating steps in the cycle proper.","CO₂ IS released in the TCA cycle."] },
  { id:36, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Where is the electron transport chain located?", opts:["On the inner mitochondrial membrane","Within the mitochondrial matrix","Within the cellular cytoplasm","On the outer mitochondrial membrane","Within the nuclear envelope"], ans:0, exp:"Complexes I-V of the ETC are embedded in the inner mitochondrial membrane, allowing proton pumping into the intermembrane space.", optExp: [null,"The matrix hosts TCA enzymes, not the ETC.","Glycolysis is cytoplasmic; the ETC is not.","The outer membrane is permeable to ions and lacks ETC complexes.","DNA replication occurs here, not the ETC."] },
  { id:37, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"What is the final electron acceptor of the ETC?", opts:["Oxygen","NAD⁺","FAD","CO₂","Cytochrome c"], ans:0, exp:"Oxygen accepts electrons at Complex IV (cytochrome c oxidase) and combines with H⁺ to form water.", optExp: [null,"NAD⁺ accepts electrons in the TCA cycle, not the end of ETC.","FAD acts at substrate level, not the end of ETC.","CO₂ is a waste product, not an electron acceptor.","Cytochrome c is an intermediate mobile carrier, not final."] },
  { id:38, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which complex accepts electrons from NADH?", opts:["Complex I","Complex II","Complex III","Complex IV","Complex V"], ans:3, exp:"NADH dehydrogenase (Complex I) oxidises NADH and passes electrons to coenzyme Q while pumping 4 H⁺.", optExp: ["Complex II accepts electrons from FADH₂, not NADH.","Complex III receives from coenzyme Q.","Complex IV receives from cytochrome c.",null,"Complex V is ATP synthase, not an electron transfer complex."] },
  { id:39, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which mobile carrier transports electrons from Complex I/II to Complex III?", opts:["Coenzyme Q","Cytochrome c","NADH","FADH₂","Iron-sulfur clusters"], ans:0, exp:"Coenzyme Q is a lipid-soluble quinone that shuttles electrons through the inner membrane to Complex III.", optExp: [null,"Cytochrome c transports between Complex III and IV.","NADH delivers electrons but is not mobile within the membrane.","FADH₂ is tethered to Complex II.","Iron-sulfur clusters are within complexes, not mobile."] },
  { id:40, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The mechanism by which proton flow through ATP synthase drives ATP production is called:", opts:["Chemiosmosis","Substrate-level phosphorylation","Beta-oxidation","Glycolysis","Fermentation"], ans:0, exp:"Chemiosmosis is the use of the proton gradient (proton-motive force) across the inner mitochondrial membrane to power ATP synthesis.", optExp: [null,"This describes direct phosphate transfer in glycolysis/TCA.","Beta-oxidation is fatty acid breakdown.","Glycolysis is glucose breakdown.","Fermentation regenerates NAD⁺ but does not produce ATP from a gradient."] },
  { id:41, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Approximately how many ATP are produced from complete oxidation of one glucose molecule?", opts:["Approximately 2 ATP","Approximately 8 ATP","Approximately 18 ATP","Approximately 30-38 ATP","Approximately 100 ATP"], ans:3, exp:"Complete oxidation yields ~30-38 ATP: 2 from glycolysis, 2 from TCA SLP, and the rest from oxidative phosphorylation.", optExp: ["2 ATP is the glycolytic yield alone.","Too low for complete oxidation.","Significantly undershoots the actual yield.",null,"100 ATP exceeds the theoretical limit."] },
  { id:42, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Why do fats yield more energy per gram than carbohydrates?", opts:["Fatty acids generate more NADH and FADH₂ per molecule","Lipids contain more oxygen atoms","Lipids enter the TCA cycle directly","Lipids bypass ATP phosphorylation","Glycerol directly produces ATP"], ans:0, exp:"Fatty acids are highly reduced; beta-oxidation generates abundant NADH and FADH₂, producing ~9 kcal/g vs ~4 kcal/g for carbohydrates.", optExp: [null,"Lipids contain LESS oxygen than carbohydrates.","Fatty acids must be processed via beta-oxidation first.","Lipids still rely on oxidative phosphorylation.","Glycerol enters glycolysis/gluconeogenesis, not ATP directly."] },
  { id:45, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Cyanide inhibits oxidative phosphorylation by binding to:", opts:["Complex I","Complex II","Complex III","Complex IV","ATP synthase"], ans:3, exp:"Cyanide binds the Fe³⁺ in cytochrome c oxidase (Complex IV), preventing electron transfer to oxygen and stopping the ETC.", optExp: ["Rotenone (a pesticide) inhibits Complex I.","Malonate is a Complex II inhibitor.","Antimycin A inhibits Complex III.",null,"Oligomycin inhibits ATP synthase, not cyanide."] },
  { id:46, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Uncoupling agents (e.g. DNP, thermogenin in brown fat) cause:", opts:["Loss of the proton gradient across the inner mitochondrial membrane","Increased ATP synthesis","Cessation of oxygen consumption","Inhibition of glycolysis","Reduced TCA cycle activity"], ans:0, exp:"Uncouplers allow protons to leak back across the membrane without going through ATP synthase, dissipating the gradient as heat.", optExp: [null,"ATP synthesis decreases when uncoupled.","Oxygen consumption actually increases.","Glycolysis is not directly affected.","TCA may speed up to compensate."] },
  { id:47, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Brown adipose tissue generates heat via:", opts:["UCP1 uncouples oxidative phosphorylation to dissipate energy as heat","Increased glycolysis in brown adipose tissue","Beta-oxidation alone produces significant heat","Substrate cycling in muscle tissue","Cytochrome P450 activity increases"], ans:0, exp:"Thermogenin (UCP1) allows protons to bypass ATP synthase, dissipating the gradient as heat — important in neonates.", optExp: [null,"Glycolysis is not a major heat source in BAT.","Beta-oxidation feeds fuel but doesn't itself uncouple.","Substrate cycles consume ATP but are not the main mechanism.","CYP450 is for drug metabolism, not thermogenesis."] },
  { id:48, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"ATP synthase (Complex V) uses what to drive ATP synthesis?", opts:["Electron flow","Substrate-level phosphorylation","Proton gradient flowing down its electrochemical gradient","ATP hydrolysis","NADH oxidation"], ans:2, exp:"H⁺ flow from the intermembrane space back to the matrix through ATP synthase drives rotation and ATP synthesis.", optExp: ["Electron flow happens at I-IV, not V.","SLP is in glycolysis/TCA.",null,"That is the reverse reaction.","NADH oxidation is at Complex I."] },
  { id:50, cat:"Oxidative Phosphorylation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In oxidative phosphorylation, oxygen is reduced to:", opts:["Carbon dioxide","Hydrogen peroxide","Water","Superoxide radical only","Ozone"], ans:2, exp:"At Complex IV, O₂ accepts four electrons and combines with 4 H⁺ to form 2 H₂O.", optExp: ["CO₂ is produced in TCA and link reaction, not the ETC.","H₂O₂ may form as a side product but is not the main product.",null,"Superoxide can form as a leak but is detoxified.","Ozone is not a biological product."] },
  { id:51, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How do enzymes accelerate reactions?", opts:["Lower the activation energy of the reaction","Shift equilibrium toward products","Raise the energy of substrates","Bind substrates permanently","Increase the reaction temperature"], ans:0, exp:"Enzymes lower the activation energy (Ea), allowing reactions to proceed faster without changing ΔG.", optExp: [null,"Enzymes do not shift equilibrium position.","They lower, not raise, energy barriers.","Enzymes bind transiently, not permanently.","They do not increase temperature."] },
  { id:52, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"An apoenzyme is:", opts:["Inactive enzyme lacking a required cofactor or coenzyme","Active enzyme bound to its cofactor","Enzyme that has been denatured","Enzyme with multiple active sites","Regulatory protein subunit"], ans:0, exp:"Apoenzyme = protein-only, inactive. Apoenzyme + cofactor = holoenzyme (active).", optExp: [null,"That is a holoenzyme.","Denatured enzymes are permanently inactive; apoenzymes can be reactivated.","Number of active sites is unrelated.","Regulatory subunits are different structural elements."] },
  { id:53, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The induced fit model states that:", opts:["The active site changes shape upon substrate binding","The active site is permanently rigid","Substrate molds to fit a rigid active site","Enzymes bind any substrate with equal affinity","The active site remains open and unchanging"], ans:0, exp:"In induced fit, the active site flexibly remodels around the substrate, optimising catalysis.", optExp: [null,"Rigid fit is the older 'lock and key' model.","The enzyme changes, not the substrate.","Enzymes are specific.","Active sites can close around substrate."] },
  { id:54, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Km (Michaelis constant) is:", opts:["The substrate concentration at which the enzyme reaches half its maximum velocity","The maximum velocity achieved by the enzyme","The rate of product formation","The enzyme saturation level","The inhibitor binding constant"], ans:0, exp:"Km = [S] at which enzyme velocity is ½ Vmax. Low Km = high affinity for substrate.", optExp: [null,"That is Vmax.","That is k_cat or turnover.","Km is a substrate parameter, not enzyme concentration.","Ki is the inhibitor constant."] },
  { id:55, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A competitive inhibitor affects enzyme kinetics by:", opts:["It increases Km while Vmax remains unchanged","It decreases Vmax only","It decreases both Km and Vmax","It increases both Km and Vmax","It decreases Km only"], ans:0, exp:"Competitive inhibitors compete for the active site — more substrate restores Vmax, but more is needed to reach ½ Vmax (Km increases).", optExp: [null,"This describes non-competitive inhibition.","This describes uncompetitive inhibition.","Both increasing is not typical.","Km should INCREASE with competitive inhibition."] },
  { id:56, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A non-competitive inhibitor affects enzyme kinetics by:", opts:["Binds to the allosteric site, not the active site","Decreases Vmax only","Binds to both free enzyme and enzyme-substrate complex","Increases Km without affecting Vmax","Always produces irreversible inhibition"], ans:1, exp:"Non-competitive inhibitors bind allosteric sites and cannot be overcome by more substrate. Vmax decreases; Km unchanged.", optExp: ["This is competitive.",null,"That's uncompetitive (binds ES complex).","Inhibitors do not increase Vmax.","Many non-competitive inhibitors are reversible."] },
  { id:57, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Uncompetitive inhibitors:", opts:["Binds only to the enzyme-substrate complex","Decreases both Km and Vmax proportionally","Increases Vmax at higher substrate concentrations","Always produces irreversible inhibition","Cannot be overcome by increasing substrate concentration"], ans:0, exp:"Uncompetitive inhibitors bind only the ES complex, locking the substrate in. Both Km and Vmax decrease.", optExp: [null,"Km and Vmax do decrease, but binding only the ES complex is the defining feature.","Inhibitors decrease, not increase, Vmax.","Reversibility varies.","True but not the defining feature."] },
  { id:58, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"On a Lineweaver-Burk plot, the y-intercept equals:", opts:["Vmax directly","1/Vmax (the reciprocal of Vmax)","Km directly","Negative 1/Km","The slope of the line"], ans:1, exp:"On the double-reciprocal plot, the y-intercept = 1/Vmax and the x-intercept = −1/Km.", optExp: ["Vmax is not the y-intercept directly.",null,"Km appears as the x-intercept reciprocal.","x-intercept value, not y.","Slope-related, not y-intercept."] },
  { id:59, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Most human enzymes function optimally at:", opts:["25°C","30°C","37°C","42°C","45°C"], ans:2, exp:"Human enzymes evolved at core body temperature (~37°C). Above this, denaturation occurs.", optExp: ["Too cold; enzyme activity drops.","Below optimum.",null,"This is feverish; many enzymes start to denature.","Significant denaturation occurs."] },
  { id:60, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"An enzyme with a LOW Km has:", opts:["Low affinity for its substrate","High affinity for its substrate","Very high Vmax at all times","Inability to undergo competitive inhibition","An absolute requirement for cofactors"], ans:1, exp:"Low Km = high substrate affinity (e.g. hexokinase). The enzyme operates efficiently at low substrate concentrations.", optExp: ["Inverse of correct.",null,"Km is independent of Vmax.","Low Km enzymes can still be inhibited.","Km does not indicate cofactor requirement."] },
  { id:61, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which is NOT an irreversible step of glycolysis?", opts:["The hexokinase reaction is reversible","The phosphoglucose isomerase reaction is reversible","The PFK-1 reaction is irreversible","The pyruvate kinase reaction is irreversible","All glycolytic steps are reversible"], ans:1, exp:"The three irreversible steps are hexokinase, PFK-1, and pyruvate kinase. Phosphoglucose isomerase (step 2) is reversible, making it the only reversible step listed.", optExp: ["Hexokinase IS irreversible — it is one of the three irreversible glycolytic steps.",null,"PFK-1 IS irreversible — the rate-limiting step of glycolysis.","Pyruvate kinase IS irreversible — the final step of glycolysis.","Most glycolytic steps are reversible; only hexokinase, PFK-1, and pyruvate kinase are irreversible."] },
  { id:62, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Vmax is best defined as:", opts:["The maximum velocity achieved at enzyme saturation","The substrate concentration at half-maximal velocity","The minimum velocity ever achieved by the enzyme","The enzyme-substrate dissociation constant","The ratio of product formed to substrate consumed"], ans:0, exp:"Vmax is the maximum rate when all enzyme active sites are saturated with substrate.", optExp: [null,"That is Km.","Vmax is the MAXIMUM, not minimum.","That is Kd, a different parameter.","That describes k_cat or turnover number."] },
  { id:63, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Allosteric enzymes typically show:", opts:["Hyperbolic kinetics","Sigmoidal kinetics","Constant velocity regardless of substrate concentration","Inverse relationship between substrate and velocity","No saturation point"], ans:1, exp:"Allosteric enzymes (often multi-subunit) show sigmoidal kinetics due to cooperative substrate binding.", optExp: ["Michaelis-Menten enzymes show hyperbolic kinetics.",null,"Velocity changes with substrate.","Not a real kinetic shape.","Allosteric enzymes do saturate."] },
  { id:64, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"An irreversible inhibitor:", opts:["Can be overcome by adding excess substrate","Forms permanent covalent bonds with the enzyme","Binds reversibly to the allosteric site","Always increases Vmax of the enzyme","Reduces Km while leaving Vmax unchanged"], ans:1, exp:"Irreversible inhibitors form covalent bonds and permanently disable the enzyme (e.g. aspirin acetylating COX).", optExp: ["Cannot be overcome — they are covalently bound.",null,"Allosteric inhibitors can be reversible.","Inhibitors lower activity.","Doesn't describe irreversible inhibition."] },
  { id:65, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which TCA enzyme is inhibited by high NADH?", opts:["Citrate synthase only","Isocitrate dehydrogenase only","Both citrate synthase and isocitrate dehydrogenase","Aconitase only","Fumarase only"], ans:2, exp:"Both citrate synthase and IDH (and α-KG DH) are inhibited by NADH, which signals high cellular energy state.", optExp: ["Citrate synthase is inhibited, but so are others.","IDH is inhibited, but so is citrate synthase.",null,"Aconitase is not allosterically regulated.","Fumarase is not allosterically regulated."] },
  { id:66, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Gluconeogenesis produces glucose from non-carbohydrate sources mainly in the:", opts:["Brain","Heart","Liver","Skeletal muscle","Spleen"], ans:2, exp:"Gluconeogenesis occurs principally in the liver (and to a smaller extent the kidney cortex), maintaining blood glucose during fasting.", optExp: ["The brain consumes glucose; cannot make it.","Heart consumes glucose/fatty acids.",null,"Muscle lacks glucose-6-phosphatase, so cannot release glucose.","The spleen has no significant role in gluconeogenesis."] },
  { id:67, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which of the following substrates is NOT a major gluconeogenic precursor?", opts:["Lactate","Glycerol","Alanine","Acetyl-CoA","Pyruvate"], ans:3, exp:"Acetyl-CoA cannot be net converted to glucose in humans — there is no enzyme to bypass the irreversible PDH step.", optExp: ["Lactate (Cori cycle) is a major precursor.","Glycerol from triacylglycerols is a precursor.","Alanine (glucose-alanine cycle) is a major precursor.",null,"Pyruvate enters via pyruvate carboxylase."] },
  { id:68, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme is unique to gluconeogenesis, bypassing pyruvate kinase?", opts:["Pyruvate dehydrogenase","Pyruvate carboxylase and phosphoenolpyruvate carboxykinase (PEPCK)","Hexokinase","Aldolase","Phosphoglucose isomerase"], ans:1, exp:"Pyruvate carboxylase converts pyruvate to OAA; PEPCK then converts OAA to PEP, bypassing irreversible pyruvate kinase.", optExp: ["PDH converts pyruvate to acetyl-CoA, not gluconeogenic.",null,"Hexokinase makes G6P from glucose, the opposite direction.","Aldolase is shared with glycolysis (reversible).","Reversible enzyme shared with glycolysis."] },
  { id:69, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme bypasses PFK-1 in gluconeogenesis?", opts:["Fructose-1,6-bisphosphatase","Glucose-6-phosphatase","Hexokinase","Aldolase","Enolase"], ans:0, exp:"Fructose-1,6-bisphosphatase hydrolyses F1,6BP to F6P, the gluconeogenic bypass of PFK-1.", optExp: [null,"G6Pase bypasses hexokinase at the final step.","Hexokinase is glycolytic.","Aldolase is reversible.","Enolase is reversible."] },
  { id:70, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Why can't muscle release free glucose into the blood?", opts:["It lacks glucokinase","It lacks glucose-6-phosphatase","It lacks pyruvate carboxylase","It lacks glycogen synthase","Its glucose is sequestered in the glycolytic pathway"], ans:1, exp:"Muscle lacks glucose-6-phosphatase, so G6P generated from glycogen cannot be dephosphorylated to free glucose for export.", optExp: ["Muscle uses hexokinase, not glucokinase.",null,"Muscle lacks pyruvate carboxylase too, but the key difference is G6Pase.","Muscle has glycogen synthase.","Not a real mechanism."] },
  { id:71, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which hormone promotes glycogenolysis in the liver during fasting?", opts:["Insulin","Glucagon","Aldosterone","Calcitonin","Oxytocin"], ans:1, exp:"Glucagon (and adrenaline) activates glycogen phosphorylase via cAMP/PKA, mobilising glucose from glycogen stores.", optExp: ["Insulin promotes glycogen STORAGE.",null,"Aldosterone regulates Na/K.","Calcitonin regulates calcium.","Oxytocin acts on uterus and breast."] },
  { id:72, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme catalyses the rate-limiting step of glycogen synthesis?", opts:["Glycogen phosphorylase","Glycogen synthase","Branching enzyme","Debranching enzyme","UDP-glucose pyrophosphorylase"], ans:1, exp:"Glycogen synthase is rate-limiting in glycogenesis, activated by insulin (via dephosphorylation).", optExp: ["This is the glycogenolysis enzyme.",null,"Branching enzyme adds α-1,6 branches but isn't rate-limiting.","Debranching is for glycogenolysis.","Provides activated glucose but isn't rate-limiting."] },
  { id:73, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme is the rate-limiting step of glycogenolysis?", opts:["Glycogen synthase","Glycogen phosphorylase","Branching enzyme","Glucokinase","Phosphoglucomutase"], ans:1, exp:"Glycogen phosphorylase liberates glucose-1-phosphate from glycogen and is rate-limiting; activated by glucagon/adrenaline.", optExp: ["This is for glycogen synthesis.",null,"Adds branches, not rate-limiting.","Glucokinase is in glucose phosphorylation.","Converts G1P to G6P, downstream."] },
  { id:74, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In severe liver disease, a patient is most likely to develop:", opts:["Hyperglycaemia develops","Hypoglycaemia develops","Ketoacidosis develops","Lactic alkalosis develops","Glycogen accumulates excessively"], ans:1, exp:"The liver maintains blood glucose during fasting via gluconeogenesis and glycogenolysis. Severe liver dysfunction → hypoglycaemia.", optExp: ["Patients usually become hypoglycaemic.",null,"Liver may also affect ketone clearance but hypoglycaemia is the key finding.","Lactic acidosis (not alkalosis) is more typical.","Glycogen stores are reduced."] },
  { id:75, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many ATP equivalents does the Cori cycle cost the body per glucose recycled?", opts:["1 ATP equivalent","2 ATP equivalents","4 ATP equivalents","6 ATP equivalents","8 ATP equivalents"], ans:2, exp:"Muscle gains 2 ATP from anaerobic glycolysis, but the liver uses 6 ATP to remake glucose — a net cost of 4 ATP.", optExp: ["Too few.","Too few.",null,"Overestimates the net loss.","Overestimates the net loss."] },
  { id:76, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Glycogen branches are formed by an α-1,6 glycosidic bond approximately every:", opts:["Every 2–3 residues","Every 4–6 residues","Every 8–10 residues","Every 30–50 residues","Every 100 residues"], ans:2, exp:"Branching enzyme introduces α-1,6 branches roughly every 8-10 glucose units, increasing solubility and accessibility.", optExp: ["Too frequent.","Too frequent.",null,"Branches are denser than this.","Far too sparse."] },
  { id:77, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The activated form of glucose used to add residues to glycogen is:", opts:["Glucose-6-phosphate","Fructose-1,6-bisphosphate","UDP-glucose","ADP-glucose","Glucose-1-phosphate"], ans:2, exp:"UDP-glucose, made by UDP-glucose pyrophosphorylase, donates glucose units to growing glycogen chains.", optExp: ["G6P is the entry point, not the donor.","An unrelated glycolysis intermediate.",null,"ADP-glucose is the plant/bacterial donor.","G1P is the immediate precursor of UDP-glucose."] },
  { id:78, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"During prolonged fasting, the brain begins to use which alternative fuel?", opts:["Fatty acids","Amino acids","Ketone bodies","Lactate","Glycerol"], ans:2, exp:"After a few days of fasting, the brain shifts to using ketone bodies (β-hydroxybutyrate, acetoacetate) for ~60% of its energy.", optExp: ["Fatty acids cannot cross the BBB efficiently.","Amino acids are not the main brain fuel.",null,"Lactate use is limited.","Glycerol is too minor a fuel source."] },
  { id:79, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Glycogen storage in the liver primarily serves to:", opts:["Provides ATP for hepatocytes","Maintains blood glucose during fasting","Powers skeletal muscle contraction","Stores water molecules","Synthesizes cholesterol"], ans:1, exp:"Liver glycogen is broken down to release free glucose into the blood, maintaining blood glucose levels between meals.", optExp: ["Liver glycogen serves systemic glucose homeostasis, not local ATP.",null,"Muscle has its own glycogen.","Glycogen is hydrated but storage isn't for water.","Cholesterol synthesis uses acetyl-CoA, not glycogen directly."] },
  { id:80, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Adrenaline activates glycogenolysis in muscle via:", opts:["α1 receptors and IP3 signalling","β2 receptors and cAMP signalling","M3 muscarinic receptors","Insulin receptors","Nicotinic receptors"], ans:1, exp:"Adrenaline binds β2 receptors on muscle (Gs-coupled), raising cAMP, activating PKA, which activates phosphorylase kinase → glycogen phosphorylase.", optExp: ["α1 receptors are more on vascular smooth muscle.",null,"M3 are smooth muscle/glandular.","Insulin promotes glycogen STORAGE.","Nicotinic receptors are ligand-gated ion channels."] },
  { id:81, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Where does beta-oxidation of fatty acids occur?", opts:["Cytoplasm","Mitochondrial matrix","Lysosome","Smooth endoplasmic reticulum","Nuclear envelope"], ans:1, exp:"Beta-oxidation occurs in the mitochondrial matrix (peroxisomes handle very-long-chain fatty acids).", optExp: ["Fatty acid synthesis is cytoplasmic, but breakdown is mitochondrial.",null,"Lysosomes degrade macromolecules but not via beta-oxidation.","Smooth ER handles lipid SYNTHESIS.","Beta-oxidation does not happen here."] },
  { id:82, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Long-chain fatty acids enter mitochondria via:", opts:["Diffusion through the outer membrane","Carnitine shuttle system","GLUT4 transporter","ATP synthase complex","Sodium-glucose co-transporter"], ans:1, exp:"Long-chain fatty acyl-CoAs are conjugated to carnitine by CPT-I, transported by translocase, and reformed by CPT-II in the matrix.", optExp: ["Long chains cannot freely cross the inner membrane.",null,"GLUT4 transports glucose.","ATP synthase is for protons.","Sodium-glucose co-transport is for intestinal/renal glucose."] },
  { id:83, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Each cycle of beta-oxidation produces:", opts:["1 NADH, 1 FADH₂, and 1 acetyl-CoA","2 NADH and 1 acetyl-CoA","1 ATP, 1 NADH, and 1 FADH₂","2 acetyl-CoA and 1 NADH","1 NADH, 1 FADH₂, and 2 acetyl-CoA"], ans:0, exp:"Each round shortens the fatty acid by 2 carbons, releasing one acetyl-CoA and reducing one FAD and one NAD⁺.", optExp: [null,"FADH₂ is also produced.","ATP is not directly produced per cycle.","Only one acetyl-CoA per cycle.","Only one acetyl-CoA per cycle."] },
  { id:84, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Beta-oxidation is most active in which condition?", opts:["Fed state with high insulin levels","Fasting or prolonged exercise","High-carbohydrate meal","Anaerobic exercise","Immediate postprandial period"], ans:1, exp:"Beta-oxidation is upregulated when glucose is low: fasting, prolonged exercise, or starvation.", optExp: ["Insulin suppresses lipolysis and beta-oxidation.",null,"Insulin suppresses fatty acid use.","Anaerobic exercise relies on glycolysis.","Insulin spikes here, suppressing beta-oxidation."] },
  { id:85, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Ketone bodies are produced in the liver from:", opts:["Glucose","Acetyl-CoA","Lactate","Amino acids","Pyruvate"], ans:1, exp:"Ketogenesis condenses two acetyl-CoA into acetoacetate (and β-hydroxybutyrate), produced when acetyl-CoA exceeds TCA capacity.", optExp: ["Glucose breakdown does not directly form ketones.",null,"Lactate is recycled via Cori cycle.","Ketogenic amino acids contribute via acetyl-CoA.","Pyruvate must first become acetyl-CoA."] },
  { id:86, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which is NOT a ketone body?", opts:["Acetoacetate","β-hydroxybutyrate","Acetone","Pyruvate","All of the above are ketone bodies"], ans:3, exp:"The three ketone bodies are acetoacetate, β-hydroxybutyrate and acetone. Pyruvate is not a ketone body.", optExp: ["Acetoacetate is a ketone body.","β-OH-butyrate is the most abundant in DKA.","Acetone gives the breath smell in DKA.",null,"Pyruvate is NOT a ketone body."] },
  { id:87, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"During lipolysis in adipose tissue, triacylglycerols are broken into:", opts:["Pyruvate and glucose","Glycerol and free fatty acids","Cholesterol and bile salts","Amino acids and glucose","Acetyl-CoA only"], ans:1, exp:"Hormone-sensitive lipase hydrolyses TAGs into glycerol and free fatty acids, which are released into blood.", optExp: ["No pyruvate or glucose produced here.",null,"Cholesterol is unrelated to TAG breakdown.","Amino acids are from protein.","Acetyl-CoA forms later in mitochondria."] },
  { id:88, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In adipose tissue, glycerol released from TAG breakdown is used in the liver for:", opts:["Beta-oxidation","Gluconeogenesis","Glycogen synthesis only","Cholesterol synthesis","Bile acid synthesis"], ans:1, exp:"Glycerol enters gluconeogenesis via glycerol kinase → glycerol-3-P → DHAP, contributing to blood glucose during fasting.", optExp: ["Glycerol is not a fatty acid.",null,"Glycogen synthesis happens after glucose is made.","Cholesterol uses acetyl-CoA.","Bile acids come from cholesterol."] },
  { id:89, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Each fatty acid carbon yields more energy than each glucose carbon because:", opts:["Fatty acids contain more carbons per molecule","Fatty acids are more reduced than carbohydrates","Fatty acids bypass the electron transport chain","Fatty acids enter glycolysis directly","Fatty acids contain more oxygen atoms"], ans:1, exp:"Fatty acid carbons are highly reduced, so beta-oxidation generates many more NADH/FADH₂ per carbon.", optExp: ["Length alone is not the reason — it's per gram efficiency.",null,"Fatty acids feed INTO the ETC, not skip it.","They do not enter glycolysis.","They are largely OXYGEN-poor compared to carbohydrate."] },
  { id:90, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In uncontrolled type 1 diabetes leading to diabetic ketoacidosis (DKA), the metabolic state most resembles:", opts:["A fed metabolic state with high insulin levels","Severe starvation or prolonged fasting","Anaerobic exercise metabolism","Refeeding syndrome","Postprandial hyperinsulinaemia"], ans:1, exp:"DKA mimics fasting/starvation: cells cannot use glucose (no insulin), so beta-oxidation and ketogenesis run unchecked.", optExp: ["Insulin is absent in DKA, not high.",null,"Anaerobic exercise produces lactate, not ketones primarily.","Opposite condition.","Insulin is deficient, not high."] },
  { id:91, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many amino acids are commonly found in human proteins?", opts:["Four amino acids","Ten amino acids","Twenty amino acids","Twenty-six amino acids","Sixty-four amino acids"], ans:2, exp:"There are 20 standard amino acids encoded by the genetic code, with 9 considered essential in humans.", optExp: ["4 is the number of nucleotides in DNA.","Approximate number of essential amino acids.",null,"The alphabet has 26 letters, not amino acids.","64 is the number of codons (including stop)."] },
  { id:92, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The isoelectric point (pI) of an amino acid is the pH at which it:", opts:["It has maximum positive charge","It has maximum negative charge","It has zero net charge","It becomes most soluble in water","It reaches minimum solubility"], ans:2, exp:"At the pI, the amino acid exists as a zwitterion with no net charge — solubility is minimal and it does not migrate in an electric field.", optExp: ["Below pI it carries positive charge.","Above pI it carries negative charge.",null,"Solubility is actually minimal at pI.","While solubility is minimal, this is a consequence, not the definition."] },
  { id:93, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which amino acid is achiral?", opts:["Alanine","Glycine","Leucine","Valine","Serine"], ans:1, exp:"Glycine has two hydrogens on its α-carbon, making it the only achiral amino acid.", optExp: ["Has a methyl side chain — chiral.",null,"Branched side chain — chiral.","Branched side chain — chiral.","Hydroxyl side chain — chiral."] },
  { id:94, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which amino acid contains a thiol (-SH) group capable of forming disulfide bonds?", opts:["Methionine","Serine","Cysteine","Threonine","Tyrosine"], ans:2, exp:"Cysteine has a sulfhydryl (-SH) side chain that forms covalent disulfide bridges with other cysteines, stabilising protein structure.", optExp: ["Methionine has a thioether (S-CH₃), not a free -SH.","Serine has a hydroxyl.",null,"Threonine has a hydroxyl.","Tyrosine has an aromatic ring with hydroxyl."] },
  { id:95, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Normal arterial blood pH is approximately:", opts:["6.8","7.0","7.4","7.8","8.0"], ans:2, exp:"Arterial pH is tightly maintained at 7.35-7.45, averaging 7.40.", optExp: ["Severe acidosis — incompatible with life.","Neutral pH — outside biological range for blood.",null,"Severe alkalosis.","Far outside normal."] },
  { id:96, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The Henderson-Hasselbalch equation for the bicarbonate buffer is:", opts:["pH = pKa + log([HCO₃⁻]/[CO₂])","pH = pKa − log([HCO₃⁻]/[CO₂])","pH = pKa × [HCO₃⁻]","pH = [HCO₃⁻] − pCO₂","pH = log(pCO₂/[HCO₃⁻])"], ans:0, exp:"pH = pKa + log([conjugate base]/[weak acid]) = 6.1 + log([HCO₃⁻]/(0.03 × pCO₂)) for blood.", optExp: [null,"Wrong sign — should be addition.","No log; ratio matters.","Subtraction is incorrect.","Inverted ratio and missing pKa."] },
  { id:97, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which amino acid is positively charged at physiological pH?", opts:["Glutamate","Aspartate","Lysine","Serine","Phenylalanine"], ans:2, exp:"Lysine, arginine, and histidine have basic side chains with positive charges at pH 7.4 (histidine partially).", optExp: ["Glutamate is negatively charged (acidic).","Aspartate is negatively charged (acidic).",null,"Serine is neutral polar.","Phenylalanine is neutral aromatic."] },
  { id:98, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A buffer system functions best when:", opts:["When pH = pKa + 3","When pH is far from pKa","When pH = pKa","When pH = 7","When pKa = 0"], ans:2, exp:"Buffering capacity is maximal when pH = pKa, where [HA] = [A⁻] and the system resists pH changes most effectively.", optExp: ["Beyond effective buffer range.","Buffer is ineffective far from pKa.",null,"Only useful if pKa is near 7.","pKa near 0 means very strong acid — poor buffer."] },
  { id:99, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Essential amino acids are those that:", opts:["Required only during growth and development phases","Cannot be synthesized by the body and must be obtained from diet","Produced exclusively by the liver","Not incorporated into protein structures","Stored primarily in adipose tissue"], ans:1, exp:"Essential amino acids cannot be synthesised in adequate amounts and must be obtained from the diet. There are 9 essential amino acids in adults.", optExp: ["They are required throughout life, not just growth.",null,"They are dietary, not liver-produced.","They ARE used in protein synthesis.","Amino acids are not stored in adipose."] },
  { id:100, cat:"Amino Acids & pH", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A patient with severe vomiting develops which acid-base disturbance?", opts:["Metabolic acidosis","Metabolic alkalosis","Respiratory acidosis","Respiratory alkalosis","No change in acid-base balance"], ans:1, exp:"Loss of gastric HCl causes metabolic alkalosis (loss of H⁺).", optExp: ["Acidosis is typical of diarrhoea, not vomiting.",null,"Respiratory disorders are about CO₂.","Hyperventilation causes respiratory alkalosis.","There is a clear acid-base shift."] },
  { id:101, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which base pairs with adenine in DNA?", opts:["Cytosine","Guanine","Thymine","Uracil","Adenine"], ans:2, exp:"A pairs with T via 2 hydrogen bonds in DNA. In RNA, A pairs with U.", optExp: ["C pairs with G.","G pairs with C.",null,"U is in RNA, not DNA.","Bases don't self-pair in normal DNA."] },
  { id:102, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many hydrogen bonds form between G and C?", opts:["One hydrogen bond","Two hydrogen bonds","Three hydrogen bonds","Four hydrogen bonds","Five hydrogen bonds"], ans:2, exp:"G-C pairs form 3 H-bonds, making GC-rich regions more thermodynamically stable than AT-rich.", optExp: ["A-T has 2 H-bonds via 1 less; 1 is too few.","This is the A-T count.",null,"4 H-bonds not possible between these bases.","Exceeds possible H-bonds."] },
  { id:103, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"DNA replication is described as semiconservative because:", opts:["Each daughter DNA molecule has two new strands","Each daughter DNA molecule has one old and one new strand","DNA is conserved without any copying occurring","Only half of the DNA molecule is copied during replication","DNA replication occurs randomly rather than in a coordinated manner"], ans:1, exp:"Each new double helix contains one original strand serving as a template and one newly synthesised strand.", optExp: ["That would be conservative-like.",null,"Replication occurs each cell cycle.","All DNA is copied.","Replication is highly regulated."] },
  { id:104, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"DNA polymerase synthesises new DNA in which direction?", opts:["3' to 5' direction","5' to 3' direction","Both directions with equal frequency","Only on the lagging strand","In a random, non-directional manner"], ans:1, exp:"DNA polymerase adds new nucleotides to the 3' OH of the growing strand, so synthesis proceeds 5' → 3'.", optExp: ["This is the wrong direction.",null,"It always goes 5' → 3'.","Both strands are synthesised 5' → 3', just differently.","Synthesis is highly directional."] },
  { id:105, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme unwinds the DNA double helix at the replication fork?", opts:["DNA polymerase","Helicase","Ligase","Topoisomerase","Primase"], ans:1, exp:"Helicase breaks H-bonds between bases, unwinding the parental DNA at the fork.", optExp: ["DNA pol synthesises new strand, doesn't unwind.",null,"Ligase joins Okazaki fragments.","Topoisomerase relieves supercoiling AHEAD of helicase.","Primase makes RNA primers."] },
  { id:106, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Okazaki fragments are joined by:", opts:["DNA polymerase I","DNA polymerase III","DNA ligase","Helicase","Topoisomerase"], ans:2, exp:"DNA ligase seals nicks between Okazaki fragments on the lagging strand by forming phosphodiester bonds.", optExp: ["DNA pol I removes RNA primers in prokaryotes.","Pol III synthesises strands.",null,"Helicase unwinds DNA.","Topoisomerase manages supercoiling."] },
  { id:107, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Telomerase is most active in which cell type?", opts:["Mature neurons","Stem cells and cancer cells","Mature erythrocytes","Mature cardiac myocytes","Differentiated skin keratinocytes"], ans:1, exp:"Telomerase adds repetitive TTAGGG sequences to chromosome ends, active in proliferative cells: stem cells, germline, and most cancers.", optExp: ["Neurons are largely post-mitotic.",null,"RBCs have no nucleus.","Cardiac cells have low turnover.","Differentiated keratinocytes lose telomerase activity."] },
  { id:108, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In transcription, RNA polymerase reads the DNA template in which direction?", opts:["3' to 5' direction","5' to 3' direction","Both directions equally","Only the sense strand","From the 3' poly-A tail"], ans:0, exp:"RNA polymerase reads the template strand 3' → 5' and synthesises RNA 5' → 3'.", optExp: [null,"This is the direction of RNA synthesis, not template reading.","Reading is unidirectional.","The template is the antisense strand.","No poly-A on DNA template."] },
  { id:109, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In eukaryotes, post-transcriptional modifications of mRNA include all EXCEPT:", opts:["5' capping of mRNA","3' polyadenylation of mRNA tail","Splicing to remove introns","Reverse transcription of mRNA to DNA","RNA editing of specific bases"], ans:3, exp:"Reverse transcription (RNA → DNA) is performed by retroviruses, NOT by eukaryotic cells during normal mRNA maturation.", optExp: ["5' cap protects mRNA.","Poly-A tail stabilises mRNA.","Splicing removes introns.",null,"RNA editing can occur (e.g. ApoB)."] },
  { id:110, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which of the following is found in RNA but not DNA?", opts:["Adenine","Thymine","Cytosine","Uracil","Guanine"], ans:3, exp:"RNA contains uracil instead of thymine. The sugar in RNA is ribose, not deoxyribose.", optExp: ["Adenine is in both.","Thymine is in DNA only.","Cytosine is in both.",null,"Guanine is in both."] },
  { id:111, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Primary protein structure refers to:", opts:["Linear sequence of amino acids","α-helices and β-sheets","Three-dimensional folding of a polypeptide","Assembly of multiple subunit chains","Disulfide bonds between cysteine residues"], ans:0, exp:"Primary structure is the linear sequence of amino acids joined by peptide bonds.", optExp: [null,"That is secondary structure.","That is tertiary structure.","That is quaternary structure.","Disulfide bonds stabilise tertiary structure."] },
  { id:112, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Secondary structure is stabilised mainly by:", opts:["Disulfide bonds between cysteine residues","Hydrogen bonds between backbone atoms","Hydrophobic interactions between side chains","Ionic bonds between charged side chains","Peptide bonds linking consecutive amino acids"], ans:1, exp:"α-helices and β-sheets are stabilised by H-bonds between backbone N-H and C=O groups.", optExp: ["Disulfide bonds stabilise tertiary.",null,"Hydrophobic interactions stabilise tertiary.","Ionic bonds also stabilise tertiary.","Peptide bonds form primary structure."] },
  { id:113, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Quaternary structure refers to:", opts:["Sequence of amino acids","Local folding into secondary motifs","Overall three-dimensional shape of a single polypeptide","Assembly of multiple polypeptide subunits","Disulfide bond network throughout the protein"], ans:3, exp:"Quaternary structure is the arrangement of two or more polypeptide subunits, e.g. haemoglobin (α2β2).", optExp: ["That is primary.","That is secondary.","That is tertiary.",null,"Disulfide bonds can stabilise but aren't quaternary by definition."] },
  { id:114, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which interaction is NOT typically involved in tertiary structure?", opts:["Hydrogen bonds between side chains","Disulfide bonds between cysteine residues","Hydrophobic interactions between nonpolar side chains","Peptide bonds between amino acids","Ionic interactions between charged side chains"], ans:3, exp:"Peptide bonds link primary structure residues. Tertiary structure relies on side-chain interactions (H-bonds, ionic, hydrophobic, disulfide).", optExp: ["These contribute to tertiary structure.","Disulfide bridges stabilise tertiary structure.","Hydrophobic interactions drive folding.",null,"Ionic interactions stabilise tertiary structure."] },
  { id:115, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Collagen's triple helix is unusual because it contains a high proportion of:", opts:["High cysteine content","High glycine and proline content","High lysine content","High tryptophan content","High methionine content"], ans:1, exp:"Collagen has a repeating Gly-X-Y motif (often Pro-Hyp), allowing tight triple helix packing.", optExp: ["Cysteine is rare in collagen.",null,"Lysine is involved in cross-linking but not the main composition.","Tryptophan is rare in collagen.","Methionine is rare."] },
  { id:116, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Denaturation of a protein involves:", opts:["Breaking peptide bonds","Loss of native three-dimensional structure","Loss of primary amino acid sequence","Synthesis of new amino acids","Complete hydrolysis of all bonds"], ans:1, exp:"Denaturation disrupts secondary/tertiary/quaternary structure (e.g. by heat, pH, urea) but leaves peptide bonds intact.", optExp: ["Hydrolysis breaks peptide bonds, not denaturation.",null,"Primary structure persists.","Denaturation doesn't synthesise.","That is hydrolysis."] },
  { id:117, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Haemoglobin demonstrates cooperative binding, shown as a:", opts:["Hyperbolic curve","Sigmoidal curve","Linear curve","Inverse curve","Step function"], ans:1, exp:"Haemoglobin's sigmoidal O₂ binding curve reflects positive cooperativity between its 4 subunits.", optExp: ["Myoglobin (1 subunit) shows hyperbolic binding.",null,"Not linear.","Not inverse.","Not a step function."] },
  { id:118, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Chaperones (e.g. HSP70) function to:", opts:["Catalysing peptide bond formation during translation","Assisting correct protein folding and preventing aggregation","Degrading misfolded proteins for disposal","Cleaving signal sequences from nascent proteins","Binding to mRNA molecules during translation"], ans:1, exp:"Chaperones prevent misfolding/aggregation and assist proper folding of nascent polypeptides.", optExp: ["Ribosomes catalyse peptide bond formation.",null,"Proteasomes degrade misfolded proteins.","Signal peptidases cleave signal sequences.","RNA-binding proteins are different."] },
  { id:119, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The α-helix is stabilised by H-bonds between:", opts:["Side chains of adjacent amino acid residues","Backbone carbonyl (C=O) and amide (N-H) groups","Backbone atoms and surrounding water molecules","Disulfide bridges between cysteine residues","Peptide bonds connecting adjacent amino acids"], ans:1, exp:"In an α-helix, each backbone C=O H-bonds with the N-H of the residue 4 amino acids ahead.", optExp: ["Side chains can have interactions but aren't the main α-helix bond.",null,"Water is excluded from inside an α-helix.","Disulfides are not α-helix-specific.","Peptide bonds are covalent, not H-bonds."] },
  { id:120, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In a globular protein, hydrophobic residues are typically found:", opts:["On the protein surface in contact with water","In the hydrophobic core of the protein","Concentrated within the active site","Only found in signal peptide sequences","Primarily involved in forming disulfide bonds"], ans:1, exp:"Hydrophobic residues cluster in the protein interior, away from water, driving folding via the hydrophobic effect.", optExp: ["Surface is mostly hydrophilic.",null,"Active sites can be either; not 'hydrophobic only'.","Signal peptides have specific motifs.","Disulfide bonds use cysteines."] },
  { id:121, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In eukaryotes, gene transcription is initiated when RNA polymerase II binds to:", opts:["Origin of replication","Promoter region upstream of the gene","Terminator sequence at the gene end","Centromere of the chromosome","Telomere at the chromosome end"], ans:1, exp:"RNA Pol II binds the promoter (with help of general transcription factors) to initiate mRNA synthesis.", optExp: ["Origins are for DNA replication.",null,"Terminator ends transcription.","Centromeres bind kinetochores.","Telomeres protect chromosome ends."] },
  { id:122, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The TATA box is found in the:", opts:["In the 3' untranslated region","In the promoter region upstream of the gene","In the protein-coding region","Within intron sequences","Near the poly-A tail of mRNA"], ans:1, exp:"The TATA box is a core promoter element ~25-30 bp upstream of the start site, bound by TBP.", optExp: ["3' UTR is downstream.",null,"It's outside coding region.","TATA box is in promoter, not introns.","Poly-A is at the end of mRNA."] },
  { id:123, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Enhancer sequences regulate transcription by:", opts:["Binding to ribosomes to regulate translation","Binding transcription factors and looping DNA to increase transcription","Blocking RNA polymerase II activity","Cleaving and processing mRNA molecules","Adding poly-A tails to mRNA"], ans:1, exp:"Enhancers bind transcription factor activators; the DNA loops to bring them near the promoter, increasing transcription.", optExp: ["Ribosomes don't bind DNA.",null,"Silencers (not enhancers) block.","mRNA cleavage is a different process.","Poly-A is added in nucleus by polyA polymerase."] },
  { id:124, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Histone acetylation generally:", opts:["Tightens chromatin structure, leading to gene silencing","Loosens chromatin structure, leading to gene activation","Marks DNA for degradation","Triggers DNA replication initiation","Has no significant effect on gene expression"], ans:1, exp:"Acetylation of histone lysines neutralises positive charges, loosening DNA-histone interaction → euchromatin → transcriptionally active.", optExp: ["Deacetylation tightens chromatin.",null,"Acetylation does not target degradation.","Replication is regulated by different complexes.","Acetylation has clear effects."] },
  { id:125, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"DNA methylation (typically on CpG islands) usually:", opts:["Increases transcription of the affected gene","Silences gene expression","Causes point mutations in the DNA sequence","Marks the centromere for chromosome segregation","Increases translation of mRNA"], ans:1, exp:"Methylation of cytosines in CpG islands recruits repressors and condenses chromatin, silencing genes.", optExp: ["Methylation silences, doesn't activate.",null,"Methylation regulates rather than directly mutates.","Centromeres have other marks.","DNA methylation affects transcription, not translation."] },
  { id:126, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In which step of gene expression do introns get removed?", opts:["During transcription initiation","During RNA splicing in the nucleus","During translation in the cytoplasm","During DNA replication","During post-translational modification"], ans:1, exp:"Spliceosomes remove introns from pre-mRNA in the nucleus before mature mRNA is exported.", optExp: ["Initiation just starts RNA synthesis.",null,"Introns are removed before mRNA leaves the nucleus.","DNA is not edited like this.","Splicing is RNA-level, not protein."] },
  { id:127, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"How many nucleotides make up a codon?", opts:["1 nucleotide","2 nucleotides","3 nucleotides","4 nucleotides","5 nucleotides"], ans:2, exp:"A codon is a triplet of nucleotides specifying one amino acid (4³ = 64 possible codons).", optExp: ["A single nucleotide cannot specify 20 amino acids.","4² = 16, too few for 20 amino acids.",null,"4 nucleotides would yield 256 codons — more than needed.","Even more than needed."] },
  { id:128, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The start codon in eukaryotes is:", opts:["UAA (stop codon)","UAG (stop codon)","UGA (stop codon)","AUG (start codon)","GUG (alternative start codon)"], ans:3, exp:"AUG codes for methionine and is the initiation codon for translation in eukaryotes.", optExp: ["UAA is a stop codon.","UAG is a stop codon.","UGA is a stop codon.",null,"GUG is a start codon in prokaryotes, but AUG is standard eukaryotic start."] },
  { id:129, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which of the following is NOT a stop codon?", opts:["UAA","UAG","UGA","AUG","All of UAA, UAG, and UGA are stop codons"], ans:3, exp:"AUG is the START codon. Stop codons are UAA, UAG, UGA.", optExp: ["UAA is a stop codon.","UAG is a stop codon.","UGA is a stop codon.",null,"This is correct as a statement."] },
  { id:130, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"tRNAs carry their amino acid attached to:", opts:["The 5' end of the tRNA molecule","The anticodon loop region","The 3' CCA end of the tRNA","The D arm of the tRNA","The T arm of the tRNA"], ans:2, exp:"Amino acids are esterified to the 3' CCA terminus of tRNA via aminoacyl-tRNA synthetases.", optExp: ["The 5' end is phosphorylated.","Anticodon binds mRNA, doesn't carry amino acid.",null,"D arm binds activating enzyme.","T arm binds ribosome."] },
  { id:131, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"During translation elongation, the incoming aminoacyl-tRNA binds which ribosomal site?", opts:["A site","P site","E site","G site","D site"], ans:0, exp:"Incoming aminoacyl-tRNAs enter the A (aminoacyl) site; the growing peptide moves from P to A.", optExp: [null,"The P site holds the growing peptide chain.","E site is exit.","T site is not a ribosomal site.","Not a ribosomal site."] },
  { id:132, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Peptide bond formation in the ribosome is catalysed by:", opts:["Aminoacyl-tRNA synthetase enzyme","Peptidyl transferase activity in ribosomal rRNA","DNA polymerase enzyme","Helicase enzyme activity","Release factor protein"], ans:1, exp:"Peptidyl transferase activity is a ribozyme (catalytic RNA) in the large ribosomal subunit.", optExp: ["This charges tRNA with amino acid.",null,"DNA pol synthesises DNA.","Helicase unwinds DNA.","Release factor terminates translation."] },
  { id:133, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The genetic code is described as 'degenerate' because:", opts:["Each codon specifies multiple amino acids","Multiple codons encode the same amino acid","Some codons are skipped during translation","The genetic code differs between prokaryotes and eukaryotes","Codons overlap with each other on mRNA"], ans:1, exp:"Most amino acids are encoded by more than one codon, due to wobble base-pairing at the third position.", optExp: ["One codon → one amino acid (unambiguous).",null,"Codons are read sequentially without skipping.","The code is nearly universal.","Codons do NOT overlap."] },
  { id:134, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Polypeptide synthesis proceeds from:", opts:["C-terminus to N-terminus direction","N-terminus to C-terminus direction","Middle outward in both directions","Random order without directional sequence","3' to 5' direction on mRNA strand"], ans:1, exp:"Translation grows the polypeptide from N-terminus to C-terminus while mRNA is read 5' to 3'.", optExp: ["Opposite direction.",null,"Synthesis is sequential.","Highly ordered process.","mRNA is read 5'→3'."] },
  { id:135, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Post-translational modifications include all EXCEPT:", opts:["Phosphorylation of proteins","Glycosylation of proteins","Proteolytic cleavage of proteins","Reverse transcription of mRNA","Ubiquitination of proteins"], ans:3, exp:"Reverse transcription generates DNA from RNA — it is not a post-translational protein modification.", optExp: ["A common reversible PTM.","Adds sugar chains in ER/Golgi.","Activates pro-proteins (e.g. insulin).",null,"Tags proteins for proteasomal degradation."] },
  { id:136, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which enzyme is most specific for myocardial infarction in the first 6 hours?", opts:["Aspartate aminotransferase (AST)","Alanine aminotransferase (ALT)","Cardiac troponin I","Alkaline phosphatase","Pancreatic amylase"], ans:2, exp:"Cardiac troponin I (and T) is the gold-standard cardiac-specific marker, rising 3-6 hours post-MI and lasting up to 10-14 days.", optExp: ["AST is non-specific (liver/muscle).","ALT is liver-specific.",null,"ALP is liver/bone.","Amylase points to pancreatitis."] },
  { id:137, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In acute pancreatitis, which enzyme is most elevated?", opts:["Alanine aminotransferase (ALT) elevation","Alkaline phosphatase (ALP) elevation","Serum amylase and lipase elevation","Cardiac troponin elevation","Creatine kinase elevation"], ans:2, exp:"Serum amylase and lipase rise rapidly in acute pancreatitis. Lipase is more specific and persists longer.", optExp: ["ALT is for liver injury.","ALP is for liver/bone.",null,"Troponin is for cardiac.","CK is for muscle/heart, less specific."] },
  { id:138, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In hepatocellular injury, which liver enzyme is most specific?", opts:["Alkaline phosphatase (ALP)","Gamma-glutamyl transferase (GGT)","Alanine aminotransferase (ALT)","Pancreatic amylase","Creatine kinase (CK)"], ans:2, exp:"ALT is found predominantly in hepatocytes — the most specific marker for hepatocellular injury.", optExp: ["ALP is more cholestatic/bone.","GGT confirms hepatic origin of ALP but not most specific itself.",null,"Amylase is pancreatic.","CK is muscle."] },
  { id:139, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"HbA1c reflects average blood glucose over approximately:", opts:["One day of average blood glucose","One week of average blood glucose","Two to three months of average blood glucose","Six months of average blood glucose","One year of average blood glucose"], ans:2, exp:"HbA1c reflects glycation of haemoglobin over ~2-3 months (the lifespan of red cells).", optExp: ["Fasting glucose reflects 1 day.","Fructosamine reflects ~2-3 weeks.",null,"RBC lifespan is ~120 days.","Far too long."] },
  { id:140, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A raised anion gap metabolic acidosis can be caused by all EXCEPT:", opts:["Lactic acidosis","Diabetic ketoacidosis","Salicylate poisoning","Diarrhoea with bicarbonate loss","Methanol poisoning"], ans:3, exp:"Diarrhoea causes a NORMAL anion gap metabolic acidosis (bicarbonate loss). The others add unmeasured anions.", optExp: ["Lactate adds anions.","Ketones add anions.","Salicylate metabolites add anions.",null,"Methanol → formate."] },
  { id:141, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In phenylketonuria (PKU), the deficient enzyme is:", opts:["Tyrosinase deficiency","Phenylalanine hydroxylase deficiency","Homogentisate oxidase deficiency","Cystathionine synthase deficiency","Branched-chain α-keto acid dehydrogenase deficiency"], ans:1, exp:"PKU is an autosomal recessive disorder of phenylalanine hydroxylase, leading to phenylalanine accumulation and intellectual disability if untreated.", optExp: ["Tyrosinase deficiency causes albinism.",null,"Homogentisate deficiency causes alkaptonuria.","Cystathionine deficiency causes homocystinuria.","BCKD deficiency causes maple syrup urine disease."] },
  { id:142, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In G6PD deficiency, oxidative haemolysis occurs because:", opts:["Cannot synthesise haemoglobin","Cannot regenerate reduced glutathione via NADPH","Cannot produce adenosine triphosphate (ATP)","Cannot bind oxygen to iron","Cannot tolerate free iron exposure"], ans:1, exp:"G6PD generates NADPH via the pentose phosphate pathway, needed to regenerate reduced glutathione and protect RBCs from oxidative damage.", optExp: ["Haemoglobin synthesis is unaffected.",null,"ATP levels are largely unaffected.","Oxygen binding is intact.","Iron contact isn't the trigger."] },
  { id:143, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Jaundice with predominantly conjugated hyperbilirubinaemia suggests:", opts:["Haemolysis with unconjugated hyperbilirubinaemia","Gilbert syndrome with mild unconjugated hyperbilirubinaemia","Biliary obstruction or cholestasis","Crigler-Najjar syndrome","Newborn physiological jaundice"], ans:2, exp:"Conjugated bilirubin elevation suggests cholestasis/post-hepatic obstruction (stones, tumour, stricture).", optExp: ["Haemolysis raises unconjugated.","Gilbert is unconjugated.",null,"Crigler-Najjar is unconjugated.","Physiological jaundice is unconjugated."] },
  { id:144, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In hypoglycaemia, which counter-regulatory hormone is released first?", opts:["Cortisol from adrenal cortex","Glucagon from pancreatic alpha cells","Growth hormone from anterior pituitary","Insulin from pancreatic beta cells","Thyroxine from thyroid gland"], ans:1, exp:"Glucagon is the first-line counter-regulator, rapidly mobilising hepatic glucose via glycogenolysis and gluconeogenesis. Adrenaline also rises quickly.", optExp: ["Cortisol acts later in chronic hypoglycaemia.",null,"GH is a slower responder.","Insulin would WORSEN hypoglycaemia.","Thyroxine is not a rapid responder."] },
  { id:145, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Which of the following best indicates renal function?", opts:["Alanine aminotransferase (ALT) levels","Creatinine and estimated glomerular filtration rate (eGFR)","Bilirubin levels","Pancreatic amylase levels","Cardiac troponin levels"], ans:1, exp:"Creatinine and eGFR are the standard markers of renal function. Urea is also used but is more variable.", optExp: ["ALT is for liver.",null,"Bilirubin is for liver/haemolysis.","Amylase is for pancreas.","Troponin is for heart."] },
  { id:146, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"How many chromosomes are in a normal human somatic cell?", opts:["23","44","46","48","92"], ans:2, exp:"Human somatic cells are diploid with 46 chromosomes (22 autosome pairs + XX/XY).", optExp: ["23 is the haploid number (gametes).","Only autosomes counted; sex chromosomes excluded incorrectly.",null,"Number for great apes.","92 would be tetraploid."] },
  { id:147, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"Approximately how many protein-coding genes does the human genome contain?", opts:["Approximately two thousand five hundred","Approximately ten thousand genes","Approximately twenty to twenty-five thousand genes","Approximately two hundred fifty thousand genes","Approximately three million genes"], ans:2, exp:"Recent estimates place protein-coding genes at ~20,000-25,000 across 46 chromosomes.", optExp: ["Too few.","Too few.",null,"Vastly overestimates.","That's roughly the number of SNPs in some studies, not genes."] },
  { id:148, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"The centromere of a chromosome is the:", opts:["Tip of a chromosome arm","Constricted region where spindle fibres attach","Site of DNA replication origin","Repetitive sequence at the chromosome terminus","Site of gene activation during transcription"], ans:1, exp:"The centromere is the constricted region where the kinetochore assembles for spindle fibre attachment during mitosis/meiosis.", optExp: ["Tips are telomeres.",null,"Origins of replication are scattered.","Telomeres are at chromosome ends.","Gene activation occurs throughout."] },
  { id:149, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"Telomeres are:", opts:["Repetitive sequences at chromosome ends","Spindle fibre attachment points at the centromere","Sites of mRNA transcription initiation","Mitochondrial DNA structural elements","Histone modification marks on chromatin"], ans:0, exp:"Telomeres (TTAGGG repeats) cap chromosome ends, preventing end-joining and degradation. They shorten with each division.", optExp: [null,"That is the centromere.","Telomeres are gene-poor.","Telomeres are nuclear, not mitochondrial.","They are DNA sequences, not modifications."] },
  { id:150, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"A karyotype of 47,XXY corresponds to:", opts:["Turner syndrome presentation","Klinefelter syndrome presentation","Down syndrome presentation","Patau syndrome presentation","Edwards syndrome presentation"], ans:1, exp:"Klinefelter syndrome (47,XXY) — phenotypically male with hypogonadism, gynaecomastia, tall stature.", optExp: ["Turner is 45,X.",null,"Down is trisomy 21.","Patau is trisomy 13.","Edwards is trisomy 18."] },
  { id:151, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"Heterochromatin refers to:", opts:["Loose transcriptionally active chromatin","Condensed transcriptionally silent chromatin","RNA-DNA hybrid duplex structure","Single-stranded DNA molecules","Histone-free DNA regions"], ans:1, exp:"Heterochromatin is densely packed and transcriptionally silent. Euchromatin is loose and active.", optExp: ["That is euchromatin.",null,"Not RNA-DNA hybrid.","Heterochromatin is double-stranded.","Histones are present (often hypoacetylated)."] },
  { id:152, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"The 5 histones include H2A, H2B, H3, H4 and:", opts:["H0 histone protein","H1 linker histone protein","H5 histone protein","HSP70 heat shock protein","H-box histone protein"], ans:1, exp:"H1 is the linker histone that binds DNA between nucleosomes, stabilising the 30-nm chromatin fibre.", optExp: ["Not a histone designation.",null,"H5 is avian; not standard mammalian.","HSP70 is a chaperone.","Not a histone."] },
  { id:153, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which of the following is mitochondrially inherited?", opts:["Cystic fibrosis inheritance pattern","Huntington disease inheritance pattern","Leber hereditary optic neuropathy","Sickle cell anaemia inheritance pattern","Duchenne muscular dystrophy"], ans:2, exp:"LHON results from mitochondrial DNA mutations, inherited maternally from the egg's mitochondria.", optExp: ["CF is autosomal recessive.","Huntington is autosomal dominant.",null,"Sickle cell is autosomal recessive.","DMD is X-linked recessive."] },
  { id:154, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"In genomic terms, an exon is a:", opts:["Non-coding sequence removed during RNA processing","Coding sequence retained in mature mRNA","Promoter element located upstream of the gene","Repetitive telomeric element at chromosome end","Mitochondrial gene sequence"], ans:1, exp:"Exons are retained in mature mRNA and translated. Introns are spliced out.", optExp: ["That is an intron.",null,"Promoters are regulatory regions.","Repetitive telomeric elements are different.","Exons are nuclear DNA."] },
  { id:155, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"What percentage of the human genome encodes proteins?", opts:["1-2%","5%","25%","50%","Over 90%"], ans:0, exp:"Only ~1-2% of the genome encodes proteins. The rest includes regulatory, structural, and non-coding RNAs.", optExp: [null,"Too high.","Greatly overestimates.","Way too high.","Most of the genome is non-coding."] },
  { id:156, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"A point mutation that changes a single nucleotide but does NOT alter the amino acid is called:", opts:["Missense mutation","Silent mutation","Nonsense mutation","Frameshift mutation","Chromosomal inversion"], ans:1, exp:"Silent mutations exploit the degeneracy of the genetic code — different codons encode the same amino acid.", optExp: ["Missense changes the amino acid.",null,"Nonsense creates a premature stop.","Frameshift = insertion/deletion not a multiple of 3.","Inversion involves segment flipping."] },
  { id:157, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"A point mutation creating a premature stop codon is:", opts:["Silent mutation","Missense mutation","Nonsense mutation","Frameshift mutation","Splice site mutation"], ans:2, exp:"Nonsense mutations introduce a stop codon (UAA, UAG, UGA), truncating the protein.", optExp: ["Silent preserves amino acid.","Missense changes amino acid.",null,"Frameshift = insertion/deletion.","Splice site disrupts intron/exon boundary."] },
  { id:158, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"A single nucleotide insertion in a coding region is most likely to cause:", opts:["Silent mutation with no phenotypic effect","Frameshift mutation disrupting the reading frame","Synonymous mutation preserving the amino acid","Conservative substitution of a similar amino acid","Chromosomal translocation event"], ans:1, exp:"Inserting one base shifts the reading frame downstream, drastically altering the protein.", optExp: ["Insertions of one base are not silent.",null,"Synonymous means same amino acid.","Not a substitution at all.","Translocation involves chromosome segments."] },
  { id:159, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Sickle cell anaemia results from which mutation?", opts:["Deletion of exon five","Single missense mutation in the β-globin gene","Trinucleotide repeat expansion","Frameshift mutation in the α-globin gene","Promoter SNP reducing transcription"], ans:1, exp:"A single missense substitution (Glu6Val) in β-globin produces HbS, which polymerises under low O₂, sickling RBCs.", optExp: ["Not a deletion.",null,"Not a trinucleotide repeat disease.","α-globin is unaffected; β-globin is altered.","Coding, not promoter, change."] },
  { id:160, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Trinucleotide repeat expansion is the mechanism of:", opts:["Cystic fibrosis","Huntington disease","Sickle cell anaemia","Marfan syndrome","Familial hypercholesterolaemia"], ans:1, exp:"Huntington disease is caused by CAG repeat expansion in the HTT gene, with anticipation in subsequent generations.", optExp: ["CF is a deletion (ΔF508 most common).",null,"Sickle cell is a missense.","Marfan is FBN1 missense/loss.","FH is LDL receptor mutations."] },
  { id:161, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Genetic anticipation describes:", opts:["Disease skips generations","Disease occurring earlier and with greater severity in successive generations","Disease occurring after age fifty","Mitochondrial inheritance pattern","Sex-limited inheritance pattern"], ans:1, exp:"Trinucleotide repeat disorders (e.g. myotonic dystrophy, Huntington) typically show anticipation due to repeat expansion in gametes.", optExp: ["Skipping generations is not anticipation.",null,"Onset varies, not always late.","Mitochondrial is its own pattern.","Sex-limited is different (e.g. premature ovarian failure)."] },
  { id:162, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Cystic fibrosis is caused by mutations in:", opts:["CFTR chloride channel gene","Dystrophin gene","Haemoglobin β-chain gene","FBN1 fibrillin gene","HTT huntingtin gene"], ans:0, exp:"CFTR mutations (most commonly ΔF508) disrupt chloride transport, causing thick mucus in lungs, pancreas, gut.", optExp: [null,"Dystrophin is in DMD.","β-globin is in sickle cell/thalassaemia.","FBN1 is in Marfan.","HTT is in Huntington."] },
  { id:163, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Translocation refers to:", opts:["Base substitution mutation","Base deletion mutation","DNA segment movement between chromosomes","Chromosome inversion","Chromosome duplication event"], ans:2, exp:"Translocation occurs when a chromosomal segment breaks off and reattaches to a different chromosome (e.g. BCR-ABL in CML).", optExp: ["That is a point mutation.","That is a deletion.",null,"That is inversion.","That is duplication/trisomy."] },
  { id:164, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which type of mutation results in the production of a polypeptide of altered length most directly?", opts:["Silent mutation","Conservative missense mutation","Nonsense or frameshift mutation","Synonymous mutation","Promoter substitution mutation"], ans:2, exp:"Nonsense (premature stop) and frameshift mutations alter the polypeptide length most directly.", optExp: ["Silent does not change protein.","Length still preserved.",null,"Synonymous = silent.","Promoter affects amount, not length."] },
  { id:165, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Loss-of-function mutations are typically:", opts:["Dominant","Recessive","X-linked dominant","Mitochondrial","Imprinted"], ans:1, exp:"Loss of function usually requires both copies to be defective — recessive inheritance. Gain of function is typically dominant.", optExp: ["GoF mutations are typically dominant.",null,"Not necessarily X-linked.","Not necessarily mitochondrial.","Imprinting is separate."] },
  { id:166, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which is an autosomal DOMINANT condition?", opts:["Cystic fibrosis","Sickle cell anaemia","Huntington disease","Phenylketonuria","Tay-Sachs disease"], ans:2, exp:"Huntington disease is autosomal dominant — one mutant copy of HTT (with expanded CAG repeats) causes disease.", optExp: ["CF is autosomal recessive.","Sickle cell is autosomal recessive.",null,"PKU is autosomal recessive.","Tay-Sachs is autosomal recessive."] },
  { id:167, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which is an X-linked recessive condition?", opts:["Marfan syndrome","Achondroplasia","Duchenne muscular dystrophy","Down syndrome","Cystic fibrosis"], ans:2, exp:"DMD is X-linked recessive — males (XY) with one mutant dystrophin allele are affected.", optExp: ["Marfan is autosomal dominant.","Achondroplasia is autosomal dominant.",null,"Down is trisomy 21 (chromosomal).","CF is autosomal recessive."] },
  { id:168, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which pattern of inheritance never shows male-to-male transmission?", opts:["Autosomal dominant","Autosomal recessive","X-linked inheritance","Mitochondrial inheritance","Codominant inheritance"], ans:2, exp:"X-linked traits cannot pass father-to-son because fathers give the Y, not X, to sons. Mitochondrial is also non-male transmitted.", optExp: ["Can show father-to-son.","Can show father-to-son.",null,"Mitochondrial is exclusively maternal — also fits, but X-linked is the classic answer.","Codominance is independent of sex."] },
  { id:169, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Two heterozygous carriers of an autosomal recessive disease have what risk per child of an affected offspring?", opts:["0%","25%","33%","50%","100%"], ans:1, exp:"Aa × Aa cross: 25% AA (unaffected), 50% Aa (carrier), 25% aa (affected).", optExp: ["This is the probability if neither carry.",null,"33% would be if focusing only on non-AA.","50% is the carrier frequency.","100% would only be if both are affected."] },
  { id:170, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"An affected father with an autosomal dominant condition has what chance of an affected child (heterozygote × normal)?", opts:["25%","50%","75%","100%","0%"], ans:1, exp:"Aa × aa = 50% Aa (affected), 50% aa (normal).", optExp: ["25% is the autosomal recessive carrier × carrier ratio.",null,"75% is more than expected.","100% would be Aa × Aa with full penetrance + lethality of aa.","0% impossible with affected parent."] },
  { id:171, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Mitochondrial inheritance is characterised by:", opts:["Equal transmission from both parents","Exclusively maternal transmission","Only male-to-male transmission","Skipping generations pattern","X-linked inheritance pattern"], ans:1, exp:"Mitochondrial DNA comes from the egg, so mothers pass mitochondrial diseases to all children; affected fathers do not transmit.", optExp: ["Father contributes minimal mtDNA.",null,"Opposite of true pattern.","Generally does not skip; depends on heteroplasmy.","Mitochondrial is its own pattern."] },
  { id:172, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Penetrance refers to:", opts:["Severity of phenotype in affected individuals","Proportion of genotype carriers showing the phenotype","Whether the trait is dominant or recessive","Strength of natural selection pressure","Mutation rate in a population"], ans:1, exp:"Penetrance = % of individuals with a disease-causing genotype who actually express it. Expressivity = how SEVERELY they express.", optExp: ["That is expressivity.",null,"Dominance is a separate concept.","Selection is different.","Mutation rate is unrelated."] },
  { id:173, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Uniparental disomy gives rise to which of the following?", opts:["Turner syndrome","Trisomy 21","Prader-Willi or Angelman syndrome","Klinefelter syndrome","Triploidy"], ans:2, exp:"Both copies of chromosome 15 from one parent: paternal duplication → Prader-Willi; maternal → Angelman (due to imprinting).", optExp: ["45,X is monosomy X.","Trisomy 21 is nondisjunction.",null,"47,XXY is nondisjunction of X.","Triploidy is dispermy or diploid gamete."] },
  { id:174, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Genomic imprinting means:", opts:["Expression of only the paternal or maternal allele","Both alleles expressed equally","Expression only in brain tissue","Gene sequence changing with each generation","Mutations always inherited from parents"], ans:0, exp:"Imprinted genes are expressed monoallelically depending on parental origin (DNA methylation 'remembers' which parent).", optExp: [null,"That is biallelic expression (normal).","Imprinting is not tissue-restricted.","Imprinting is epigenetic.","Imprinting is not about new mutations."] },
  { id:175, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Heterozygote advantage explains why which disease persists in some populations?", opts:["Huntington disease","Sickle cell disease in malaria-endemic regions","Down syndrome","Klinefelter syndrome","Turner syndrome"], ans:1, exp:"Some recessive diseases (e.g. sickle cell vs malaria, possibly CF vs cholera/TB) persist because heterozygotes have a survival advantage.", optExp: ["Huntington has no heterozygote advantage.",null,"Down is chromosomal nondisjunction.","Klinefelter is sex chromosome anomaly.","Turner is sex chromosome anomaly."] },
  { id:176, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"In which phase of mitosis do chromosomes align at the metaphase plate?", opts:["Prophase","Metaphase","Anaphase","Telophase","Cytokinesis"], ans:1, exp:"During metaphase, chromosomes line up in the middle of the cell with sister chromatids attached to spindle fibres.", optExp: ["Prophase = condensation and spindle formation.",null,"Anaphase = sister chromatids separate.","Telophase = nuclear membranes reform.","Cytokinesis = cell division."] },
  { id:177, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Sister chromatids separate to opposite poles in:", opts:["Prophase","Metaphase","Anaphase","Telophase","Interphase"], ans:2, exp:"Anaphase: centromeres split, sister chromatids are pulled apart by shortening spindle fibres.", optExp: ["Prophase = condensation.","Metaphase = alignment.",null,"Telophase = membranes reform.","Interphase = growth/replication."] },
  { id:178, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"DNA replication occurs during:", opts:["G1 phase","S phase","G2 phase","M phase","G0 phase"], ans:1, exp:"S (synthesis) phase of interphase is when DNA is replicated.", optExp: ["G1 is growth before replication.",null,"G2 is preparation for mitosis.","M is mitosis itself.","G0 is quiescent state."] },
  { id:179, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Which checkpoint protein halts the cell cycle at G1 in response to DNA damage?", opts:["BRCA1","p53","Cyclin D","Bcl-2","Retinoblastoma protein (Rb)"], ans:1, exp:"p53 ('guardian of the genome') arrests the cell at G1 to allow repair, or triggers apoptosis if damage is irreparable.", optExp: ["BRCA1 is involved in DNA repair, not checkpoint per se.",null,"Cyclin D promotes progression.","Bcl-2 prevents apoptosis.","Rb regulates G1/S but is downstream."] },
  { id:180, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Meiosis produces:", opts:["2 diploid daughter cells","4 haploid daughter cells","2 haploid identical cells","4 diploid daughter cells","1 polyploid cell"], ans:1, exp:"Meiosis I + II yield 4 haploid gametes, with genetic diversity from crossing over and independent assortment.", optExp: ["That is mitosis.",null,"Two haploid is only after meiosis I.","Diploid would not be a gamete.","Meiosis halves chromosome count."] },
  { id:181, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Crossing over occurs during which phase of meiosis?", opts:["Prophase I","Metaphase I","Anaphase I","Prophase II","Telophase II"], ans:0, exp:"Crossing over (recombination) occurs in prophase I (pachytene), generating genetic variation between homologous chromosomes.", optExp: [null,"Alignment of homologues, not recombination.","Separation of homologues.","No homologue pairing in meiosis II.","Late meiosis II, no recombination."] },
  { id:182, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Independent assortment of homologous chromosomes occurs in:", opts:["Anaphase I of meiosis","Anaphase II of meiosis","Mitotic anaphase","S phase of interphase","G2 phase of interphase"], ans:0, exp:"Independent assortment of HOMOLOGOUS chromosomes happens in meiosis I anaphase, contributing to genetic diversity.", optExp: [null,"Anaphase II separates SISTERS not homologues.","Mitotic anaphase doesn't involve homologue separation in this way.","S = replication.","G2 = preparation."] },
  { id:183, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"Nondisjunction in meiosis is the failure of:", opts:["Failure of DNA replication","Failure of chromosomes to separate","Failure of cytokinesis","Failure of nuclear membrane reformation","Failure of spindle assembly"], ans:1, exp:"Nondisjunction = failure of homologues (meiosis I) or sister chromatids (meiosis II) to separate, leading to aneuploidy (e.g. trisomy 21).", optExp: ["Replication is separate.",null,"Cytokinesis is cell separation, not chromosome separation.","Membrane reformation is telophase.","Spindle defects are different."] },
  { id:184, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"If p53 is mutated/non-functional, the result is:", opts:["DNA repair occurs more rapidly","Damaged cells continue dividing uncontrolled","Cells enter permanent growth arrest","Cells undergo immediate apoptosis","Cell cycle regulation remains normal"], ans:1, exp:"Without functional p53, damaged DNA isn't repaired or eliminated — cells with mutations replicate and may become cancerous.", optExp: ["Repair efficiency drops, not improves.",null,"Cells continue dividing.","Apoptosis is impaired.","p53 is a key regulator."] },
  { id:185, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"At the end of meiosis I, the daughter cells are:", opts:["Diploid with sister chromatids still joined","Haploid with sister chromatids still joined","Haploid with separated individual chromatids","Tetraploid with replicated chromosomes","Genetically identical to the parent cell"], ans:1, exp:"After meiosis I, each cell is haploid (n) but each chromosome still has 2 sister chromatids. Meiosis II separates these.", optExp: ["No longer diploid after meiosis I.",null,"Chromatids separate in meiosis II.","Not tetraploid.","Mitosis gives identical cells."] },
  { id:186, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"Epigenetic mechanisms affect gene expression without altering:", opts:["Histone protein modifications","DNA sequence composition","Transcription of genes","Cell phenotype and function","Protein folding patterns"], ans:1, exp:"Epigenetic changes (methylation, histone modifications) modify gene activity without changing the DNA sequence itself.", optExp: ["Histones ARE modified.",null,"Transcription IS affected.","Phenotype IS affected.","Folding is downstream and not the definition."] },
  { id:187, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"DNA methylation typically occurs at:", opts:["GG dinucleotide sequences","CpG dinucleotide sequences","AA dinucleotide sequences","TT dinucleotide sequences","Telomeric repeat sequences"], ans:1, exp:"In mammals, cytosines in CpG dinucleotides are the predominant target of DNA methylation, silencing genes.", optExp: ["Not the typical site.",null,"Not the typical site.","Not the typical site.","Telomeres have their own structure but methylation is CpG-targeted."] },
  { id:188, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"X-inactivation in females is mediated by:", opts:["Genomic imprinting genes alone","XIST long non-coding RNA","DNA polymerase enzyme activity","RNase enzyme activity","Telomerase enzyme activity"], ans:1, exp:"XIST RNA coats one X chromosome and recruits silencing machinery, forming a Barr body in females.", optExp: ["Imprinting is separate.",null,"DNA pol is for replication.","RNase degrades RNA.","Telomerase extends telomeres."] },
  { id:189, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"Histone acetylation tends to:", opts:["Silencing gene expression","Activating gene expression by loosening chromatin structure","Causing DNA strand breaks","Initiating programmed cell death","Inducing point mutations in DNA"], ans:1, exp:"Acetylation neutralises positive lysine charges on histone tails, loosening DNA wrapping → euchromatin → active transcription.", optExp: ["Deacetylation silences.",null,"Acetylation doesn't damage DNA.","No direct apoptosis trigger.","Doesn't cause mutations."] },
  { id:190, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"Imprinting disorders such as Prader-Willi and Angelman syndromes both involve chromosome:", opts:["Chromosome 7","Chromosome 11","Chromosome 15","Chromosome 18","Chromosome 21"], ans:2, exp:"Both result from deletion or uniparental disomy of chromosome 15q11-13 — paternal loss → Prader-Willi; maternal loss → Angelman.", optExp: ["CFTR is on 7 but not for these.","Beckwith-Wiedemann is on 11.",null,"Edwards is trisomy 18, unrelated.","Down is trisomy 21, unrelated."] },
  { id:191, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"The cell membrane is best described as a:", opts:["Rigid phospholipid wall","Fluid mosaic with proteins","Single cholesterol layer","DNA-protein matrix","Pure protein structure"], ans:1, exp:"Singer-Nicolson fluid mosaic model: phospholipid bilayer with proteins floating freely and asymmetrically.", optExp: ["Membranes are fluid, not rigid.",null,"Cholesterol is embedded but not the main structure.","DNA is nuclear.","Lipids form the structural framework."] },
  { id:192, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which of the following molecules crosses the lipid bilayer most easily by simple diffusion?", opts:["Glucose molecule","Na⁺ ion","Water molecule","O₂ small nonpolar molecule","Amino acid"], ans:3, exp:"Small, nonpolar molecules like O₂, CO₂, and N₂ diffuse easily through the bilayer. Water uses aquaporins.", optExp: ["Glucose uses facilitated diffusion.","Na⁺ requires channels/pumps.","Water uses aquaporins primarily.",null,"Amino acids use transporters."] },
  { id:193, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"The Na⁺/K⁺-ATPase pumps:", opts:["3 Na⁺ in, 2 K⁺ out","3 Na⁺ out, 2 K⁺ in","2 Na⁺ in, 3 K⁺ out","1 Na⁺ out, 1 K⁺ in","3 Ca²⁺ out, 2 Na⁺ in"], ans:1, exp:"Na⁺/K⁺-ATPase pumps 3 Na⁺ OUT and 2 K⁺ IN per ATP, maintaining electrochemical gradient and resting membrane potential.", optExp: ["Reversed direction.",null,"Reversed stoichiometry.","Stoichiometry wrong.","This is the Na⁺/Ca²⁺ exchanger pattern."] },
  { id:194, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Facilitated diffusion differs from active transport in that it:", opts:["Requires ATP energy to move substances across membrane","Moves substances against the concentration gradient","Does not require ATP energy and moves down concentration gradient","Uses channel proteins and moves against gradient","Requires hydrolysis of GTP molecules"], ans:2, exp:"Facilitated diffusion moves down the electrochemical gradient via channels or carriers; no ATP needed.", optExp: ["Active transport requires ATP.","Against gradient = active transport.",null,"Uses channels/carriers, not pumps.","Not water-specific."] },
  { id:195, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Osmosis is the movement of:", opts:["Movement of solutes from low to high concentration","Movement of solutes across the cell membrane","Movement of water across a semipermeable membrane toward higher solute concentration","Movement of ions through ion channels","Movement of glucose via carrier proteins"], ans:2, exp:"Osmosis = movement of water across a semipermeable membrane from low to high solute concentration (high to low water concentration).", optExp: ["Solutes don't move uphill in osmosis.","Phrased imprecisely; missing membrane.",null,"That is ion diffusion.","Carrier-mediated transport, not osmosis."] },
  { id:196, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"GLUT4 transports glucose into:", opts:["All cells in the body equally","Muscle and adipose tissue cells","Erythrocytes only","Neurons only","Liver cells only"], ans:1, exp:"GLUT4 is insulin-dependent and is the main glucose transporter in skeletal muscle and adipose tissue.", optExp: ["GLUT family is tissue-specific.",null,"GLUT1 is the RBC transporter.","GLUT3 is for neurons.","GLUT2 is for liver/β-cells."] },
  { id:197, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Tight junctions function to:", opts:["Anchoring cells to the extracellular matrix","Preventing paracellular transport between adjacent cells","Allowing ion passage between epithelial cells","Aiding muscle contraction","Binding cells to fibroblasts"], ans:1, exp:"Tight junctions seal cells together apically, blocking paracellular flow (e.g. blood-brain barrier, intestinal lining).", optExp: ["Hemidesmosomes anchor to ECM.",null,"Gap junctions allow ion passage.","Not the role of tight junctions.","Not their function."] },
  { id:198, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Cholesterol in the cell membrane:", opts:["Increases membrane fluidity at all temperatures","Decreases membrane fluidity at all temperatures","Modulates membrane fluidity based on temperature","Acts as a receptor protein on the membrane","Forms ion channels in the membrane"], ans:2, exp:"Cholesterol stabilises membrane fluidity: it prevents tight packing at low temperatures and excessive fluidity at high temperatures.", optExp: ["Cholesterol does not universally increase fluidity.","Cholesterol does not universally decrease fluidity.",null,"Not a receptor function.","Cholesterol does not form channels."] },
  { id:199, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"The resting membrane potential of a neuron is approximately:", opts:["+40 mV","+20 mV","−40 mV","−70 mV","−100 mV"], ans:3, exp:"Resting Vm is around −70 mV, established by Na⁺/K⁺-ATPase and K⁺ leak channels.", optExp: ["+40 mV is the peak of the AP.","0 mV is the reversal point.","−40 mV is closer to threshold.",null,"Too hyperpolarised for resting."] },
  { id:200, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Depolarisation during a neuronal action potential is due to:", opts:["Na⁺ influx through voltage-gated channels","K⁺ efflux through voltage-gated channels","Cl⁻ influx through voltage-gated channels","Ca²⁺ efflux through voltage-gated channels","Na⁺/K⁺-ATPase pump activation"], ans:0, exp:"At threshold (~−55 mV), voltage-gated Na⁺ channels open, Na⁺ rushes in, depolarising to +40 mV.", optExp: [null,"K⁺ efflux causes repolarisation.","Cl⁻ influx hyperpolarises.","Ca²⁺ is more relevant in cardiac.","Pump restores gradients but doesn't cause depolarisation."] },
  { id:201, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Repolarisation of the neuronal action potential is mainly due to:", opts:["K⁺ efflux through voltage-gated potassium channels","Na⁺ influx through voltage-gated sodium channels","Cl⁻ influx through voltage-gated chloride channels","Ca²⁺ influx through voltage-gated calcium channels","Inactivation of Na⁺/K⁺-ATPase pumps"], ans:0, exp:"Voltage-gated K⁺ channels open, K⁺ flows out, restoring negative membrane potential.", optExp: [null,"Na⁺ influx is depolarisation.","Cl⁻ influx is hyperpolarisation in some contexts.","Ca²⁺ is for cardiac plateau.","Pumps maintain but don't cause repolarisation."] },
  { id:202, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Hyperpolarisation after the AP is caused by:", opts:["K⁺ channels remaining open longer than needed","Na⁺ channels remaining open longer than needed","Cl⁻ exit from the cell","Ca²⁺ release from sarcoplasmic reticulum","Na⁺/K⁺-ATPase pump inactivation"], ans:0, exp:"K⁺ channels close slowly, leading to brief K⁺ efflux beyond resting Vm — the after-hyperpolarisation.", optExp: [null,"Na⁺ channels inactivate after depolarisation.","Cl⁻ flow is not the AHP mechanism.","Ca²⁺ release is more cardiac.","Pump activity stabilises Vm."] },
  { id:203, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Saltatory conduction occurs in:", opts:["Myelinated axons with nodes of Ranvier","Unmyelinated axons","Smooth muscle tissue","Cardiac muscle tissue","Neuronal cell bodies only"], ans:0, exp:"In myelinated axons, ion channels concentrate at Nodes of Ranvier; APs 'jump' node-to-node, greatly speeding conduction.", optExp: [null,"Unmyelinated have continuous slow conduction.","Smooth muscle uses different signalling.","Cardiac uses gap junctions.","Cell bodies don't propagate APs in this manner."] },
  { id:204, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"The absolute refractory period prevents:", opts:["Initiating another action potential regardless of stimulus strength","Opening of voltage-gated Na⁺ channels","Opening of voltage-gated K⁺ channels","Reaching threshold potential","Release of calcium from intracellular stores"], ans:1, exp:"During absolute refractory period, Na⁺ channels are inactivated and cannot reopen — no new AP can occur.", optExp: ["Na⁺ channels are inactivated specifically.",null,"K⁺ channels still function.","Threshold can be reached, but no AP fires due to Na⁺ channel state.","Calcium dynamics are separate."] },
  { id:205, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which phase of the cardiac action potential is due to L-type Ca²⁺ channel opening?", opts:["Phase 0 depolarisation","Phase 1 early repolarisation","Phase 2 plateau phase","Phase 3 repolarisation","Phase 4 resting membrane potential"], ans:2, exp:"Phase 2 (plateau) is sustained by Ca²⁺ influx through L-type channels, balanced by K⁺ efflux — unique to cardiac cells.", optExp: ["Phase 0 = Na⁺ influx.","Phase 1 = transient K⁺ efflux.",null,"Phase 3 = K⁺ efflux repolarisation.","Phase 4 = resting potential."] },
  { id:206, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Larger-diameter axons conduct action potentials:", opts:["Slower than small-diameter axons","Faster due to lower resistance","At the same speed as small axons","Only in cold environmental conditions","Only in retrograde direction"], ans:1, exp:"Larger diameter = lower axoplasmic resistance = faster local current spread → faster conduction.", optExp: ["Inverse of correct.",null,"Diameter matters significantly.","Temperature affects but not diameter principle.","Direction is not diameter-dependent."] },
  { id:207, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Temporal summation refers to:", opts:["Multiple neurons firing simultaneously","One neuron firing rapidly repeatedly","Backwards action potential conduction","Action potentials in muscle","Synaptic vesicle pooling"], ans:1, exp:"Temporal summation = one presynaptic neuron fires repeatedly in quick succession, summing EPSPs to reach threshold.", optExp: ["That is spatial summation.",null,"Backwards conduction is retrograde.","Not muscle-specific.","Not summation per se."] },
  { id:208, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"Hyperkalaemia (high extracellular K⁺) typically causes:", opts:["Less negative Vm with increased excitability","Hyperpolarise and prevent AP firing","No change in membrane potential","Repolarisation failure of Na⁺","Total loss of all conduction"], ans:0, exp:"High extracellular K⁺ depolarises the resting membrane (less negative), initially increasing excitability but eventually inactivating Na⁺ channels.", optExp: [null,"Hyperpolarisation is from hypokalaemia.","Definite effect.","Initial inactivation; this is too specific.","Eventually but not initially."] },
  { id:209, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"In skeletal muscle, calcium binds to which thin filament protein to initiate contraction?", opts:["Myosin head","Tropomyosin protein","Troponin C protein","Actin filament","Titin protein"], ans:2, exp:"Ca²⁺ binds troponin C, causing tropomyosin to shift and expose actin binding sites for myosin.", optExp: ["Myosin is the thick filament motor.","Tropomyosin moves AFTER Ca²⁺-troponin binding.",null,"Actin is the binding partner, not Ca²⁺ binder.","Titin is structural."] },
  { id:210, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"The power stroke in skeletal muscle contraction occurs when:", opts:["Myosin releases ADP and Pi pulling actin","ATP binds to myosin head","Calcium is pumped back into SR","Tropomyosin covers actin binding sites","Sarcolemma becomes depolarised"], ans:0, exp:"After ATP hydrolysis, the cocked myosin head releases ADP + Pi and pivots, dragging actin toward the M-line.", optExp: [null,"ATP binding causes detachment.","Ca²⁺ pumping happens during relaxation.","Tropomyosin masking is the resting state.","Depolarisation initiates but isn't the stroke."] },
  { id:211, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"In skeletal muscle, what stores calcium for release during contraction?", opts:["Sarcoplasmic reticulum stores calcium","Mitochondria store calcium","Lysosomes store calcium","Nucleus stores calcium","Golgi apparatus stores calcium"], ans:0, exp:"The sarcoplasmic reticulum stores Ca²⁺, releasing it via ryanodine receptors when T-tubules depolarise.", optExp: [null,"Mitochondria buffer Ca²⁺ but don't trigger release.","Lysosomes degrade material.","Nucleus stores DNA.","Golgi packages proteins."] },
  { id:212, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"What causes detachment of myosin from actin during the cross-bridge cycle?", opts:["ATP binding to myosin","Calcium release","Power stroke","Tropomyosin movement","Action potential arrival"], ans:0, exp:"ATP binding to the myosin head reduces affinity for actin → myosin releases. ATP is then hydrolysed for re-cocking.", optExp: [null,"Calcium initiates contraction, not detachment.","Power stroke is the contraction phase.","Tropomyosin exposure allows binding.","AP triggers Ca²⁺ release, not detachment."] },
  { id:213, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"In rigor mortis, muscles stay contracted because:", opts:["ATP depletion prevents myosin detachment","High calcium release occurs","Tropomyosin permanently moves aside","Excess troponin C production","Sarcolemma membrane collapses"], ans:0, exp:"Without ATP after death, myosin heads remain bound to actin — rigor. Eventually proteolysis releases the muscle.", optExp: [null,"Calcium is one factor but not the chief reason.","Tropomyosin doesn't permanently move.","Troponin is not in excess.","Sarcolemma is not the cause."] },
  { id:214, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Type I (slow oxidative) muscle fibres are characterised by:", opts:["High glycolytic capacity, fatigue quickly","High mitochondria, fatigue-resistant, dark","Pale colour, fast contraction speed","No myoglobin protein present","Anaerobic ATP metabolism only"], ans:1, exp:"Type I fibres are slow, oxidative, rich in mitochondria/myoglobin, dark in colour, and fatigue-resistant — endurance.", optExp: ["That describes Type IIB.",null,"Type I are slow.","Type I have lots of myoglobin.","Type I use aerobic metabolism."] },
  { id:215, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Type IIB (fast glycolytic) muscle fibres are:", opts:["Fast, pale, low mitochondria, fatigues quickly","Slow, dark, fatigue-resistant fibres","Found only in cardiac muscle","Found only in tongue","Not found in adult muscle"], ans:0, exp:"Type IIB fibres are fast-twitch, glycolytic, low in mitochondria/myoglobin (pale), and fatigue quickly — power/sprinting.", optExp: [null,"That is Type I.","Cardiac is its own type.","Not tongue-specific.","Present throughout life."] },
  { id:216, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"What is the role of T-tubules in skeletal muscle?", opts:["Store calcium ions released","Conduct action potential into fibre","Synthesise ATP for contraction","Generate the muscle force","Anchor sarcomeres in place"], ans:1, exp:"T-tubules are sarcolemma invaginations that conduct APs deep into the muscle fibre to trigger Ca²⁺ release from SR.", optExp: ["SR stores calcium.",null,"Mitochondria make ATP.","Actin/myosin generate force.","Z-discs anchor sarcomeres."] },
  { id:217, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Cardiac muscle differs from skeletal muscle in that it:", opts:["Is voluntary contraction type","Has multiple peripheral cell nuclei","Has intercalated discs with junctions","Lacks striations completely","Lacks troponin protein entirely"], ans:2, exp:"Cardiac myocytes are connected by intercalated discs containing desmosomes and gap junctions, enabling rapid coordinated contraction.", optExp: ["Cardiac is involuntary.","Skeletal has multiple peripheral nuclei; cardiac usually 1-2 central.",null,"Cardiac IS striated.","Cardiac HAS troponin (used as MI marker)."] },
  { id:218, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Smooth muscle contraction differs from skeletal in that:", opts:["Calcium binds calmodulin to activate MLCK","Uses sarcomeres for contraction","Is striated like skeletal muscle","Is voluntary contraction type","Uses only calcium from SR"], ans:0, exp:"In smooth muscle, Ca²⁺ binds calmodulin → activates MLCK → phosphorylates myosin light chain → contraction. No troponin/sarcomeres.", optExp: [null,"Smooth muscle has no sarcomeres.","Smooth muscle is NOT striated.","Smooth muscle is involuntary.","Uses Ca²⁺ from extracellular and SR."] },
  { id:219, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which neuroglial cell myelinates axons in the CNS?", opts:["Schwann cell in PNS","Oligodendrocyte in CNS","Astrocyte in CNS","Microglia in CNS","Ependymal cell in CNS"], ans:1, exp:"Oligodendrocytes myelinate multiple CNS axons. Schwann cells myelinate ONE PNS axon segment each.", optExp: ["Schwann cells are PNS.",null,"Astrocytes provide structural/metabolic support.","Microglia are CNS immune cells.","Ependymal cells line ventricles."] },
  { id:220, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Schwann cells:", opts:["Myelinate multiple axons","Myelinate one axon segment","Function as immune cells","Line the ventricles","Form blood-brain barrier"], ans:1, exp:"Each Schwann cell wraps one segment of a single PNS axon to form myelin.", optExp: ["Oligodendrocytes do CNS multi-axon myelination.",null,"Microglia are immune.","Ependymal cells line ventricles.","Astrocytes contribute to BBB."] },
  { id:221, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Astrocytes contribute to the blood-brain barrier by:", opts:["Phagocytose pathogens directly","Wrap endfeet around capillaries","Produce cerebrospinal fluid","Myelinate axons in the CNS","Produce neurotransmitters"], ans:1, exp:"Astrocytic endfeet surround capillary endothelium, signalling them to form tight junctions and contributing to BBB integrity.", optExp: ["Microglia phagocytose.",null,"CSF is from choroid plexus (ependymal).","That is oligodendrocyte/Schwann.","Some neurotransmitter uptake, but not main BBB role."] },
  { id:222, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which neuron type is most common in motor pathways?", opts:["Bipolar neurons","Pseudounipolar neurons","Multipolar neurons","Anaxonic neurons","Unipolar neurons"], ans:2, exp:"Multipolar neurons (one axon + many dendrites) are most common — typical of motor neurons and CNS neurons.", optExp: ["Bipolar are mainly in special senses (retina, olfactory).","Pseudounipolar are PNS sensory.",null,"Anaxonic are rare CNS interneurons.","Pure unipolar are rare in vertebrates."] },
  { id:223, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Pseudounipolar neurons are typically found:", opts:["Found in dorsal root ganglia","Found in the cerebellum","Found in the retina","Found as motor neurons in the spinal cord","Found in autonomic ganglia"], ans:0, exp:"Pseudounipolar neurons are characteristic of PNS sensory neurons (dorsal root ganglia, cranial sensory ganglia).", optExp: [null,"Cerebellar cells are multipolar.","Retina has bipolar cells.","Motor neurons are multipolar.","Autonomic ganglia have multipolar postganglionic neurons."] },
  { id:224, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"What is the primary ion responsible for neurotransmitter release at the synaptic terminal?", opts:["Sodium ion (Na⁺)","Potassium ion (K⁺)","Calcium ion (Ca²⁺)","Chloride ion (Cl⁻)","Magnesium ion (Mg²⁺)"], ans:2, exp:"AP arrival opens voltage-gated Ca²⁺ channels at the presynaptic terminal; Ca²⁺ triggers vesicle fusion via SNARE.", optExp: ["Na⁺ depolarises the membrane but doesn't trigger release.","K⁺ repolarises.",null,"Cl⁻ is mainly inhibitory neurotransmission.","Mg²⁺ blocks NMDA receptors at rest."] },
  { id:225, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Postganglionic sympathetic neurons release which neurotransmitter (with exception of sweat glands)?", opts:["Acetylcholine","Noradrenaline","Dopamine","Serotonin","GABA"], ans:1, exp:"Postganglionic sympathetic neurons release noradrenaline onto adrenergic receptors. Exception: sweat glands use ACh.", optExp: ["ACh is preganglionic (and PNS postganglionic).",null,"Dopamine is in CNS dopaminergic pathways.","Serotonin is in raphe nuclei mainly.","GABA is CNS inhibitory."] },
  { id:226, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Preganglionic neurons of both sympathetic and parasympathetic systems release:", opts:["Noradrenaline","Acetylcholine","Dopamine","Glutamate","Histamine"], ans:1, exp:"All autonomic preganglionic neurons release ACh onto nicotinic receptors on postganglionic neurons.", optExp: ["Postganglionic sympathetic releases noradrenaline.",null,"Not the autonomic transmitter.","Not in autonomic preganglionic.","Histamine is in mast cells/some CNS pathways."] },
  { id:227, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Postganglionic parasympathetic neurons release ACh onto:", opts:["Nicotinic receptors","Muscarinic receptors","Adrenergic receptors","NMDA receptors","GABA receptors"], ans:1, exp:"PNS postganglionic neurons release ACh onto muscarinic receptors on target tissues (e.g. M2 on heart, M3 on smooth muscle/glands).", optExp: ["Nicotinic is preganglionic.",null,"Adrenergic is sympathetic postganglionic.","Glutamatergic in CNS.","Inhibitory CNS receptor."] },
  { id:228, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Microglia are best described as:", opts:["Myelinating cells of the CNS","CNS resident immune cells","Cells that produce cerebrospinal fluid","Sensory cells in the nervous system","Cells that produce extracellular matrix"], ans:1, exp:"Microglia are the CNS's resident macrophages, performing phagocytosis and releasing cytokines.", optExp: ["Oligodendrocytes myelinate CNS.",null,"Ependymal/choroid plexus make CSF.","Not sensory.","ECM is from connective tissue cells."] },
  { id:229, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Endocrine signalling involves:", opts:["Cells signal themselves","Local diffusion to neighbouring cells","Hormones travel in the bloodstream","Direct cell-to-cell contact via gap junctions","Synaptic signal transmission"], ans:2, exp:"Endocrine = hormones travel via the blood to act on distal target tissues (e.g. insulin, thyroxine).", optExp: ["That is autocrine.","That is paracrine.",null,"That is juxtacrine.","Synaptic is neuronal."] },
  { id:230, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Paracrine signalling means:", opts:["A cell signals itself","A cell signals nearby cells","Hormones travel in the blood","Signals travel through gap junctions","Intracellular receptor signalling"], ans:1, exp:"Paracrine signalling acts on neighbouring cells via local diffusion (e.g. growth factors, prostaglandins).", optExp: ["That is autocrine.",null,"That is endocrine.","Juxtacrine relies on direct contact.","That is intracrine."] },
  { id:231, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Autocrine signalling means:", opts:["A cell signals itself","A cell signals neighbouring cells","Hormones travel in the blood","Direct cell-to-cell contact occurs","Synaptic transmission occurs"], ans:0, exp:"Autocrine = the cell secretes a signal that acts on receptors on its own membrane (e.g. T cells with IL-2).", optExp: [null,"That is paracrine.","That is endocrine.","That is juxtacrine.","That is synaptic."] },
  { id:232, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which receptor type is the insulin receptor?", opts:["G protein-coupled receptor","Ligand-gated ion channel","Receptor tyrosine kinase","Nuclear receptor","Voltage-gated ion channel"], ans:2, exp:"Insulin binds an RTK; subunit autophosphorylation triggers IRS, PI3K, MAPK cascades.", optExp: ["Glucagon is the GPCR; insulin is not.","ACh nicotinic is a ligand-gated channel.",null,"Steroids use nuclear receptors.","Voltage-gated channels are not hormone receptors."] },
  { id:233, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Steroid hormones (e.g. cortisol, oestrogen) typically bind:", opts:["G protein-coupled receptors","Receptor tyrosine kinases","Ligand-gated ion channels","Nuclear receptors","Voltage-gated ion channels"], ans:3, exp:"Steroid hormones are lipid-soluble; they cross the membrane and bind nuclear receptors that act as transcription factors.", optExp: ["Peptide hormones use GPCRs.","Insulin uses RTK.","Ionotropic for fast neurotransmission.",null,"Voltage-gated for excitable cells."] },
  { id:234, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Adrenergic receptors β1 are coupled to:", opts:["Gs protein coupling → increased cAMP","Gi protein coupling → decreased cAMP","Gq protein coupling → IP3/DAG pathway","Tyrosine kinase activation","Nuclear receptor activation"], ans:0, exp:"β1 receptors (heart) couple to Gs, increasing cAMP → ↑ heart rate, contractility.", optExp: [null,"α2 couples to Gi.","α1 couples to Gq.","Not adrenergic.","Not adrenergic."] },
  { id:235, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"α1 adrenergic receptor activation causes:", opts:["Bronchodilation","Vasoconstriction","Decreased heart rate","Increased lipolysis","Pupil constriction"], ans:1, exp:"α1 on vascular smooth muscle activates Gq → PLC → IP3/DAG → Ca²⁺ release → vasoconstriction.", optExp: ["β2 mediates bronchodilation.",null,"M2 mediates ↓HR.","β3 mediates lipolysis.","M3 mediates miosis."] },
  { id:236, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"β2 adrenergic receptors are most associated with:", opts:["Increase cardiac contractility","Cause bronchodilation","Cause vasoconstriction","Cause pupil constriction","Increase sweat secretion"], ans:1, exp:"β2 (Gs) on bronchial and skeletal muscle vascular smooth muscle causes bronchodilation and vasodilation.", optExp: ["β1 = cardiac.",null,"α1 = vasoconstriction.","M3 = miosis.","Sweat is muscarinic (sympathetic ACh exception)."] },
  { id:237, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"M2 muscarinic receptors are located in:", opts:["Lung smooth muscle","Heart, where they decrease heart rate","Sweat glands","Skeletal muscle","Vascular smooth muscle"], ans:1, exp:"M2 in the heart couples to Gi → ↓ cAMP → slower SA node firing and reduced contractility (vagal effect).", optExp: ["M3 is in lung smooth muscle.",null,"Sweat glands use M3.","Skeletal muscle uses nicotinic.","M3 affects vascular endothelium for NO release."] },
  { id:238, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"M3 receptors (smooth muscle, glands) couple to:", opts:["Couple to Gs protein","Couple to Gi protein","Couple to Gq protein","Couple to tyrosine kinase","Couple to nuclear receptor"], ans:2, exp:"M3 couples to Gq → PLC → IP3 → Ca²⁺ release → smooth muscle contraction and glandular secretion.", optExp: ["Gs raises cAMP (β receptors).","Gi lowers cAMP (M2, α2).",null,"Not RTK.","Not nuclear."] },
  { id:239, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Which is NOT a feature of innate immunity?", opts:["Rapid response occurring within minutes to hours","Non-specific response to pathogens","Uses pattern recognition receptors","Memory response upon re-exposure to antigen","Physical barriers including skin and mucus"], ans:3, exp:"Memory is a hallmark of ADAPTIVE immunity, not innate. Innate is rapid but non-specific and has no memory.", optExp: ["Innate is rapid.","Innate is non-specific.","PRRs are innate.",null,"Skin/mucus are innate barriers."] },
  { id:240, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Which innate immune cell is the FIRST to be recruited to a site of bacterial infection?", opts:["Macrophage","Dendritic cell","Neutrophil","B cell","CD8+ T cell"], ans:2, exp:"Neutrophils are the first to arrive at acute bacterial infections via margination, rolling, adhesion, diapedesis.", optExp: ["Macrophages are tissue-resident and early but neutrophils swarm rapidly from blood.","DCs sample antigen and migrate to lymph nodes.",null,"B cells are adaptive.","CD8+ T cells are adaptive."] },
  { id:241, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Which innate immune cell is primarily responsible for early antiviral defence and killing virus-infected cells?", opts:["Macrophage","Natural killer cell","Neutrophil","Mast cell","B cell"], ans:1, exp:"NK cells recognise infected/transformed cells lacking MHC I and kill them via perforin/granzymes — innate antiviral.", optExp: ["Macrophages are tissue-resident phagocytes, but NK cells lead early antiviral killing.",null,"Neutrophils are antibacterial.","Mast cells mediate allergic responses.","B cells produce antibodies (adaptive)."] },
  { id:242, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Mast cells release histamine, causing:", opts:["Cause bronchoconstriction","Cause vasoconstriction","Cause vasodilation and increased vascular permeability","Cause hypotension","Reduce immune response"], ans:2, exp:"Histamine causes vasodilation (redness, warmth) and increased vascular permeability (oedema) — the cardinal signs of acute inflammation.", optExp: ["Bronchoconstriction is one effect but not the main here.","Histamine VASODILATES, not constricts.",null,"Hypotension can occur but not the defining inflammatory effect.","Histamine triggers, not reduces, immune response."] },
  { id:243, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Lysozyme (in tears, saliva) is most effective against:", opts:["Gram-positive bacteria","Gram-negative bacteria","Viruses","Fungi","Parasites"], ans:0, exp:"Lysozyme cleaves bonds in peptidoglycan, abundant in Gram-positive cell walls.", optExp: [null,"Gram-negative have thinner peptidoglycan and outer membrane (less affected).","Viruses lack peptidoglycan.","Fungi have chitin.","Parasites have protective coatings."] },
  { id:244, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The complement system's three pathways converge on activation of:", opts:["C1","C3","C5","C9","Factor B"], ans:1, exp:"All three pathways (classical, lectin, alternative) generate C3 convertase, which splits C3 into C3a and C3b.", optExp: ["C1 is only in classical.",null,"C5 is downstream of C3.","C9 is in MAC formation.","Factor B is alternative-specific."] },
  { id:245, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The classical complement pathway is activated by:", opts:["Mannose on pathogen surfaces","Antibody-antigen complexes","Spontaneous C3 hydrolysis","Lectins bound to pathogenic mannose","T cell receptors"], ans:1, exp:"C1q binds the Fc region of antibody (IgG or IgM) bound to antigen, initiating the cascade.", optExp: ["That is lectin pathway.",null,"That is alternative pathway.","Lectins drive lectin pathway, not classical.","TCRs are adaptive."] },
  { id:246, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The alternative complement pathway is activated by:", opts:["Antibody binding to pathogens","Spontaneous C3 hydrolysis and pathogen surfaces","Mannose binding lectin recognition","T cell help signals","B cell receptor engagement"], ans:1, exp:"C3 spontaneously hydrolyses; the resulting C3b can attach to bacterial surfaces (especially LPS), amplifying complement.", optExp: ["That is classical.",null,"That is lectin.","T cells are adaptive.","BCRs are adaptive."] },
  { id:247, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Membrane attack complex (MAC) consists of:", opts:["C5b, C6, C7, C8, and C9 proteins","C1, C2, C3, and C4 proteins","C3a and C3b fragments","C1q, C1r, and C1s proteins","Factor B and D proteins"], ans:0, exp:"MAC = C5b + C6 + C7 + C8 + (multiple) C9, forming a pore that lyses pathogens (especially Gram-negative bacteria).", optExp: [null,"These are upstream cascade components.","These are cleavage products, not the MAC.","That is the C1 complex.","Alternative pathway initiator components."] },
  { id:248, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"C3b functions as a(n):", opts:["Opsonin that tags pathogens for phagocytosis","Anaphylatoxin that triggers mast cell degranulation","Chemotactic factor that attracts immune cells","Membrane pore component","Antibody-like recognition molecule"], ans:0, exp:"C3b binds pathogen surfaces, marking them for phagocyte recognition (opsonisation).", optExp: [null,"C3a is the anaphylatoxin.","C5a is the main chemotactic factor.","C5b-9 forms the membrane pore.","Complement is not antibody."] },
  { id:249, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"C5a primarily functions as a:", opts:["Potent chemotactic anaphylatoxin","Membrane pore-forming component","Opsonin for enhanced phagocytosis","Antibody enhancer","Cytokine receptor antagonist"], ans:0, exp:"C5a is a potent chemotactic factor and anaphylatoxin, recruiting neutrophils to the site of infection.", optExp: [null,"MAC is the membrane pore.","C3b is opsonin.","Not an antibody.","Not a receptor."] },
  { id:250, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Toll-like receptors (TLRs) are an example of:", opts:["Adaptive antigen recognition receptor","Pattern recognition receptor","Cytokine recognition receptor","Chemotactic factor receptor","T cell receptor subtype"], ans:1, exp:"TLRs recognise pathogen-associated molecular patterns (PAMPs) — defining feature of innate PRR-mediated recognition.", optExp: ["TLRs are innate, not adaptive.",null,"Not cytokine receptors.","Not chemotactic.","TCRs are clonal adaptive receptors."] },
  { id:251, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"C4 deficiency is most associated with:", opts:["Systemic lupus erythematosus","Recurrent meningococcal infections","Sickle cell anemia","Hereditary angioedema","Anaphylaxis reactions"], ans:0, exp:"C4 deficiency impairs immune complex clearance and is strongly associated with SLE (~90% develop the disease).", optExp: [null,"C5-9 deficiency → Neisseria infections.","Sickle cell is haemoglobinopathy.","C1 inhibitor deficiency → hereditary angioedema.","Not complement deficiency-related."] },
  { id:252, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Defensins and cathelicidins are:", opts:["Antibody proteins","Antimicrobial peptides","Cytokine proteins","Complement proteins","Histamine molecules"], ans:1, exp:"Defensins/cathelicidins are AMPs secreted by neutrophils and epithelial cells, disrupting microbial membranes.", optExp: ["Antibody isotypes are IgG/A/M/E/D.",null,"Cytokines are signalling, not membrane-disrupting.","Complement is a different system.","Not histamine-related."] },
  { id:253, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Diapedesis refers to:", opts:["Rolling on endothelium","Adhesion to endothelium","Migration of leukocytes through vessel walls into tissue","Antigen presentation by dendritic cells","Antibody isotype switching"], ans:2, exp:"Diapedesis is the leukocyte step of squeezing through endothelial junctions to enter tissues.", optExp: ["Rolling is step 2.","Adhesion is step 3.",null,"That is APC function.","Class switching is in B cells."] },
  { id:254, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Which immunoglobulin is the primary antibody of mucosal immunity (gut, respiratory tract)?", opts:["IgG","IgM","IgA","IgE","IgD"], ans:2, exp:"IgA is secreted onto mucosal surfaces (gut, airways, breast milk) and protects against pathogens entering through these routes.", optExp: ["IgG is the main serum antibody.","IgM is the first responder.",null,"IgE mediates allergy/parasites.","IgD is on B cell receptors."] },
  { id:255, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Which immunoglobulin crosses the placenta to provide passive immunity to the fetus?", opts:["IgA","IgM","IgG","IgE","IgD"], ans:2, exp:"IgG is the only immunoglobulin that crosses the placenta via FcRn receptors, giving newborns passive immunity.", optExp: ["IgA does not cross significantly.","IgM is too large (pentamer).",null,"IgE does not cross placenta.","IgD does not cross."] },
  { id:256, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The first antibody produced in a primary immune response is:", opts:["IgG","IgM","IgA","IgE","IgD"], ans:1, exp:"IgM is the first antibody produced in response to a new antigen (primary response).", optExp: ["IgG dominates the secondary response.",null,"IgA is mucosal.","IgE for allergies.","IgD is BCR."] },
  { id:257, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"IgE is most associated with:", opts:["Bacterial opsonisation and complement fixation","Type I hypersensitivity and parasitic infections","Transplacental transfer to the fetus","Mucosal immunity and secretory transport","B cell receptor complex formation"], ans:1, exp:"IgE binds mast cells and eosinophils. Crosslinking by allergen/antigen triggers degranulation — allergic and antiparasitic responses.", optExp: ["IgG opsonises.",null,"IgG crosses placenta.","IgA is mucosal.","IgD is BCR."] },
  { id:258, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"MHC class I molecules:", opts:["Found only on antigen-presenting cells","Found on all nucleated cells","Present endogenous antigens to CD4+ T cells","Absent in viral infections","Bind to antibodies directly"], ans:1, exp:"MHC I is on all nucleated cells, presenting intracellular (endogenous) antigens to CD8+ cytotoxic T cells.", optExp: ["MHC II is more APC-restricted.",null,"That is MHC II.","MHC I downregulation occurs in some viral infections, but they are normally present.","MHC binds peptides, not antibodies."] },
  { id:259, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"MHC class II molecules:", opts:["Present endogenous antigens to CD8+ T cells","Found on all nucleated cells","Restricted to antigen-presenting cells","Bind antibodies in immune complexes","Activate CD8+ cytotoxic T cells"], ans:2, exp:"MHC II is on APCs (DCs, macrophages, B cells) and presents extracellular antigens to CD4+ helper T cells.", optExp: ["That is MHC I.","MHC II is restricted to APCs.",null,"MHC binds peptides.","MHC I activates CD8+ T cells."] },
  { id:260, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"T cells develop and mature in the:", opts:["Bone marrow","Thymus","Spleen","Lymph nodes","Peyer's patches"], ans:1, exp:"T cells originate in bone marrow but migrate to the thymus where positive and negative selection occur.", optExp: ["B cells mature there.",null,"Spleen filters blood antigens.","LNs are sites of activation, not maturation.","Peyer's patches are gut-associated lymphoid tissue."] },
  { id:261, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Positive selection of T cells occurs in:", opts:["Thymic medulla","Thymic cortex","Bone marrow","Spleen","Lymph nodes"], ans:1, exp:"In the thymic cortex, T cells that can bind self-MHC survive ('positive selection'); those that can't undergo death by neglect.", optExp: ["Negative selection occurs in medulla.",null,"B cells select in bone marrow.","Spleen filters blood.","Not the site of T cell selection."] },
  { id:262, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Negative selection of T cells eliminates:", opts:["Self-reactive T cells that bind strongly to self-antigens","T cells failing to recognize self-MHC molecules","All immature T cells regardless of specificity","B cells accidentally located in the thymus","Macrophages within the thymic tissue"], ans:0, exp:"In the thymic medulla, T cells with high affinity for self-antigens are deleted, preventing autoimmunity.", optExp: [null,"That happens via positive selection failure (death by neglect).","Only ~2% survive selection but not all are deleted.","B cells select in bone marrow.","Macrophages don't undergo this selection."] },
  { id:263, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"CD4+ T cells differentiate into all EXCEPT:", opts:["TH1 cells","TH2 cells","TH17 cells","Regulatory T cells (Treg)","CD8+ cytotoxic T cells"], ans:4, exp:"CD4+ helper T cells differentiate into TH1, TH2, TH17, Treg, etc. CD8+ cytotoxic is a separate lineage.", optExp: ["TH1 fights intracellular pathogens.","TH2 fights parasites/allergies.","TH17 fights extracellular bacteria/fungi.","Treg suppresses immune response.",null] },
  { id:264, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The variable region of an antibody:", opts:["Determines antigen specificity and binding","Responsible for effector functions via Fc region","Activates complement via classical pathway","Enables transplacental crossing","Shows structural similarity across all antibody types"], ans:0, exp:"The variable regions of light and heavy chains form the antigen-binding paratope, giving each antibody its specificity.", optExp: [null,"Fc is the constant (stem) region.","Fc activates complement.","Fc crosses placenta.","Variable regions vary; constant is shared by isotype."] },
  { id:265, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Class switching of antibodies occurs in:", opts:["Bone marrow plasma cells only","T cells in secondary lymphoid organs","Activated B cells in germinal centres","Tissue macrophages","Thymic dendritic cells"], ans:2, exp:"Activated B cells undergo class switch recombination from IgM/IgD to IgG, IgA, or IgE, driven by cytokines and CD40-CD40L.", optExp: ["Plasma cells already produced antibody — switching happens before.","T cells don't make antibodies.",null,"Macrophages don't make antibodies.","DCs don't make antibodies."] },
  { id:266, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Memory cells provide:", opts:["Faster and stronger immune response on re-exposure","Innate barrier function against pathogens","Immediate phagocytosis of antigens","Vasodilation and increased vascular permeability","Direct activation of the complement cascade"], ans:0, exp:"Memory B and T cells persist after infection and mount a faster, larger response on re-encounter — basis of vaccination.", optExp: [null,"Innate barriers are skin/mucus.","Phagocytosis is by neutrophils/macrophages.","Vasodilation is from histamine.","Complement is innate."] },
  { id:267, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Plasma cells are derived from:", opts:["Activated B cells","Activated T cells","Natural killer cells","Dendritic cells","Eosinophils"], ans:0, exp:"Activated B cells differentiate into plasma cells, which are dedicated antibody factories.", optExp: [null,"T cells don't differentiate into plasma cells.","NK cells are innate.","DCs are APCs.","Eosinophils combat parasites."] },
  { id:268, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Hypersensitivity Type I (allergic) is mediated by:", opts:["IgG and IgM antibodies against cell antigens","IgE antibodies bound to mast cells and basophils","Immune complex deposition in tissues","T cell-mediated delayed response","Complement system deficiency"], ans:1, exp:"Type I: IgE binds mast cells; allergen crosslinks IgE, triggering rapid degranulation (anaphylaxis, asthma).", optExp: ["That is Type II.",null,"That is Type III.","That is Type IV.","Complement deficiency is a different disorder."] },
  { id:269, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Type II hypersensitivity (cytotoxic) is exemplified by:", opts:["Anaphylaxis","Autoimmune hemolytic anemia","Serum sickness","Tuberculin skin test","Allergic rhinitis"], ans:1, exp:"Type II: antibodies bind cells, activating complement or ADCC (e.g. AIHA, Goodpasture's, transfusion reactions).", optExp: ["That is Type I.",null,"That is Type III.","That is Type IV.","That is Type I."] },
  { id:270, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Type III hypersensitivity involves:", opts:["IgE antibodies and mast cell degranulation","Immune complex deposition in blood vessels and tissues","T cell-mediated cellular response","Complement system deficiency","NK cell activation"], ans:1, exp:"Type III: antigen-antibody complexes deposit in vessels/tissues, activating complement (e.g. SLE, serum sickness, post-strep GN).", optExp: ["That is Type I.",null,"That is Type IV.","Different mechanism.","Not the mechanism."] },
  { id:271, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Type IV hypersensitivity is mediated by:", opts:["IgE antibodies","IgG antibodies","Immune complexes","T cells","Natural killer cells"], ans:3, exp:"Type IV (delayed) is T-cell mediated — TB skin test, contact dermatitis, granuloma formation.", optExp: ["IgE → Type I.","IgG against cells → Type II.","ICs → Type III.",null,"NK cells are not the main mediator."] },
  { id:272, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"A patient develops urticaria and bronchospasm minutes after a bee sting. This is which type of hypersensitivity?", opts:["Type I","Type II","Type III","Type IV","Type V"], ans:0, exp:"Rapid IgE-mediated mast cell degranulation = Type I (anaphylaxis).", optExp: [null,"Type II involves antibody against cells.","Type III is immune complex.","Type IV is delayed cellular.","No standard 'Type V' in this scheme."] },
  { id:273, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which type of necrosis occurs in the brain after infarction?", opts:["Coagulative necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis","Fibrinoid necrosis"], ans:1, exp:"Brain tissue has high lipid and minimal collagen — neutrophil enzymes liquefy it, producing cystic cavities.", optExp: ["Coagulative is most solid organs.",null,"Caseous is in TB.","Fat necrosis is in pancreatitis.","Fibrinoid is in vessel walls."] },
  { id:274, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Coagulative necrosis is typical of:", opts:["Brain infarction","Myocardial infarction","Tuberculosis infection","Acute pancreatitis","Vasculitis"], ans:1, exp:"Coagulative necrosis preserves tissue architecture for several days after ischaemic injury (e.g. MI, kidney infarct).", optExp: ["Brain shows liquefactive.",null,"TB shows caseous.","Pancreatitis shows fat necrosis.","Vasculitis shows fibrinoid."] },
  { id:275, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Caseous necrosis is characteristic of:", opts:["Myocardial infarction","Tuberculosis and fungal infections","Acute pancreatitis","Deep vein thrombosis","Brain stroke"], ans:1, exp:"Caseous necrosis ('cheese-like') is seen in TB granulomas and certain systemic fungal infections.", optExp: ["MI is coagulative.",null,"Pancreatitis is fat necrosis.","DVT is thrombus, not necrosis type per se.","Stroke is liquefactive."] },
  { id:276, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Fat necrosis with saponification (chalky white areas) is classically seen in:", opts:["Brain tissue damage","Heart tissue damage","Pancreatic tissue damage","Lung tissue damage","Spleen tissue damage"], ans:2, exp:"In acute pancreatitis, lipase digests fat → free fatty acids + Ca²⁺ form chalky saponified deposits.", optExp: ["Brain shows liquefactive.","Heart shows coagulative.",null,"Lung infarcts are coagulative/hemorrhagic.","Spleen infarcts are coagulative."] },
  { id:277, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Fibrinoid necrosis is seen in:", opts:["Malignant hypertension","Tuberculosis infection","Myocardial infarction","Brain infarction","Acute pancreatitis"], ans:0, exp:"Immune complexes deposit in vessel walls causing fibrin-like material accumulation and necrosis (e.g. malignant HTN, polyarteritis nodosa).", optExp: [null,"TB is caseous.","MI is coagulative.","Brain is liquefactive.","Pancreatitis is fat necrosis."] },
  { id:278, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Wet gangrene differs from dry gangrene in that wet gangrene:", opts:["No bacterial infection present","Secondary bacterial infection with tissue liquefaction","Involvement of fingers only","Potentially reversible with treatment","Associated with diabetes only"], ans:1, exp:"Wet gangrene involves bacterial superinfection leading to liquefactive necrosis with foul odour. Dry gangrene is purely ischaemic.", optExp: ["Wet HAS infection.",null,"Affects any extremity.","Gangrene is irreversible.","Diabetes is a risk factor but not exclusive."] },
  { id:279, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Apoptosis differs from necrosis in that apoptosis:", opts:["Causes inflammatory response","Unregulated and pathological cell death","Programmed, organized cell death without inflammation","Always involves multiple organ systems","Releases cell contents into surrounding tissue"], ans:2, exp:"Apoptosis is energy-requiring, programmed cell death without inflammation. Necrosis is messy and inflammatory.", optExp: ["Apoptosis avoids inflammation.","Apoptosis is highly regulated.",null,"Apoptosis is cell-specific.","Apoptotic bodies are phagocytosed; cytoplasmic content is retained."] },
  { id:280, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which is NOT a type of cell adaptation?", opts:["Hypertrophy","Hyperplasia","Atrophy","Apoptosis","Metaplasia"], ans:3, exp:"Apoptosis is cell death, not adaptation. Adaptations include hypertrophy, hyperplasia, atrophy, metaplasia, dysplasia.", optExp: ["Cell gets bigger.","More cells.","Cells get smaller.",null,"Cell type changes."] },
  { id:281, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Metaplasia refers to:", opts:["Reversible change from one differentiated cell type to another","Disordered growth with loss of normal architecture","Programmed cell death process","Decrease in cell size","Uncontrolled proliferation of cells"], ans:0, exp:"Metaplasia is the reversible conversion from one adult cell type to another (e.g. Barrett's oesophagus: squamous → columnar).", optExp: [null,"That is dysplasia.","That is necrosis/apoptosis.","That is atrophy.","That is neoplasia."] },
  { id:282, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Dysplasia is characterised by:", opts:["Maintenance of normal differentiation","Disordered growth with loss of normal architecture","Programmed cell death","Increase in individual cell size","Invasion beyond tissue boundaries"], ans:1, exp:"Dysplasia features atypical cells (loss of differentiation, irregular nuclei), but the basement membrane is intact — pre-cancerous.", optExp: ["Dysplasia is abnormal.",null,"Not cell death.","That is hypertrophy.","Invasion = malignancy."] },
  { id:283, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Hypertrophy of the cardiac left ventricle in response to hypertension is an example of:", opts:["Increase in the number of cardiac myocytes","Increase in size of individual cardiac myocytes","Replacement of cardiac muscle with another cell type","Uncontrolled growth of cardiac cells","Programmed death of cardiac myocytes"], ans:1, exp:"Cardiac myocytes cannot divide; LV hypertrophy is purely cell enlargement, not increased cell number.", optExp: ["Hyperplasia is more cells.",null,"Metaplasia is cell-type change.","Neoplasia is uncontrolled new growth.","Apoptosis is cell death."] },
  { id:284, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"The 5 cardinal signs of inflammation include all EXCEPT:", opts:["Redness (rubor)","Warmth (calor)","Pain (dolor)","Swelling (tumor)","Tissue necrosis"], ans:4, exp:"Cardinal signs: rubor (redness), calor (heat), dolor (pain), tumor (swelling), functio laesa (loss of function). Necrosis is a tissue change, not a cardinal sign.", optExp: ["Cardinal sign.","Cardinal sign.","Cardinal sign.","Cardinal sign.",null] },
  { id:285, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which mediator primarily causes vasodilation and increased vascular permeability in acute inflammation?", opts:["TNF-α","Histamine","IL-1","Bradykinin","Histamine and bradykinin together"], ans:4, exp:"Multiple mediators contribute, but histamine is the immediate/early mediator, with bradykinin, leukotrienes, NO, and cytokines amplifying.", optExp: ["Major systemic effects but not the most immediate.","Major immediate vasodilator/permeability factor.","Pyrogen and adhesion molecule inducer.","Increases vascular permeability and pain.",null] },
  { id:286, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"The correct order of leukocyte extravasation is:", opts:["Adhesion → margination → rolling → diapedesis","Margination → rolling → adhesion → diapedesis","Diapedesis → adhesion → margination → rolling","Rolling → margination → adhesion → diapedesis","Adhesion → rolling → diapedesis → margination"], ans:1, exp:"Margination (edge), rolling (selectins), firm adhesion (integrins), diapedesis (out into tissue).", optExp: ["Adhesion comes after rolling.",null,"Diapedesis is last.","Margination is first.","Order is wrong."] },
  { id:287, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Granulomas are characteristic of:", opts:["Acute bacterial infection","Chronic inflammation","Allergic asthma","Anaphylactic reaction","Acute viral hepatitis"], ans:1, exp:"Granulomas form when macrophages cannot eliminate the antigen — chronic inflammation with epithelioid macrophages, multinucleated giant cells.", optExp: ["Acute is mainly neutrophilic.",null,"Asthma involves eosinophils.","Anaphylaxis is mast cell-driven.","Some viral infections produce granulomas but not typical of viral hepatitis."] },
  { id:288, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which cell type predominates in granulomas?", opts:["Neutrophils","Eosinophils","Epithelioid macrophages","Plasma cells","Mast cells"], ans:2, exp:"Granulomas are dominated by activated macrophages (epithelioid cells) and multinucleated giant cells, with surrounding lymphocytes.", optExp: ["Neutrophils are acute.","Eosinophils are parasitic/allergic.",null,"Plasma cells make antibodies.","Mast cells mediate Type I."] },
  { id:289, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"A non-caseating granuloma is most characteristic of:", opts:["Tuberculosis","Sarcoidosis","Bacterial pneumonia","Chronic viral hepatitis","Sickle cell disease"], ans:1, exp:"Non-caseating granulomas are characteristic of sarcoidosis. Caseating granulomas are typical of TB.", optExp: ["TB is caseating.",null,"Pneumonia is acute, not granulomatous.","Hepatitis B/C are not classic granuloma diseases.","Not granulomatous."] },
  { id:290, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which cytokine is a major pyrogen and is targeted by anti-inflammatory biologics in RA?", opts:["IL-2","TNF-α","IL-10","TGF-β","IL-13"], ans:1, exp:"TNF-α is a key pyrogen and inflammatory cytokine, blocked by drugs like infliximab in rheumatoid arthritis.", optExp: ["IL-2 drives T cell proliferation.",null,"IL-10 is anti-inflammatory.","TGF-β is regulatory.","IL-13 is in allergy."] },
  { id:291, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Chronic inflammation is characterised by infiltrate of:", opts:["Predominantly neutrophils","Predominantly mast cells","Lymphocytes and macrophages","Predominantly red blood cells","Predominantly eosinophils"], ans:2, exp:"Chronic inflammation involves mononuclear cells (lymphocytes, plasma cells, macrophages) with possible fibrosis and granuloma formation.", optExp: ["Acute is neutrophilic.","Mast cells alone is allergic.",null,"RBCs indicate haemorrhage, not inflammation.","Eosinophils alone are parasitic/allergic."] },
  { id:292, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"A benign tumour of glandular epithelium is termed a(n):", opts:["Adenocarcinoma","Adenoma","Sarcoma","Lymphoma","Carcinoma in situ"], ans:1, exp:"-oma denotes benign; adenoma = benign glandular tumour. Carcinoma denotes malignant epithelial.", optExp: ["Adenocarcinoma is malignant.",null,"Sarcoma is malignant mesenchymal.","Lymphoma is malignant lymphoid.","CIS is dysplasia confined to epithelium."] },
  { id:293, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"A malignant tumour of mesenchymal origin is a:", opts:["Carcinoma","Sarcoma","Adenoma","Papilloma","Teratoma"], ans:1, exp:"Sarcomas arise from mesenchymal tissue (bone, muscle, fat, fibrous, blood vessels). Carcinomas are epithelial.", optExp: ["Carcinomas are epithelial.",null,"Adenoma is benign glandular.","Papilloma is benign epithelial.","Teratoma arises from germ cells."] },
  { id:294, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Which of the following is a characteristic of malignant (not benign) tumours?", opts:["Slow growth rate","Well-differentiated cells","Well-defined encapsulated structure","Invasion of surrounding tissues and metastasis","Mature and organized cell types"], ans:3, exp:"Invasion past the basement membrane and metastasis define malignancy.", optExp: ["Benign tumours are typically slow.","Benign tumours are well-differentiated.","Benign tumours are usually encapsulated.",null,"Malignant can be poorly differentiated/anaplastic."] },
  { id:295, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Anaplasia describes:", opts:["Increase in the number of cells","Programmed cell death","Loss of cellular differentiation","Decrease in cell size","Reversible change in cell type"], ans:2, exp:"Anaplasia = lack of differentiation, with disorganised cells and bizarre nuclei — a hallmark of malignancy.", optExp: ["That is hyperplasia.","That is necrosis/apoptosis.",null,"That is atrophy.","That is metaplasia."] },
  { id:296, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Carcinoma in situ refers to:", opts:["Malignant epithelial cells confined within the basement membrane","Metastatic carcinoma that has spread to distant sites","Benign tumor with slow growth pattern","Granulation tissue forming at wound sites","Premalignant inflammation without cellular atypia"], ans:0, exp:"CIS has high-grade dysplasia involving full thickness of epithelium but has not breached the basement membrane.", optExp: [null,"Metastasis is more advanced.","Carcinoma is malignant.","Granulation is reparative.","CIS is more advanced than inflammation."] },
  { id:297, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Most common route of metastasis for sarcomas is:", opts:["Lymphatic spread to regional nodes","Haematogenous spread via blood vessels","Transcoelomic spread across body cavities","Perineural invasion along nerve sheaths","Direct invasion into adjacent tissues only"], ans:1, exp:"Sarcomas typically spread via blood (haematogenous, often to lung). Carcinomas typically spread via lymph first.", optExp: ["More typical of carcinomas.",null,"Trancoelomic (e.g. ovarian) less common.","Perineural less common.","Many routes are possible."] },
  { id:298, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"A cervical smear showing abnormal epithelium with atypia but intact basement membrane is:", opts:["Hyperplasia with increased cell numbers but normal appearance","Metaplasia with replacement by different cell type","Dysplasia with cellular atypia but intact basement membrane","Carcinoma in situ with breach of basement membrane","Invasive carcinoma with spread to surrounding tissues"], ans:2, exp:"Dysplasia is abnormal cellular features without breach of basement membrane. CIS is full-thickness dysplasia.", optExp: ["Hyperplasia is increased number, not atypia.","Metaplasia is cell type change.",null,"CIS is more severe but related (full-thickness).","Invasive carcinoma has broken through basement membrane."] },
  { id:299, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Virchow's triad components are:", opts:["Endothelial injury, blood stasis, and altered blood composition","Pain, swelling, and redness at affected site","Platelets, fibrin, and red blood cells","Pressure changes, flow alterations, and time duration","Vasodilation and edema formation"], ans:0, exp:"Virchow's triad: endothelial injury, abnormal flow (stasis/turbulence), hypercoagulability — predisposing factors for thrombosis.", optExp: [null,"Symptoms of DVT.","Components of a clot.","Hemodynamic factors but not Virchow's.","Inflammation features."] },
  { id:300, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"A 60-year-old woman immobilised after surgery develops DVT. The MOST contributing Virchow's factor is:", opts:["Endothelial injury from surgical trauma","Hypercoagulability induced by anesthesia","Stasis of blood from immobilization","Turbulent blood flow in veins","Atherosclerosis of vessel walls"], ans:2, exp:"Immobilisation reduces venous return, causing stasis — the predominant factor for post-operative DVT.", optExp: ["Surgery can cause some injury, but stasis predominates here.","Surgery and inflammation can contribute, but stasis is key.",null,"Turbulence is more in arteries.","Not the dominant factor in DVT."] },
  { id:301, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"A young man with fractured femur develops respiratory distress and petechial rash. Which embolism?", opts:["Thromboembolism from venous thrombus","Fat embolism from bone marrow release","Air embolism from atmospheric entry","Amniotic fluid embolism during pregnancy","Septic embolism from bacterial infection"], ans:1, exp:"Fat embolism syndrome: fat from marrow enters bloodstream after long-bone fractures → respiratory distress, petechiae, cerebral symptoms 24-72 h later.", optExp: ["Thromboembolism does not classically cause petechiae.",null,"Air embolism is iatrogenic.","Amniotic embolism is in labour.","Septic embolism is from infection."] },
  { id:302, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Air embolism most commonly occurs:", opts:["Spontaneous occurrence without identifiable cause","Iatrogenic injury during medical procedures","Long-bone fracture with marrow exposure","Pregnancy and labor complications","Bacterial infection with septicemia"], ans:1, exp:"Air can enter circulation during surgery, central line insertion, or scuba diving (decompression).", optExp: ["Air embolism is not spontaneous.",null,"That is fat embolism.","That is amniotic fluid embolism.","That is septic embolism."] },
  { id:303, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Pulmonary embolism most often arises from thrombi in the:", opts:["Cerebral veins of the brain","Coronary arteries of the heart","Deep veins of the lower limbs","Abdominal aorta","Renal artery of the kidney"], ans:2, exp:"Most PEs originate from DVTs in deep veins of the lower limbs, traveling through right heart to lungs.", optExp: ["Cerebral vein thrombosis is rare.","Coronaries cause MI, not PE.",null,"Aortic emboli travel systemically.","Renal artery emboli go to kidney."] },
  { id:304, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"The coagulation cascade ultimately generates which protein to form a clot?", opts:["Thrombin alone without other factors","Fibrinogen protein in its inactive form","Fibrin generated by thrombin from fibrinogen","Plasmin protein that dissolves clots","Von Willebrand factor for platelet adhesion"], ans:2, exp:"Thrombin (IIa) cleaves fibrinogen to fibrin monomers, which polymerise to form the clot mesh.", optExp: ["Thrombin is the enzyme; fibrin is the product.","Fibrinogen is the substrate.",null,"Plasmin breaks down fibrin (fibrinolysis).","vWF helps platelet adhesion."] },
  { id:305, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"The first step of thrombus formation at site of vascular injury is:", opts:["Fibrin mesh formation and cross-linking","Platelet adhesion to exposed subendothelium","Fibrin polymerization and stabilization","Plasmin activation initiating fibrinolysis","Vasodilation and increased vascular permeability"], ans:1, exp:"Endothelial injury exposes collagen; platelets adhere via vWF and GPIb, then activate and aggregate.", optExp: ["Fibrin formation is later in cascade.",null,"Cross-linking is late.","Plasmin is for clot breakdown.","Vasoconstriction (not dilation) occurs initially."] },
  { id:306, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Hyaline cartilage is found in all EXCEPT:", opts:["Trachea cartilage","Articular surfaces of joints","Nose cartilage","Intervertebral discs","Costal cartilage of ribs"], ans:3, exp:"IV discs are fibrocartilage (shock absorbers). Hyaline cartilage is in trachea, articular surfaces, nose, larynx, costal cartilage.", optExp: ["Trachea has hyaline rings.","Articular surfaces are hyaline.","Nasal cartilage is hyaline.",null,"Costal cartilage is hyaline."] },
  { id:307, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Elastic cartilage is found in:", opts:["Trachea cartilage","Intervertebral discs","External ear cartilage","Articular surfaces of joints","Costal cartilage of ribs"], ans:2, exp:"Elastic cartilage (with elastin fibres) is found in the external ear (pinna), epiglottis, and Eustachian tube.", optExp: ["Hyaline.","Fibrocartilage.",null,"Hyaline.","Hyaline."] },
  { id:308, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Fibrocartilage is found in:", opts:["Trachea cartilage","Intervertebral discs","External ear cartilage","Articular surfaces of joints","Larynx cartilage"], ans:1, exp:"Fibrocartilage (Type I collagen-rich) is found in IV discs, pubic symphysis, menisci — shock absorbers.", optExp: ["Hyaline.",null,"Elastic.","Hyaline.","Hyaline."] },
  { id:309, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Compact bone is mainly found in:", opts:["Epiphysis of long bones","Diaphysis of long bones","Bone marrow cavity","Interior of flat bones","Articular surfaces of joints"], ans:1, exp:"Compact (cortical) bone forms the diaphysis (shaft) of long bones, providing strength.", optExp: ["Epiphyses have spongy bone.",null,"Marrow cavity contains marrow, not compact bone.","Flat bones have spongy interior between compact layers.","Articular surfaces are cartilage."] },
  { id:310, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Spongy (trabecular) bone is found in:", opts:["Found primarily in the diaphysis","Found primarily in the epiphysis and metaphysis","Found in tendons and ligaments","Found in cartilage layers","Found in the periosteum membrane"], ans:1, exp:"Spongy bone (with trabeculae) is in the epiphyses of long bones and in flat bones, containing red marrow.", optExp: ["Compact bone there.",null,"Tendons are connective tissue.","Cartilage is different.","Periosteum is a covering."] },
  { id:311, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Intramembranous ossification is responsible for forming:", opts:["Long bones of the limbs","Flat bones of the skull","Ribs and sternum","Vertebrae and spine","Pelvis and hip bones"], ans:1, exp:"Intramembranous ossification forms flat bones from mesenchymal cells directly (e.g. skull vault, mandible, clavicle). Closes fontanelles by ~age 2.", optExp: ["Long bones use endochondral.",null,"Ribs are endochondral.","Vertebrae are endochondral.","Pelvis is endochondral."] },
  { id:312, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Endochondral ossification involves:", opts:["Ossification directly from mesenchyme without a cartilage template","Ossification of a pre-existing cartilage model","Calcification of fibrous tendons and ligaments","Bone formation that occurs only in adult life","Formation of dental tissues and tooth enamel"], ans:1, exp:"Endochondral ossification produces long bones (and pelvis, ribs, vertebrae) by replacing a cartilage model with bone.", optExp: ["That is intramembranous.",null,"Tendons don't undergo ossification normally.","Begins in utero, continues to puberty.","Teeth use a different process."] },
  { id:313, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Which cell breaks down bone tissue?", opts:["Osteoblast","Osteocyte","Osteoclast","Chondrocyte","Fibroblast"], ans:2, exp:"Osteoclasts are large multinucleated cells (from monocyte lineage) that resorb bone via H⁺ and proteases.", optExp: ["Osteoblasts build bone.","Osteocytes maintain bone matrix.",null,"Chondrocytes are in cartilage.","Fibroblasts make collagen in connective tissue."] },
  { id:314, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Osteocytes reside in:", opts:["Within the periosteum","Within lacunae in the bone matrix","Within Haversian canals","Within bone marrow cavities","Within synovial cavities of joints"], ans:1, exp:"Osteocytes are osteoblasts that became trapped in lacunae of the mineralised bone matrix, communicating via canaliculi.", optExp: ["Periosteum has osteoprogenitors.",null,"Haversian canals contain vessels and nerves.","Marrow contains haematopoietic cells.","Synovial cavity has fluid."] },
  { id:315, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Chondrocytes are housed within:", opts:["Within Haversian canals","Within lacunae in the cartilage matrix","Within lamellae of bone","Within trabeculae of bone","Within Volkmann's canals"], ans:1, exp:"Chondrocytes sit in lacunae within the cartilage matrix; cartilage is avascular and relies on diffusion.", optExp: ["Haversian canals are in bone.",null,"Lamellae are bone matrix layers.","Trabeculae are spongy bone struts.","Volkmann's canals are in bone."] },
  { id:316, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"The growth plate (epiphyseal plate) zones from epiphysis to diaphysis include:", opts:["Calcification zone → hypertrophic zone → proliferation zone → resting zone","Resting zone → proliferation zone → hypertrophic zone → calcification zone","Hypertrophic zone → resting zone → calcification zone → proliferation zone","Proliferation zone → resting zone → calcification zone → hypertrophic zone","Resting zone → calcification zone → proliferation zone → hypertrophic zone"], ans:1, exp:"Mnemonic 'Really Poor Habits Cause Osteoporosis': Resting (Reserved) → Proliferation → Hypertrophic → Calcification.", optExp: ["Reverse order.",null,"Wrong order.","Wrong order.","Wrong order."] },
  { id:317, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"In osteogenesis imperfecta, the defective protein is:", opts:["Type II collagen defect","Type I collagen defect","Elastin defect","Fibrillin defect","Keratin defect"], ans:1, exp:"OI is caused by mutations in COL1A1/COL1A2 (Type I collagen), causing brittle bones, blue sclerae, hearing loss.", optExp: ["Type II is in cartilage.",null,"Elastin is in skin/lungs.","Fibrillin → Marfan.","Keratin is in skin/hair."] },
  { id:318, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Tendons and ligaments are composed of:", opts:["Loose connective tissue","Dense regular connective tissue","Dense irregular connective tissue","Adipose tissue","Elastic cartilage"], ans:1, exp:"Tendons/ligaments are dense regular CT — collagen fibres aligned in parallel to resist tension along one direction.", optExp: ["Loose CT surrounds vessels/organs.",null,"Dense irregular is in dermis/periosteum.","Adipose stores fat.","Different tissue type."] },
  { id:319, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"The periosteum and perichondrium are examples of:", opts:["Dense regular connective tissue","Dense irregular connective tissue","Loose connective tissue","Adipose tissue","Reticular connective tissue"], ans:1, exp:"Dense irregular CT has interwoven collagen bundles, providing strength in multiple directions (dermis, periosteum, perichondrium).", optExp: ["Dense regular is tendons/ligaments.",null,"Loose CT is around organs.","Adipose is fat.","Reticular is in lymph nodes/marrow."] },
  { id:320, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Reticular fibres are predominantly found in:", opts:["Tendons and ligaments","Lymph nodes and spleen","The dermis of skin","Walls of large arteries","Hyaline cartilage matrix"], ans:1, exp:"Reticular fibres (Type III collagen) form the stroma of lymph nodes, spleen, and bone marrow.", optExp: ["Tendons use Type I collagen.",null,"Dermis has Type I primarily.","Aorta has elastic fibres.","Cartilage has Type II."] },
  { id:321, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Which connective tissue cell synthesises collagen and ECM?", opts:["Macrophage","Fibroblast","Mast cell","Adipocyte","Plasma cell"], ans:1, exp:"Fibroblasts are the main producers of collagen, elastin, and ECM ground substance in connective tissue.", optExp: ["Macrophages phagocytose.",null,"Mast cells release histamine.","Adipocytes store fat.","Plasma cells make antibodies."] },
  { id:322, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Adipose tissue's main function is:", opts:["Providing structural strength to tissues","Energy storage and thermal insulation","Muscle contraction and movement","Phagocytosis and immune defense","Antibody secretion and immunity"], ans:1, exp:"White adipose tissue stores energy as triglycerides; brown adipose generates heat.", optExp: ["Dense regular CT for strength.",null,"Muscle for movement.","Macrophages phagocytose.","Plasma cells make antibodies."] },
  { id:323, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Elastic fibres are most abundant in:", opts:["Tendons and ligaments","Articular cartilage","Walls of large elastic arteries","Bone matrix","Lymph nodes"], ans:2, exp:"Large elastic arteries (aorta) and lung tissue contain abundant elastin, allowing recoil.", optExp: ["Tendons use collagen.","Hyaline cartilage uses Type II collagen.",null,"Bone uses Type I + hydroxyapatite.","Reticular dominates here."] },
  { id:324, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Skeletal muscle fibres are:", opts:["Branched, striated multinucleated cells","Long, multinucleated, striated cells","Non-striated involuntary cells","Short cells with a single nucleus","Cells without sarcomeres or striations"], ans:1, exp:"Skeletal muscle: long, cylindrical, multinucleated (peripheral nuclei), striated, voluntary.", optExp: ["That is cardiac muscle.",null,"That is smooth muscle.","Skeletal fibres are unbranched.","Skeletal muscle has sarcomeres."] },
  { id:325, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Cardiac muscle is best identified by:", opts:["Multiple nuclei located at the periphery of cells","Lack of visible striations under the microscope","Intercalated discs joining adjacent cells","Long uninucleated cells with branching","Branched cells completely lacking nuclei"], ans:2, exp:"Cardiac myocytes are branched, striated, with 1-2 central nuclei and intercalated discs containing gap junctions.", optExp: ["That is skeletal.","Cardiac IS striated.",null,"Skeletal is uninucleated... wait, skeletal is multinucleated; cardiac has 1-2 central nuclei.","Cardiac has nuclei."] },
  { id:326, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Smooth muscle differs from skeletal because:", opts:["It has visible striations","It is non-striated and spindle-shaped","It undergoes voluntary contraction","It contains sarcomeres","It has a branched cell structure"], ans:1, exp:"Smooth muscle cells are spindle-shaped, non-striated, with a single central nucleus, involuntary control.", optExp: ["Smooth muscle is NON-striated.",null,"Smooth muscle is involuntary.","Smooth muscle lacks sarcomeres.","Smooth muscle is not branched."] },
  { id:327, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Intercalated discs are unique to:", opts:["Skeletal muscle","Cardiac muscle","Smooth muscle","Tendons","Cartilage"], ans:1, exp:"Intercalated discs are unique to cardiac muscle, containing desmosomes and gap junctions for electrical and mechanical coupling.", optExp: ["Skeletal has none.",null,"Smooth muscle uses gap junctions but no intercalated discs.","Tendons are CT.","Cartilage is different."] },
  { id:328, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Pharmacokinetics refers to:", opts:["What the drug does to the body","What the body does to the drug","How the drug interacts with receptors","The side effect profile of the drug","Genetic variability in drug metabolism"], ans:1, exp:"Pharmacokinetics = absorption, distribution, metabolism, excretion (ADME) — body's effects on drug.", optExp: ["That is pharmacodynamics.",null,"That is pharmacodynamics.","Side effects are pharmacodynamic outputs.","That is pharmacogenetics."] },
  { id:329, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Pharmacodynamics refers to:", opts:["How the body eliminates the drug","The effect of the drug on the body","The rate of drug excretion only","The formulation type of the drug","The manufacturing process of the drug"], ans:1, exp:"Pharmacodynamics = drug effects on receptors and tissues (mechanism of action, dose-response).", optExp: ["That is pharmacokinetics.",null,"Just one element of PK.","That is formulation science.","That is industrial."] },
  { id:330, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Which receptor type produces the FASTEST response?", opts:["G-protein coupled receptor activation","Receptor tyrosine kinase activation","Ligand-gated ion channel activation","Nuclear receptor activation","Cytokine receptor activation"], ans:2, exp:"Ligand-gated ion channels (e.g. nicotinic ACh) open in milliseconds — the fastest response.", optExp: ["GPCRs take seconds.","RTKs take minutes.",null,"Nuclear receptors take hours-days.","Cytokine receptors take minutes-hours."] },
  { id:331, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Which is a GPCR?", opts:["Insulin receptor","Nicotinic acetylcholine receptor","β-adrenergic receptor","Cortisol receptor","NMDA receptor"], ans:2, exp:"β-adrenergic receptors are GPCRs (Gs → cAMP). Insulin = RTK, nicotinic = LGIC, cortisol = nuclear, NMDA = LGIC.", optExp: ["RTK.","LGIC.",null,"Nuclear receptor.","LGIC."] },
  { id:332, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Which is an example of a ligand-gated ion channel?", opts:["Muscarinic acetylcholine receptor","Nicotinic acetylcholine receptor","Insulin receptor","Steroid receptor","Adrenergic receptor"], ans:1, exp:"Nicotinic ACh receptors are pentameric LGICs that flux Na⁺/K⁺ when ACh binds.", optExp: ["Muscarinic = GPCR.",null,"Insulin = RTK.","Steroid = nuclear.","Adrenergic = GPCR."] },
  { id:333, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Insulin receptor is an example of a(n):", opts:["A G-protein coupled receptor","A receptor tyrosine kinase","A ligand-gated ion channel","A nuclear receptor","A voltage-gated ion channel"], ans:1, exp:"Insulin binds an RTK, triggering autophosphorylation, IRS, and downstream PI3K/MAPK signalling.", optExp: ["Glucagon is GPCR.",null,"Nicotinic is LGIC.","Steroids use nuclear.","Not a receptor type."] },
  { id:334, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Intracellular (nuclear) receptors are activated by:", opts:["Polar peptide hormones","Lipid-soluble hormones","Cytokine signalling molecules","Neurotransmitter molecules","Acetylcholine molecules"], ans:1, exp:"Steroid and thyroid hormones are lipid-soluble; they enter the cell and bind intracellular/nuclear receptors to alter gene expression.", optExp: ["Peptide hormones use surface receptors.",null,"Cytokines use cytokine receptors.","Neurotransmitters use LGICs/GPCRs.","ACh uses LGIC or GPCR."] },
  { id:335, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A full agonist is a drug that:", opts:["It has no effect on the receptor","It produces a maximal response at the receptor","It produces no cellular response","It produces a partial response at the receptor","It blocks all receptor activity"], ans:1, exp:"Full agonists fully activate the receptor (efficacy = 1). Partial agonists give submaximal response even at full occupancy.", optExp: ["That would be no binding/no efficacy.",null,"That would be an antagonist.","That is a partial agonist.","That is an antagonist."] },
  { id:336, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A competitive antagonist:", opts:["It cannot be overcome by increasing agonist concentration","It can be overcome by increasing the concentration of agonist","It has an efficacy of one","It permanently disables the receptor","It is the same as a partial agonist"], ans:1, exp:"Competitive antagonists shift the dose-response curve rightward; full Emax can still be reached with enough agonist.", optExp: ["Describes non-competitive/irreversible.",null,"Antagonists have efficacy 0.","Describes irreversible.","Partial agonists have some intrinsic activity."] },
  { id:337, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"The main site of oral drug absorption is the:", opts:["The stomach lining","The small intestine","The colon","The mouth cavity","The oesophagus"], ans:1, exp:"The small intestine, with villi and microvilli, has the largest absorptive surface area for oral drugs.", optExp: ["Stomach absorbs some acidic drugs but smaller area.",null,"Colon absorbs water and some drugs.","Mouth allows sublingual absorption for some.","Oesophagus is primarily transit."] },
  { id:338, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"First-pass metabolism refers to:", opts:["Metabolism of the drug in the intestines only","Metabolism and inactivation of the drug by the liver before systemic circulation","The process of renal clearance","The binding of the drug to plasma proteins","The absorption of the drug through the skin"], ans:1, exp:"Drugs absorbed from the gut pass through the liver via portal circulation, where significant metabolism can occur before reaching systemic circulation.", optExp: ["Intestinal first-pass is a component but liver dominates.",null,"That is renal elimination.","Plasma protein binding is unrelated.","Skin absorption is dermal route."] },
  { id:339, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Which route AVOIDS first-pass metabolism?", opts:["Oral administration","Sublingual or intravenous administration","Rectal suppository administration","Subcutaneous injection","Intramuscular injection"], ans:1, exp:"IV, sublingual, and (partially) rectal routes bypass the liver's portal circulation.", optExp: ["Oral has full first-pass.",null,"Rectal partly bypasses, not fully.","SC enters systemic but is not the most common bypass route mentioned.","IM enters systemic similarly."] },
  { id:340, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Phase I metabolism involves:", opts:["Conjugation reactions with glutathione or other molecules","Oxidation and hydrolysis reactions","Renal excretion of unchanged drug","Binding of the drug to plasma proteins","Activation of cellular receptors"], ans:1, exp:"Phase I involves functional group modifications by CYP450 (oxidation), reductases, and hydrolases.", optExp: ["That is Phase II.",null,"That is excretion.","Unrelated.","Unrelated."] },
  { id:341, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Phase II metabolism is:", opts:["An oxidation reaction","A conjugation reaction","A hydrolysis reaction","A renal excretion process","A receptor binding process"], ans:1, exp:"Phase II adds polar groups (glucuronide, sulfate, glutathione) to make drugs water-soluble for excretion.", optExp: ["That is Phase I.",null,"That is Phase I.","Different process.","Unrelated."] },
  { id:342, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A drug with a high volume of distribution (Vd) implies:", opts:["The drug is restricted to plasma","The drug distributes extensively into tissues","The drug is excreted unchanged in urine","The drug cannot cross cell membranes","The drug has poor oral absorption"], ans:1, exp:"High Vd suggests the drug leaves plasma and distributes extensively into tissues (e.g. lipophilic drugs, tissue-binding drugs).", optExp: ["Low Vd describes plasma confinement.",null,"Unrelated to Vd.","High Vd actually means easy crossing.","Vd is about distribution, not absorption."] },
  { id:343, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"The major route of drug excretion is:", opts:["Lungs","Skin","Faeces","Kidneys","Sweat glands"], ans:3, exp:"Most drugs are excreted by the kidneys via filtration, secretion, and limited reabsorption.", optExp: ["Volatile anaesthetics use lung route.","Some drugs excreted in sweat but minor.","Bile-excreted drugs may reach faeces.",null,"Minor route."] },
  { id:344, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A weakly acidic drug is best excreted in:", opts:["Acidic urine","Alkaline urine","A dehydrated state","High sodium intake","Faeces only"], ans:1, exp:"Weak acids are more ionised in alkaline urine → less reabsorbed → faster excretion. This is the basis of urinary alkalinisation in aspirin overdose.", optExp: ["Acidic urine keeps weak acids non-ionised, increasing reabsorption.",null,"Dehydration concentrates urine but doesn't enhance excretion.","Sodium isn't the relevant variable.","Acidic drugs go via kidney."] },
  { id:345, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Bioavailability (F) refers to:", opts:["The plasma concentration level achieved","The fraction of drug reaching systemic circulation","The elimination half-life value","The ability to bind to receptors","The therapeutic index value"], ans:1, exp:"Bioavailability = (AUC oral / AUC IV) × 100%. IV drugs have F = 100%.", optExp: ["Concentration is a measurement, not definition.",null,"That is half-life.","That is pharmacodynamics.","Therapeutic index is a safety metric."] },
  { id:346, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Half-life (t½) is the time for plasma drug concentration to:", opts:["The time to reach steady state","The time for plasma concentration to decrease by 50%","The time for complete drug elimination","The time for plasma protein binding to occur","The time to reach maximum concentration (Cmax)"], ans:1, exp:"t½ = time for plasma concentration to fall to half its value. After 4-5 half-lives, ~94-97% of drug is eliminated.", optExp: ["Steady state takes ~4-5 t½ with regular dosing.",null,"Complete elimination needs many half-lives.","Protein binding is a separate property.","Cmax is peak concentration."] },
  { id:347, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Drug absorption is enhanced by:", opts:["Low lipid solubility","High lipid solubility","An ionised form of the drug","Poor blood flow at the absorption site","Advanced age"], ans:1, exp:"Lipid-soluble drugs cross membranes more easily → better absorption.", optExp: ["Low lipid solubility = poor absorption.",null,"Non-ionised form is absorbed.","Good blood flow enhances absorption.","Old age can reduce absorption."] },
  { id:348, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"CYP450 enzymes are mainly found in the:", opts:["Brain tissue","Liver tissue","Kidney tissue","Pancreatic tissue","Lung tissue"], ans:1, exp:"CYP450 enzymes are most concentrated in hepatocyte smooth ER, performing most of Phase I drug metabolism.", optExp: ["Brain has some CYPs but minor.",null,"Kidneys have some CYPs.","Pancreas has minor CYP activity.","Lung has minor CYP activity."] },
  { id:349, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Plasma protein binding affects:", opts:["Drug absorption only","The free active concentration of drug","Phase I metabolism only","The half-life by shortening it","Renal clearance only"], ans:1, exp:"Only free (unbound) drug can leave the plasma to act on receptors or be metabolised/excreted. Highly bound drugs have prolonged effects.", optExp: ["Binding affects distribution/elimination more than absorption.",null,"Affects more than just Phase I.","Often lengthens half-life.","Affects clearance but not only."] },
  { id:350, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"The therapeutic index (TI) is defined as:", opts:["Calculated as ED50 divided by LD50","Calculated as LD50 divided by ED50","Calculated as Cmax divided by Cmin","Calculated as Vd divided by Cl","Calculated as dose multiplied by half-life"], ans:1, exp:"TI = LD50/ED50 (lethal dose for 50% / effective dose for 50%). Higher = safer drug (wider window).", optExp: ["Inverse of correct.",null,"Refers to drug exposure peak/trough.","Pharmacokinetic ratio.","No standard formula."] },
  { id:351, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Potency refers to:", opts:["The maximum effect a drug can produce","The dose required to produce a given effect","The bioavailability of the drug","The half-life of the drug","The volume of distribution of the drug"], ans:1, exp:"Potency relates to position on the dose-response curve (EC50). High potency = effect at low dose. Efficacy = max effect.", optExp: ["That is efficacy.",null,"PK parameter.","PK parameter.","PK parameter."] },
  { id:352, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Efficacy refers to:", opts:["The dose needed for therapeutic effect","The maximum response the drug can produce","The time to onset of action","The degree of toxicity","The selectivity for specific receptors"], ans:1, exp:"Efficacy = the maximum effect (Emax). Full agonists have high efficacy; partial agonists have lower efficacy.", optExp: ["That is potency.",null,"PK parameter.","Adverse effect parameter.","Receptor binding selectivity is separate."] },
  { id:353, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"An inverse agonist:", opts:["Produces no effect on the receptor","Activates the receptor fully","Reduces constitutive activity below basal levels","Acts as a competitive antagonist","Has an efficacy value of one"], ans:2, exp:"Inverse agonists stabilise the inactive receptor conformation, reducing constitutive activity below baseline.", optExp: ["That is a neutral antagonist (in some descriptions).","That is an agonist.",null,"Different mechanism — antagonist has zero efficacy, not negative.","That is full agonist."] },
  { id:354, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Tachyphylaxis is:", opts:["Slow onset of drug action","Rapid development of tolerance despite continued use","Slow drug elimination","Reduced drug absorption","Increased drug bioavailability"], ans:1, exp:"Tachyphylaxis = acute desensitisation over minutes-hours with repeated administration.", optExp: ["Different concept.",null,"PK property.","PK property.","PK property."] },
  { id:355, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Penicillins act by:", opts:["Inhibition of DNA gyrase","Inhibition of bacterial cell wall synthesis","Blockade of bacterial protein synthesis","Disruption of bacterial folate metabolism","Inhibition of bacterial RNA polymerase"], ans:1, exp:"Penicillins (β-lactams) inhibit penicillin-binding proteins (transpeptidases) needed for cross-linking peptidoglycan.", optExp: ["Quinolones do that.",null,"Macrolides/aminoglycosides do that.","Sulfonamides/trimethoprim do that.","Rifampicin does that."] },
  { id:356, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Aminoglycosides (e.g. gentamicin) target:", opts:["Binds the 30S ribosomal subunit","Binds the 50S ribosomal subunit","Inhibits bacterial cell wall synthesis","Inhibits DNA gyrase","Blocks folate synthesis"], ans:0, exp:"Aminoglycosides bind the 30S ribosomal subunit, causing misreading of mRNA and inhibiting protein synthesis.", optExp: [null,"Macrolides/chloramphenicol target 50S.","β-lactams target cell wall.","Quinolones target gyrase.","Sulfonamides target folate."] },
  { id:357, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Macrolides (e.g. erythromycin) act by:", opts:["Inhibits bacterial cell wall synthesis","Binds the 50S ribosomal subunit","Inhibits DNA gyrase","Blocks folate synthesis","Disrupts the bacterial cell membrane"], ans:1, exp:"Macrolides bind the 50S subunit, blocking peptide chain elongation.", optExp: ["β-lactams.",null,"Quinolones.","Sulfonamides.","Polymyxins."] },
  { id:358, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Fluoroquinolones (e.g. ciprofloxacin) inhibit:", opts:["Inhibits the 50S ribosomal subunit","Inhibits bacterial cell wall synthesis","Inhibits DNA gyrase","Blocks folate synthesis","Inhibits bacterial RNA polymerase"], ans:2, exp:"Quinolones inhibit DNA gyrase (gram-negative) and topoisomerase IV (gram-positive), preventing DNA replication.", optExp: ["Macrolides.","β-lactams.",null,"Sulfa drugs.","Rifampicin."] },
  { id:359, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Trimethoprim and sulfonamides inhibit:", opts:["Inhibits bacterial cell wall synthesis","Inhibits bacterial protein synthesis","Inhibits folate synthesis","Inhibits DNA gyrase","Inhibits bacterial RNA polymerase"], ans:2, exp:"Sulfonamides inhibit dihydropteroate synthase; trimethoprim inhibits dihydrofolate reductase — both block folate-dependent nucleotide synthesis.", optExp: ["β-lactams.","Aminoglycosides/macrolides.",null,"Quinolones.","Rifampicin."] },
  { id:360, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"Fertilisation typically occurs in the:", opts:["In the cervix","In the uterine cavity","In the ovary","In the fallopian tube","In the vagina"], ans:3, exp:"Sperm meets the ovum in the ampulla (lateral 1/3) of the fallopian tube within 24 hours of ovulation.", optExp: ["Cervix is the gateway, not site of fertilisation.","Implantation occurs there.","Ovulation occurs from ovary.",null,"Sperm pass through, not the site."] },
  { id:361, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"Implantation of the blastocyst typically occurs:", opts:["In the cervix on day 3","In the uterine fundus on days 6–7","In the fallopian tube on day 1","In the ovary on day 8","In the cervix on day 14"], ans:1, exp:"The blastocyst implants in the uterine endometrium (usually fundus) around day 6-7 post-fertilisation.", optExp: ["Cervix is incorrect site/time.",null,"Tubal implantation = ectopic pregnancy.","Ovarian = rare ectopic.","Too late."] },
  { id:362, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"During week 2, the inner cell mass forms:", opts:["Cytotrophoblast layer","Epiblast and hypoblast","Endoderm and mesoderm","Neural tube","Notochord"], ans:1, exp:"Week 2 = bilaminar disc: the inner cell mass forms epiblast (dorsal) and hypoblast (ventral).", optExp: ["Trophoblast differentiates separately.",null,"Endoderm/mesoderm form in week 3.","Neural tube is week 3-4.","Notochord forms in week 3."] },
  { id:363, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"In week 2, the trophoblast differentiates into:", opts:["Epiblast and hypoblast","Cytotrophoblast and syncytiotrophoblast","Hypoblast only","Notochord","Somites"], ans:1, exp:"Trophoblast → cytotrophoblast (inner, mitotic) + syncytiotrophoblast (outer, invasive, hormone-producing).", optExp: ["That's the embryoblast.",null,"Germ layers in week 3.","Mesodermal structures in week 3-4.","Cavities form in week 2 but are separate."] },
  { id:364, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"hCG is produced by:", opts:["Cytotrophoblast cells","Syncytiotrophoblast cells","Corpus luteum cells","Fetal liver cells","Embryoblast cells"], ans:1, exp:"Syncytiotrophoblast produces hCG, which maintains the corpus luteum to sustain progesterone in early pregnancy.", optExp: ["Cytotrophoblast is the proliferative inner layer.",null,"Corpus luteum makes progesterone in response to hCG.","Fetal liver makes AFP.","Embryoblast becomes the embryo."] },
  { id:365, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"Gastrulation occurs during which week of development?", opts:["Week 1","Week 2","Week 3","Week 4","Week 5"], ans:2, exp:"Gastrulation occurs in week 3, forming the three germ layers from the epiblast via the primitive streak.", optExp: ["Week 1 is fertilisation/cleavage.","Week 2 is bilaminar disc.",null,"Week 4 is organogenesis.","Week 5+ is later organogenesis."] },
  { id:366, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"The first visible sign of gastrulation is:", opts:["Notochord formation","Neural groove formation","Primitive streak formation","Amniotic cavity formation","Yolk sac formation"], ans:2, exp:"The primitive streak appears on the dorsal epiblast, marking the start of gastrulation and the body's craniocaudal axis.", optExp: ["Notochord forms after streak.","Neural groove is later.",null,"Amniotic cavity forms in week 2.","Yolk sac forms in week 2."] },
  { id:367, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"During gastrulation, epiblast cells that migrate through the primitive streak and DISPLACE hypoblast become:", opts:["Ectoderm","Mesoderm","Endoderm","Notochord","Amnion"], ans:2, exp:"First migrating epiblast cells push hypoblast aside and form endoderm; later migrants form mesoderm; remaining epiblast = ectoderm.", optExp: ["Ectoderm stays in the epiblast.","Mesoderm forms between layers.",null,"Notochord forms from specific mesoderm.","Amnion is from epiblast originally."] },
  { id:368, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"Which germ layer gives rise to the nervous system?", opts:["Endoderm","Mesoderm","Ectoderm","Trophoblast","Hypoblast"], ans:2, exp:"Neural tube derived from ectoderm forms the CNS; neural crest cells form much of PNS.", optExp: ["Gut tube and derivatives.","Connective tissue, muscle, heart, etc.",null,"Forms placenta.","Replaced during gastrulation."] },
  { id:369, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"Which germ layer gives rise to the gut epithelium, liver, and pancreas?", opts:["Ectoderm","Mesoderm","Endoderm","Notochord","Neural crest"], ans:2, exp:"Endoderm forms the lining of the GI tract, respiratory tract, and parenchyma of liver/pancreas.", optExp: ["Ectoderm forms epidermis and CNS.","Mesoderm forms muscle, bone, kidneys, cardiovascular.",null,"Notochord induces neural tube.","Neural crest forms PNS, melanocytes, etc."] },
  { id:370, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"The notochord:", opts:["Becomes the spinal cord","Induces neural tube formation","Forms the heart","Forms the gut","Forms the limbs"], ans:1, exp:"The notochord is a mesodermal structure that induces overlying ectoderm to form the neural plate; persists as nucleus pulposus in adult.", optExp: ["Spinal cord forms from neural tube.",null,"Heart from cardiogenic mesoderm.","Gut from endoderm.","Limbs from limb bud mesoderm."] },
  { id:371, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"The Sonic Hedgehog (SHH) pathway primarily controls:", opts:["Apoptosis during development","Body axis formation","Cytokinesis and cell division","Embryonic implantation","Placental development"], ans:1, exp:"SHH signalling regulates left-right asymmetry, limb patterning (digit number), ventral CNS, and many other developmental processes.", optExp: ["SHH is not primarily an apoptosis pathway.",null,"Not its main role.","SHH not directly involved in implantation.","Trophoblast handles placental formation."] },
  { id:372, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"The Notch signalling pathway controls:", opts:["Primary body axis formation","Cell fate determination and differentiation","Embryonic implantation","Placental development","Gastrulation movements"], ans:1, exp:"Notch signalling determines cell fate via direct cell-cell contact (NICD cleavage activates target genes). Mutations cause cancer or developmental defects.", optExp: ["SHH governs axis.",null,"Not Notch's role.","Trophoblast handles placentation.","Driven by other pathways."] },
  { id:373, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"Organogenesis primarily occurs during:", opts:["Weeks 1–2 of pregnancy","Week 3 of pregnancy","Weeks 4–8 of pregnancy","Weeks 12–16 of pregnancy","During the third trimester"], ans:2, exp:"Most organs form between weeks 4-8 (embryonic period). The fetal period (week 9-birth) is for growth and maturation.", optExp: ["Early cleavage and bilaminar disc.","Gastrulation.",null,"Fetal period.","Growth phase, not organogenesis."] },
  { id:374, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"During the fetal period (week 9 onwards):", opts:["Organs first form and differentiate","Organs grow and mature in function","Implantation of the blastocyst occurs","Gastrulation and germ layer formation occurs","The bilaminar disc is formed"], ans:1, exp:"Fetal period is mostly growth and functional maturation of organs that formed earlier.", optExp: ["Organs form in embryonic period.",null,"Implantation is week 1.","Gastrulation is week 3.","Bilaminar disc is week 2."] },
  { id:375, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"Neural tube closes around which day post-fertilisation?", opts:["Around day 7 post-fertilisation","Around day 14 post-fertilisation","Around days 21–28 post-fertilisation","Around day 60 post-fertilisation","Around week 12 post-fertilisation"], ans:2, exp:"Neural tube closure begins ~day 22 and completes by day 28. Failure → neural tube defects (spina bifida, anencephaly).", optExp: ["Implantation timeline.","Gastrulation completing.",null,"Far later in development.","Far later."] },
  { id:376, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"Folate supplementation in pregnancy reduces risk of:", opts:["Risk of cleft palate","Risk of neural tube defects","Risk of trisomy 21","Risk of congenital cardiac defects","Risk of limb malformations"], ans:1, exp:"Folate supplementation prior to conception and in early pregnancy significantly reduces neural tube defects.", optExp: ["Some weak association but not primary.",null,"Down syndrome is chromosomal nondisjunction.","Folate not strongly protective for cardiac.","Limb defects unrelated."] },
  { id:377, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The heart has how many chambers?", opts:["2 chambers","3 chambers","4 chambers","5 chambers","6 chambers"], ans:2, exp:"Four chambers: right atrium, right ventricle, left atrium, left ventricle.", optExp: ["Fish hearts.","Amphibians.",null,"Includes coronary sinus, but standard answer is 4.","Too many."] },
  { id:378, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The left ventricle pumps blood into the:", opts:["The pulmonary trunk","The aorta","The superior vena cava","The pulmonary veins","The inferior vena cava"], ans:1, exp:"LV → aorta → systemic circulation. RV → pulmonary trunk → lungs.", optExp: ["RV pumps into pulmonary trunk.",null,"SVC drains into RA.","Pulmonary veins return to LA.","IVC drains into RA."] },
  { id:379, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The right atrium receives blood from:", opts:["The pulmonary veins","The superior vena cava, inferior vena cava, and coronary sinus","The aorta","The left ventricle","The hepatic veins"], ans:1, exp:"RA receives deoxygenated blood from SVC, IVC, and coronary sinus.", optExp: ["LA receives pulmonary veins.",null,"Aorta exits LV.","LV is downstream.","Hepatic veins drain into IVC."] },
  { id:380, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The bicuspid (mitral) valve is between:", opts:["The right atrium and right ventricle","The right ventricle and pulmonary artery","The left atrium and left ventricle","The left ventricle and aorta","The superior vena cava and right atrium"], ans:2, exp:"Mitral (bicuspid) valve sits between LA and LV. Tricuspid is right-sided. SL valves at outflows.", optExp: ["Tricuspid valve.","Pulmonary valve.",null,"Aortic valve.","No valve there."] },
  { id:381, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The first branch of the aorta is the:", opts:["The left common carotid artery","The brachiocephalic trunk","The right subclavian artery","The left coronary artery","The right coronary artery"], ans:4, exp:"The first branches of the aorta are the coronary arteries (from the aortic sinuses). Brachiocephalic is the first arch branch.", optExp: ["This is from the arch.","First arch branch, but coronaries arise even earlier from the root.","Branches off brachiocephalic.","Third arch branch.",null] },
  { id:382, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The left coronary artery (LCA) divides into:", opts:["The posterior descending artery and right marginal artery","The left anterior descending artery and circumflex artery","The right coronary artery and circumflex artery","The left anterior descending artery and diagonal branches","The marginal artery and posterior descending artery"], ans:1, exp:"LCA divides into the LAD (left anterior descending) and circumflex artery, supplying most of the left ventricle.", optExp: ["Those are from RCA.",null,"RCA is independent.","LCA also gives circumflex.","Those are right-sided branches."] },
  { id:383, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"In ~80% of people, the posterior descending artery (PDA) arises from the:", opts:["From the left anterior descending artery","From the left circumflex artery","From the right coronary artery","From the aorta directly","From the left main coronary artery"], ans:2, exp:"~80% of people are right-coronary dominant — PDA arises from RCA, supplying inferior LV and posterior septum.", optExp: ["LAD is anterior.","Left dominant in ~10%.",null,"PDA never arises from aorta directly.","Never from pulmonary artery."] },
  { id:384, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The SA node is located in the:", opts:["The interventricular septum","The right atrium at the entrance of the superior vena cava","The left atrium","The cardiac apex","The atrioventricular groove"], ans:1, exp:"SA node sits in the right atrial wall near the superior vena cava entry — the heart's natural pacemaker.", optExp: ["Bundle branches are here.",null,"LA is not the pacemaker location.","Apex is far from pacemaker.","AV node is in the AV groove."] },
  { id:385, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The AV node delays conduction to allow:", opts:["Allow adequate ventricular filling before contraction","Increase the heart rate during exercise","Stimulate the SA node to fire","Prolong the diastolic phase","Open the mitral valve"], ans:0, exp:"AV nodal delay (~100 ms) allows the atria to fully empty into the ventricles before ventricular contraction.", optExp: [null,"Slower, not faster.","SA fires independently.","Diastole is its own phase.","Mitral valve opens during diastole."] },
  { id:386, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The vagus nerve (CN X) provides parasympathetic innervation to the heart, primarily slowing the:", opts:["SA node firing rate","AV node conduction velocity","Ventricular contraction force","Ventricular repolarization time","Aortic baroreceptor sensitivity"], ans:0, exp:"Vagal stimulation slows SA node firing (also slows AV conduction). Has minimal effect on ventricular contractility.", optExp: [null,"Vagal effect on ventricular force is minimal.","AV node is also affected, but SA is primary.","Vagus has limited ventricular contact.","Baroreceptors send signals TO vagus, not from."] },
  { id:387, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Cardiac veins drain into the:", opts:["Left atrium","Right atrium","Right ventricle","Aorta","Superior vena cava"], ans:1, exp:"Most cardiac venous blood drains into the coronary sinus, which empties into the right atrium.", optExp: ["LA receives pulmonary veins.",null,"RV receives from RA.","Aorta receives from LV.","SVC drains body, not heart."] },
  { id:388, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The thoracic duct drains into the:", opts:["Right subclavian vein","Left subclavian vein","Aorta","Inferior vena cava","Hepatic portal vein"], ans:1, exp:"The thoracic duct (largest lymphatic vessel) drains most of the body's lymph into the left venous angle (junction of left subclavian and internal jugular).", optExp: ["Right lymphatic duct drains there.",null,"Aorta is arterial.","IVC is venous, not lymph drainage.","Portal vein is for GI venous return."] },
  { id:389, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The right lymphatic duct drains lymph from the:", opts:["Lower body and left upper body","Right head, neck, and right arm","Left lower limb only","Entire body except right upper quadrant","Gastrointestinal tract and spleen only"], ans:1, exp:"The right lymphatic duct drains the right upper quadrant; thoracic duct drains the rest.", optExp: ["Drained by thoracic duct.",null,"Thoracic duct.","Thoracic duct drains most.","Thoracic duct via cisterna chyli."] },
  { id:390, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Primary lymphoid organs include:", opts:["Bone marrow and thymus","Spleen and lymph nodes","Tonsils and adenoids","Peyer's patches only","Appendix only"], ans:0, exp:"Primary lymphoid organs (where lymphocytes mature) = bone marrow (B cells) and thymus (T cells). Secondary = spleen, LNs, MALT.", optExp: [null,"Spleen and lymph nodes are secondary lymphoid organs.","Tonsils are secondary.","Peyer's patches are secondary.","Appendix is secondary lymphoid."] },
  { id:391, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Lymph nodes function to:", opts:["Filter lymph and present antigens","Produce red blood cells","Store fat reserves","Detoxify drugs and medications","Produce bile"], ans:0, exp:"Lymph nodes filter antigens from lymph and present them to lymphocytes, initiating adaptive responses.", optExp: [null,"Bone marrow produces RBCs.","Adipose stores fat.","Liver detoxifies.","Liver makes bile."] },
  { id:392, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The spleen is located in which abdominal quadrant?", opts:["Right upper quadrant","Left upper quadrant","Right lower quadrant","Left lower quadrant","Central epigastric region"], ans:1, exp:"The spleen sits in the left upper quadrant, posterior to ribs 9-11, lateral to the stomach.", optExp: ["Liver is in RUQ.",null,"Appendix in RLQ.","Sigmoid colon in LLQ.","Central is umbilical."] },
  { id:393, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The spleen's white pulp contains:", opts:["Reticulocytes only","Lymphoid tissue and lymphocytes","Hepatocytes and adipocytes","Mature erythrocytes only","Fibroblasts and collagen fibres only"], ans:1, exp:"White pulp contains periarteriolar lymphoid sheaths (PALS, T cells) and B cell follicles. Red pulp filters blood and stores platelets.", optExp: ["Red pulp deals with RBCs.",null,"Liver-specific.","Adipose has those.","Bone marrow has those."] },
  { id:394, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The cisterna chyli is found at the level of:", opts:["C7 vertebral level","T1 vertebral level","L1-L2 vertebral level","S1 vertebral level","Diaphragmatic hiatus"], ans:2, exp:"Cisterna chyli is a saccular dilation at the start of the thoracic duct at L1-L2, receiving lumbar and intestinal trunks.", optExp: ["Too high.","Too high.",null,"Too low.","Diaphragmatic hiatus is at T12 — close but L1-L2 is the standard answer."] },
  { id:395, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Lymphoedema can result from:", opts:["High protein intake","Lymphatic vessel obstruction or removal","Anemia or low hemoglobin levels","Hypoglycemia or low blood glucose","Hyperthyroidism or excess thyroid hormone"], ans:1, exp:"Obstruction or removal of lymphatic vessels (e.g. mastectomy with axillary clearance, filariasis) causes lymph accumulation.", optExp: ["Diet alone doesn't cause lymphoedema.",null,"Anaemia causes pallor.","Hypoglycaemia is metabolic.","Hyperthyroidism causes pretibial myxoedema in Graves, but different."] },
  { id:396, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The thymus is most active in:", opts:["During old age","During adulthood","During infancy and childhood","During pregnancy","During senescence and aging"], ans:2, exp:"Thymus is most active in early life, producing mature T cells. It involutes (shrinks) after puberty.", optExp: ["Atrophies with age.","Largely involuted.",null,"Pregnancy doesn't reactivate thymus.","Not applicable."] },
  { id:399, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"In skeletal muscle during exercise, lactate is produced because:", opts:["Mitochondria are absent in muscle cells","Glycolysis rate exceeds oxidative capacity","Acetyl-CoA inhibits pyruvate dehydrogenase","ATP levels decrease significantly","TCA cycle activity stops completely"], ans:1, exp:"During intense exercise, glycolysis outpaces oxidative phosphorylation; LDH regenerates NAD⁺ from NADH by reducing pyruvate to lactate.", optExp: ["Muscle has mitochondria.",null,"Acetyl-CoA inhibition is part of regulation but not the cause.","ATP is being USED, not absent.","TCA continues but capacity is exceeded."] },
  { id:401, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Allosteric activators of enzymes typically:", opts:["Bind to the active site","Bind to a regulatory site distant from the active site","Permanently bind to the enzyme","Bind to the enzyme-substrate complex","Have no effect on enzyme Vmax"], ans:1, exp:"Allosteric activators bind regulatory sites distinct from the active site, often shifting the enzyme toward its high-affinity (R) state.", optExp: ["Substrates and competitive ligands bind active site.",null,"Allosteric modulators are usually reversible.","That is uncompetitive inhibitor behaviour.","Allosteric activators often increase Vmax/affinity."] },
  { id:402, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A coenzyme differs from a cofactor in that coenzymes are:", opts:["Inorganic ions only","Organic molecules that serve as cofactors","Identical to the substrate molecule","Permanently bound to enzymes","Lipid molecules exclusively"], ans:1, exp:"Cofactors include both inorganic (metal ions) and organic (coenzymes — often vitamin-derived) helpers. Coenzymes are organic.", optExp: ["Inorganic ions are cofactors generally.",null,"Coenzymes assist but aren't substrates per se.","Some are loosely bound (e.g. NAD⁺).","Not all are lipids."] },
  { id:403, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"NAD⁺ functions as a:", opts:["Phosphate group donor","Electron acceptor in redox reactions","Acetyl group carrier","Methyl group donor","Glucose transport protein"], ans:1, exp:"NAD⁺ accepts electrons (becoming NADH) in catabolic reactions; NADP⁺/NADPH is for biosynthesis.", optExp: ["ATP/GTP donate phosphate.",null,"Acetyl-CoA donates acetyl.","SAM is methyl donor.","Glucose has its own transporters."] },
  { id:404, cat:"Enzymes & Enzyme Kinetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The turnover number (kcat) refers to:", opts:["Maximum substrate concentration at enzyme saturation","Number of substrate molecules converted per enzyme molecule per unit time","Substrate concentration at half-maximal velocity","Half-life of the enzyme molecule","Maximum reaction velocity of the enzyme"], ans:1, exp:"kcat = Vmax/[Etotal] = molecules of substrate converted per enzyme molecule per second at saturation.", optExp: ["Substrate concentration is separate.",null,"Km is half-saturation [S].","Half-life is for drug PK.","Vmax is rate, not turnover per enzyme."] },
  { id:405, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"Sex chromosomes in a normal human male are:", opts:["XX","XY","XO","XXY","XYY"], ans:1, exp:"Normal male karyotype is 46,XY. XX is female; XO is Turner; XXY is Klinefelter; XYY is Jacobs.", optExp: ["Female.",null,"Turner syndrome.","Klinefelter.","Jacobs syndrome."] },
  { id:406, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"In Duchenne muscular dystrophy, the affected gene encodes:", opts:["Myosin protein","Actin protein","Dystrophin protein","Collagen protein","Titin protein"], ans:2, exp:"DMD is caused by dystrophin gene mutations (X-linked recessive), leading to fragile muscle membranes.", optExp: ["Myosin defects cause cardiomyopathies.","Actin defects cause myopathies but not DMD.",null,"Collagen defects cause OI.","Titin defects cause other myopathies."] },
  { id:407, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Myotonic dystrophy is caused by:", opts:["Dystrophin gene deletion","CTG repeat expansion in DMPK gene","CAG repeat expansion in HTT gene","CFTR gene mutation","Type I collagen gene mutation"], ans:1, exp:"Myotonic dystrophy (autosomal dominant) results from CTG repeat expansion in DMPK, with genetic anticipation.", optExp: ["That is DMD.",null,"That is Huntington.","That is CF.","That is OI."] },
  { id:408, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Angelman syndrome results from:", opts:["Paternal 15q11-q13 deletion or maternal uniparental disomy","Maternal 15q11-q13 deletion or paternal uniparental disomy","Trisomy 21","X-linked recessive mutation","Mitochondrial inheritance pattern"], ans:1, exp:"Angelman = loss of the maternal contribution of 15q11-13 (deletion or paternal UPD), causing severe intellectual disability and 'happy puppet' features.", optExp: ["That is Prader-Willi.",null,"Down is unrelated.","Not X-linked.","Not mitochondrial."] },
  { id:409, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"Prader-Willi syndrome results from:", opts:["Paternal 15q11-q13 deletion or maternal uniparental disomy","Maternal 15q11-q13 deletion or paternal uniparental disomy","Trisomy 21","X-linked dominant mutation","Mitochondrial inheritance pattern"], ans:0, exp:"Prader-Willi = loss of paternal contribution to 15q11-13 → obesity, short stature, hypotonia.", optExp: [null,"That is Angelman.","Down is unrelated.","Not X-linked.","Not mitochondrial."] },
  { id:410, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"At the G2 checkpoint, the cell ensures:", opts:["DNA replication is complete before mitosis","Cell reaches adequate size for division","Spindle apparatus is properly assembled","Cytokinesis completes properly","Apoptosis pathway is activated"], ans:0, exp:"G2/M checkpoint verifies DNA was replicated correctly and undamaged before allowing mitosis.", optExp: [null,"Size check is more in G1.","Spindle checkpoint is at metaphase-anaphase transition.","Cytokinesis is after M.","Apoptosis is when checkpoints fail."] },
  { id:411, cat:"Genetics: Epigenetics", year:"Year 1", block:"Principles", deck:"Genetics", q:"A Barr body is:", opts:["Inactivated X chromosome","Extra Y chromosome","Nucleolus structure","Mitochondrion in cytoplasm","Spliceosome in nucleus"], ans:0, exp:"The Barr body is the inactivated X chromosome (via XIST), visible as a dense structure in female somatic cells.", optExp: [null,"Not Y-related.","Different structure.","Different organelle.","Different complex."] },
  { id:412, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"At resting potential, K⁺ tends to:", opts:["Be actively pumped inward","Leak outward down its concentration gradient","Remain stationary inside the cell","Be actively pumped outward","Bind to the Na⁺/K⁺-ATPase pump protein"], ans:1, exp:"K⁺ leak channels allow K⁺ to flow out down its gradient, contributing to the negative resting Vm.", optExp: ["K⁺ concentration is higher inside.",null,"Ions always move.","Pumped IN, not out.","Pumps move K⁺ in."] },
  { id:413, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"The functional unit of striated muscle is the:", opts:["Sarcolemma membrane","Sarcomere from Z-line to Z-line","Single myofibril","Endomysium connective tissue","Bundle of muscle fibers"], ans:1, exp:"A sarcomere extends from one Z-disc to the next and contains the actin/myosin filaments that produce contraction.", optExp: ["Sarcolemma is the membrane.",null,"Myofibrils are bundles of sarcomeres.","Endomysium surrounds fibres.","Fasciculus is a bundle of fibres."] },
  { id:414, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"The cerebellum primarily controls:", opts:["Sound and hearing processing","Coordination and motor control","Vision and light processing","Emotional regulation","Memory storage"], ans:1, exp:"The cerebellum coordinates movement, balance, and fine motor control. Dysfunction causes ataxia, dysmetria, dysarthria.", optExp: ["Hearing is temporal lobe.",null,"Vision is occipital.","Emotion involves limbic system.","Memory involves hippocampus."] },
  { id:415, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Which structure controls vital functions like breathing and heart rate?", opts:["Cerebellum","Cerebrum","Hypothalamus","Medulla oblongata","Thalamus"], ans:3, exp:"The medulla houses cardiac, respiratory, and vasomotor centres essential for survival.", optExp: ["Cerebellum is coordination.","Cerebrum is higher cognition.","Hypothalamus regulates homeostasis (temp, hunger, hormones).",null,"Thalamus is sensory relay."] },
  { id:416, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Sympathetic preganglionic neurons originate from:", opts:["Brainstem nuclei","Thoracolumbar spinal cord segments T1–L2","Sacral spinal cord segments S2–S4","Cranial nerve nuclei","Adrenal medulla"], ans:1, exp:"SNS preganglionics arise from T1-L2 (thoracolumbar outflow), synapsing in paravertebral chain ganglia.", optExp: ["PNS uses cranial nuclei (III, VII, IX, X).",null,"PNS uses S2-S4.","Brainstem is PNS.","Adrenal medulla is a target, not origin."] },
  { id:417, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Parasympathetic outflow comes from:", opts:["Cranial nerves and sacral spinal cord segments S2–S4","Thoracolumbar spinal cord segments T1–L2","Cervical spinal cord segments C1–C8","Adrenal medulla","Sympathetic chain ganglia"], ans:0, exp:"PNS = craniosacral: CN III, VII, IX, X and sacral S2-S4. SNS = thoracolumbar (T1-L2).", optExp: [null,"That is SNS.","No PNS comes from cervical only.","Adrenal medulla is SNS target.","Not the parasympathetic source."] },
  { id:418, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"cAMP is the second messenger downstream of:", opts:["Gs and Gi protein coupling","Gq protein coupling","Receptor tyrosine kinases","Nuclear receptor activation","Ligand-gated ion channels"], ans:0, exp:"Gs activates adenylyl cyclase → ↑ cAMP; Gi inhibits AC → ↓ cAMP. Gq → IP3/DAG.", optExp: [null,"Gq → PLC → IP3/DAG.","RTKs use various cascades.","Nuclear receptors alter transcription.","LGICs gate ions, not second messengers."] },
  { id:419, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"IP3 (inositol trisphosphate) acts to:", opts:["Opens endoplasmic reticulum calcium channels","Activates adenylate cyclase enzyme","Opens sodium channels in the plasma membrane","Directly phosphorylates target proteins","Cleaves membrane proteins"], ans:0, exp:"IP3 binds receptors on the ER/SR, releasing stored Ca²⁺ into the cytoplasm.", optExp: [null,"That is Gs/Gαs.","Different pathway.","PKC does that.","Not its function."] },
  { id:420, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Eosinophils are especially important against:", opts:["Bacterial infection response","Parasitic and allergic responses","Viral infection response only","Fungal infection response only","Tumor cell elimination only"], ans:1, exp:"Eosinophils release major basic protein and ECP, killing helminths. They also contribute to allergic inflammation.", optExp: ["Neutrophils are anti-bacterial.",null,"NK cells and T cells fight viruses.","Neutrophils handle most fungi.","NK cells primarily fight tumours."] },
  { id:421, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Basophils release:", opts:["Secretion of immunoglobulin G","Release of histamine and heparin","Production of surfactant proteins","Activation of complement proteins","Secretion of mucus"], ans:1, exp:"Basophils (and mast cells) release histamine and heparin granules in allergic responses.", optExp: ["B cells make IgG.",null,"Type II pneumocytes make surfactant.","Liver makes complement.","Goblet cells make mucus."] },
  { id:422, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Cytotoxic T cells (CD8+) recognise antigen presented on:", opts:["MHC class II molecules","MHC class I molecules","Both MHC class I and II equally","Antibodies on the cell surface","Toll-like receptors"], ans:1, exp:"CD8+ T cells recognise endogenous peptides on MHC I expressed by virtually all nucleated cells.", optExp: ["CD4+ recognises MHC II.",null,"CD8+ is MHC I restricted.","TCR recognises MHC-peptide, not antibody.","TLRs are innate."] },
  { id:423, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"B cell receptor (BCR) is essentially a membrane-bound form of:", opts:["T cell receptor","Membrane-bound antibody","Complement protein","Cytokine signaling molecule","MHC molecule"], ans:1, exp:"BCR is a membrane-anchored immunoglobulin (initially IgM/IgD), with similar antigen-binding specificity as secreted antibodies.", optExp: ["TCR is a different receptor on T cells.",null,"Complement is a separate cascade.","Cytokines are signalling molecules.","MHC presents antigens."] },
  { id:424, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Vaccination provides which type of immunity?", opts:["Passive natural immunity","Passive artificial immunity","Active artificial immunity","Active natural immunity","Innate immunity"], ans:2, exp:"Vaccination = active artificial immunity — the immune system mounts its own response to a controlled antigen exposure, creating memory.", optExp: ["Passive natural = maternal antibodies.","Passive artificial = giving antibodies (IVIG).",null,"Active natural = natural infection.","Innate is non-specific, no memory."] },
  { id:425, cat:"Immune System Overview", year:"Year 1", block:"Principles", deck:"Immunology", q:"Passive immunity from breast milk is mediated mainly by:", opts:["IgG antibodies","IgM antibodies","IgA antibodies","IgE antibodies","IgD antibodies"], ans:2, exp:"Secretory IgA in colostrum and breast milk provides mucosal protection to the infant's gut.", optExp: ["IgG crosses placenta but not main in milk.","IgM is too large.",null,"IgE is for allergy.","IgD is BCR."] },
  { id:426, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Reversible cell injury features include:", opts:["Nuclear fragmentation","Cell swelling and fat accumulation","Coagulative necrosis","DNA fragmentation in a patterned manner","Cell membrane rupture"], ans:1, exp:"Hallmarks of reversible injury: cellular swelling (hydropic change), fatty change, and ribosome detachment. Necrosis features are irreversible.", optExp: ["That is apoptosis/necrosis.",null,"That is necrosis.","That is apoptosis.","Membrane integrity loss = irreversible."] },
  { id:427, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Apoptosis is regulated by:", opts:["Random cellular destruction","Activation of caspases","Lysosomal enzyme action only","Complement system activation","Nitric oxide release alone"], ans:1, exp:"Caspases are cysteine proteases that execute apoptosis (initiator caspases 8/9 → effector caspases 3/6/7).", optExp: ["Apoptosis is regulated, not random.",null,"Lysosomes are for autophagy.","Complement is innate immunity.","NO is involved in macrophage killing but not the executioner."] },
  { id:428, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Pus is a mixture of:", opts:["Dead neutrophils and tissue fluid","Bacterial cells only","Lymphocyte cells only","Plasma fluid only","Bile fluid only"], ans:0, exp:"Pus is purulent exudate composed of dead/dying neutrophils, tissue debris, and oedema fluid.", optExp: [null,"Bacteria may be present but not alone.","Lymphocytes dominate chronic, not acute pus.","Plasma is acellular.","Bile is from liver."] },
  { id:429, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Resolution after acute inflammation is most likely when:", opts:["Extensive tissue destruction is present","Minimal tissue damage allowing regeneration","Granuloma formation occurs","Fibrosis becomes the dominant feature","Chronic infection continues"], ans:1, exp:"Complete resolution occurs when injury is limited and tissue stem cells can regenerate normal architecture.", optExp: ["Extensive destruction → repair by fibrosis.",null,"Granulomas indicate chronicity.","Fibrosis = scarring, not resolution.","Chronic persistence prevents resolution."] },
  { id:430, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Oncogenes:", opts:["Dominant gain-of-function mutations","Recessive loss-of-function mutations","Silent genetic mutations with no effect","Recessive inheritance pattern only","Apoptosis trigger genes"], ans:0, exp:"Oncogenes (e.g. RAS, MYC) are activated proto-oncogenes; one mutated copy can drive uncontrolled growth.", optExp: [null,"Tumour suppressors are different (e.g. p53, Rb).","Silent has no effect.","TSGs are recessive at cellular level.","Oncogenes prevent apoptosis."] },
  { id:431, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Tumour suppressor genes (e.g. p53, Rb):", opts:["Activated and overexpressed in cancer cells","Lost or inactivated in both alleles (two-hit hypothesis)","Dominant gain-of-function mutations","Oncogene type genes","Never mutated in human cancers"], ans:1, exp:"Knudson's two-hit hypothesis: both alleles of a TSG must be inactivated. p53 is mutated in >50% of cancers.", optExp: ["Inactivated, not activated.",null,"They're recessive at cellular level.","Different category.","Frequently mutated."] },
  { id:432, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Atrial fibrillation predisposes to thromboembolism mainly via:", opts:["Endothelial injury from rapid arrhythmia","Blood stasis in the left atrial appendage","Genetic hypercoagulability state","Increased blood viscosity state","Formation of fat emboli"], ans:1, exp:"Loss of coordinated atrial contraction leads to stasis (especially in left atrial appendage), promoting thrombus formation → stroke risk.", optExp: ["Not the predominant factor.",null,"Possible in some but not classic AF.","Not characteristic.","Different mechanism entirely."] },
  { id:433, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"An infarct in the brain typically heals by:", opts:["Coagulative necrosis with scar formation","Liquefactive necrosis with cyst formation","Caseous necrosis formation","Fat necrosis formation","Complete tissue regeneration"], ans:1, exp:"CNS neurons cannot regenerate; necrotic tissue liquefies, leaving a fluid-filled cyst surrounded by gliosis (astrocyte scar).", optExp: ["Most other organs use coagulative + fibrosis.",null,"Caseous is TB-related.","Fat necrosis is pancreatic.","Neurons do not regenerate normally."] },
  { id:434, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Osteoid is:", opts:["Mineralised bone matrix","Unmineralised organic matrix of bone","Cartilage tissue","Bone marrow tissue","Cement substance"], ans:1, exp:"Osteoid is the protein-rich, unmineralised matrix laid down by osteoblasts; calcium phosphate later mineralises it to form bone.", optExp: ["Osteoid is pre-mineralised.",null,"Different tissue.","Bone marrow is haematopoietic.","Not a biological term in this context."] },
  { id:435, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"The Haversian system (osteon) contains:", opts:["Central canal containing blood vessels","Muscle fiber bundles","Nerve fibers only","Cartilage matrix only","Bone marrow only"], ans:0, exp:"Each osteon has a Haversian canal (vessels/nerves) surrounded by concentric lamellae, with osteocytes in lacunae linked by canaliculi.", optExp: [null,"Not a muscle structure.","Vessels are also present.","No cartilage.","Marrow is in spongy bone."] },
  { id:436, cat:"Histology: Connective Tissue", year:"Year 1", block:"Principles", deck:"Histology", q:"Mast cells contain granules of:", opts:["Insulin and glucagon","Histamine and heparin","Bilirubin and bile pigments","Acetylcholine and serotonin","Proteoglycans and collagen"], ans:1, exp:"Mast cells store histamine, heparin, tryptase — released on IgE crosslinking in allergy/anaphylaxis.", optExp: ["Pancreatic β cells.",null,"Liver process.","Liver process.","Neuronal vesicles."] },
  { id:437, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Striations in muscle are due to:", opts:["Random organelle arrangement","Alternating A and I bands with thick and thin filaments","Glycogen deposits throughout muscle fibers","Mitochondrial clusters in rows","Calcium crystal deposition in matrix"], ans:1, exp:"The repeating sarcomere structure with overlapping actin/myosin produces alternating dark (A) and light (I) bands visible as striations.", optExp: ["Striations are highly organised.",null,"Glycogen doesn't cause striations.","Mitochondria don't cause this pattern.","No calcium crystals."] },
  { id:438, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Tachyphylaxis differs from tolerance in that tachyphylaxis develops:", opts:["Over weeks to months with continuous drug exposure","Over minutes to hours with repeated dosing","Only in elderly patients receiving treatment","Only with placebo and inactive compounds","Only with antibiotic drug classes"], ans:1, exp:"Tachyphylaxis = rapid (acute) desensitisation. Tolerance develops over days-weeks.", optExp: ["That is tolerance.",null,"Not age-restricted.","Placebo effects are different.","Not antibiotic-restricted."] },
  { id:439, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Zero-order elimination kinetics means:", opts:["Clearance rate depends on drug concentration","Constant amount of drug eliminated per unit time","Half-life remains constant at all drug concentrations","Drug is eliminated instantly without metabolic delay","Drug accumulates indefinitely without elimination"], ans:1, exp:"Zero-order: elimination rate is constant (e.g. ethanol). At any concentration above saturation, a fixed amount is removed per unit time.", optExp: ["That is first-order.",null,"Half-life varies with concentration in zero-order.","Not instant.","Drug IS eliminated."] },
  { id:440, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"First-order elimination means:", opts:["Constant amount of drug eliminated per unit time","Constant fraction of drug eliminated per unit time","No elimination of drug occurs during therapy","Enzyme is saturated at all drug concentrations","Drug elimination follows a linear dose-response relationship"], ans:1, exp:"First-order: rate of elimination is proportional to concentration; a constant FRACTION is removed per t (most drugs).", optExp: ["That is zero-order.",null,"All drugs eliminated eventually.","That is zero-order.","Linear PK applies to first-order."] },
  { id:441, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A non-competitive antagonist:", opts:["Binds reversibly to the orthosteric receptor site","Cannot be overcome by increasing agonist concentration","Produces a rightward shift in the dose-response curve","Increases the affinity of agonist for receptor","Binds to an allosteric site distinct from the agonist binding site"], ans:1, exp:"Non-competitive (or irreversible) antagonists prevent the agonist from achieving full Emax even at high concentrations.", optExp: ["That is competitive.",null,"Antagonists have efficacy 0.","Antagonists decrease potency.","They have major effect."] },
  { id:442, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Vancomycin works by:", opts:["Inhibits the 30S ribosomal subunit","Prevents peptidoglycan synthesis in the bacterial cell wall","Disrupts the bacterial cell membrane integrity","Inhibits DNA gyrase enzyme activity","Inhibits bacterial folate synthesis pathway"], ans:1, exp:"Vancomycin blocks Gram-positive cell wall synthesis by binding D-Ala-D-Ala — used for MRSA, C. difficile.", optExp: ["That is aminoglycosides.",null,"That is polymyxins.","That is quinolones.","That is sulfa drugs."] },
  { id:443, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"A morula consists of approximately:", opts:["2 cells in total","8 cells in total","16-32 compact cells","64-100 cells in total","200-500 cells in total"], ans:2, exp:"After cleavage, the embryo forms a solid ball of 16-32 cells called the morula, before cavitating into a blastocyst.", optExp: ["Too early.","Approaching morula stage.",null,"Blastocyst is ~100 cells.","Far later."] },
  { id:444, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"The blastocyst consists of:", opts:["Trophoblast and inner cell mass","Single layer of endoderm only","Single epithelial cell layer only","Yolk sac tissue only","Trilaminar germ disc only"], ans:0, exp:"Blastocyst = trophoblast (outer, → placenta) + inner cell mass/embryoblast (→ embryo) around a fluid-filled blastocoel.", optExp: [null,"Endoderm forms in week 3.","Multiple layers.","Yolk sac forms in week 2.","Trilaminar disc is week 3."] },
  { id:445, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"Somites are derived from:", opts:["Paraxial mesoderm","Lateral plate mesoderm","Endoderm layer","Ectoderm layer","Neural crest"], ans:0, exp:"Paraxial mesoderm segments into somites, giving rise to vertebrae (sclerotome), skeletal muscle (myotome), and dermis (dermatome).", optExp: [null,"Lateral plate → body wall, limbs.","Endoderm → gut.","Ectoderm → skin/CNS.","Neural crest → PNS, melanocytes."] },
  { id:446, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"Surfactant production by Type II pneumocytes begins around:", opts:["Week 5 of gestation","Week 12 of gestation","Week 24-28 of gestation","Week 36-38 of gestation","After delivery only"], ans:2, exp:"Surfactant production starts around week 24-28 but is adequate by ~35 weeks. Premature birth → respiratory distress.", optExp: ["Far too early.","Too early.",null,"Functional well before this.","Begins in utero."] },
  { id:447, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"The foramen ovale shunts blood from:", opts:["Shunts blood from left atrium to right atrium","Shunts blood from right atrium to left atrium, bypassing the lungs","Shunts blood from left ventricle to right ventricle","Connects pulmonary artery to ascending aorta","Connects umbilical vein to inferior vena cava"], ans:1, exp:"In utero, the foramen ovale shunts oxygenated blood from RA to LA, bypassing non-functional lungs.", optExp: ["Reverse direction.",null,"No ventricle-ventricle shunt.","That is the ductus arteriosus.","That is the ductus venosus."] },
  { id:448, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"The ductus arteriosus connects:", opts:["Connects right atrium to left atrium","Connects pulmonary artery to descending aorta","Connects umbilical vein to inferior vena cava","Connects ascending aorta to superior vena cava","Connects hepatic vein to cardiac circulation"], ans:1, exp:"Ductus arteriosus shunts blood from the pulmonary trunk to the descending aorta, bypassing the fetal lungs.", optExp: ["That is foramen ovale.",null,"That is ductus venosus.","Different vessels.","Not anatomically correct."] },
  { id:449, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The apex of the heart is normally located at:", opts:["2nd intercostal space at the right midclavicular line","5th intercostal space at the left midclavicular line","At the level of the xiphoid process","At the suprasternal notch","6th intercostal space at the right midclavicular line"], ans:1, exp:"The cardiac apex (LV) is normally palpated at the 5th left intercostal space in the midclavicular line.", optExp: ["This is the area for aortic auscultation.",null,"Substernal region.","Top of sternum.","Far right of normal apex."] },
  { id:450, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Stenosis of which valve typically causes a crescendo-decrescendo systolic murmur radiating to the carotids?", opts:["Mitral valve stenosis","Tricuspid valve stenosis","Pulmonary valve stenosis","Aortic valve stenosis","Mitral valve regurgitation"], ans:3, exp:"Aortic stenosis produces an ejection systolic murmur, loudest at the right 2nd intercostal space, radiating to carotids.", optExp: ["Mitral stenosis = diastolic rumble.","Tricuspid stenosis is rare; diastolic.","Pulmonary stenosis murmur in left 2nd ICS.",null,"This is a defined pathology."] },
  { id:451, cat:"Anatomy: Lymphatic System", year:"Year 1", block:"Principles", deck:"Anatomy", q:"Axillary lymph nodes drain the:", opts:["Upper limb and breast tissue","Pelvic organs only","Lower limb only","Brain tissue only","Bladder only"], ans:0, exp:"Axillary nodes drain the upper extremity, lateral breast, and thoracoabdominal wall — important in breast cancer staging.", optExp: [null,"Pelvis drains via internal iliac nodes.","Lower limb drains to inguinal nodes.","Brain has no lymphatics (mostly).","Bladder drains to pelvic nodes."] },
  { id:452, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The backbone of DNA is composed of:", opts:["Amino acids","Deoxyribose sugar and phosphate groups","Glycerol and fatty acids","Histone proteins only","Cholesterol molecules"], ans:1, exp:"DNA backbone = alternating deoxyribose sugars and phosphate groups linked by phosphodiester bonds.", optExp: ["Amino acids form proteins.",null,"That's lipid structure.","Histones package DNA but aren't the backbone.","Cholesterol is a lipid."] },
  { id:453, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A purine includes:", opts:["Adenine and guanine","Cytosine and thymine","Uracil only","Ribose sugar component","Phosphate group"], ans:0, exp:"Purines = adenine and guanine (two rings). Pyrimidines = cytosine, thymine, uracil (one ring).", optExp: [null,"Those are pyrimidines.","Pyrimidine.","Not a base.","Not a base."] },
  { id:454, cat:"Nucleic Acids & DNA", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A pyrimidine includes:", opts:["Cytosine, thymine, and uracil","Adenine only","Guanine only","Ribose sugar","Adenosine nucleoside"], ans:0, exp:"Pyrimidines have a single ring structure: cytosine (C), thymine (T) and uracil (U). Purines (adenine, guanine) have a double ring.", optExp: [null,"Adenine is a purine — double ring structure.","Guanine is a purine — double ring structure.","Ribose is a sugar, not a nitrogenous base.","Adenosine is a nucleoside (adenine + ribose), not a base."] },
  { id:455, cat:"Protein Structure", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"The peptide bond is a:", opts:["A hydrogen bond between atoms","A covalent amide bond between amino acids","An ionic bond between charged atoms","A hydrophobic interaction between side chains","A phosphate ester linkage"], ans:1, exp:"A peptide bond is a covalent amide linkage formed by dehydration synthesis between two amino acids.", optExp: ["H-bonds form secondary structure.",null,"Ionic bonds are weaker non-covalent.","Hydrophobic interactions are non-covalent.","Phosphate esters are in DNA/RNA backbones."] },
  { id:456, cat:"Gene Regulation", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Transcription factors regulate gene expression by:", opts:["Bind to DNA sequences and recruit RNA polymerase","Cleave DNA strands at specific sites","Translate mRNA into protein","Form the structural components of ribosomes","Generate ATP for cellular energy"], ans:0, exp:"Transcription factors bind promoters/enhancers/silencers, recruiting (or blocking) RNA pol II and modifying transcription rates.", optExp: [null,"Nucleases cleave DNA.","Ribosomes translate.","Ribosomes are rRNA + proteins.","Not their function."] },
  { id:457, cat:"Protein Synthesis", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Polysomes (polyribosomes) are:", opts:["Multiple ribosomes translating a single mRNA simultaneously","Multiple DNA strands bound together covalently","Mitochondrial ribosomal structures in prokaryotes","Damaged or defective ribosomal complexes","Free amino acid chains awaiting incorporation into protein"], ans:0, exp:"Multiple ribosomes can translate a single mRNA at the same time, increasing protein output per transcript.", optExp: [null,"DNA is in chromosomes.","Mitochondria have their own ribosomes but polysome is the general term.","Functional, not damaged.","Not amino acids."] },
  { id:458, cat:"Clinical Biochemistry", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Random blood glucose ≥ 11.1 mmol/L with symptoms is diagnostic of:", opts:["Hypoglycaemia","Diabetes mellitus","Insulinoma","Glycogen storage disease","Hyperinsulinaemia"], ans:1, exp:"WHO/NICE criteria: random ≥11.1 mmol/L with symptoms, or fasting ≥7.0 mmol/L, or HbA1c ≥48 mmol/mol (6.5%).", optExp: ["Hypoglycaemia is LOW glucose.",null,"Insulinoma causes hypoglycaemia.","GSDs typically cause hypoglycaemia.","Hyperinsulinaemia causes hypoglycaemia."] },
  { id:459, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Cholesterol synthesis occurs primarily in the:", opts:["Mitochondrial membranes","Cytoplasm and smooth endoplasmic reticulum","Nuclear envelope regions","Lysosomal compartments","Peroxisomal organelles"], ans:1, exp:"Cholesterol is synthesised in hepatocyte cytoplasm and smooth ER, starting from acetyl-CoA via HMG-CoA reductase (the statin target).", optExp: ["Beta-oxidation occurs in mitochondria.",null,"Not site of cholesterol synthesis.","Lysosomes degrade.","Peroxisomes handle VLCFAs and bile acid synthesis steps."] },
  { id:460, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"HMG-CoA reductase is the target of:", opts:["Aspirin","Statins","Insulin","Metformin","Warfarin"], ans:1, exp:"Statins inhibit HMG-CoA reductase, the rate-limiting enzyme of cholesterol synthesis, lowering LDL cholesterol.", optExp: ["Aspirin inhibits COX.",null,"Insulin acts on insulin receptor.","Metformin acts on AMPK / mitochondrial pathways.","Warfarin inhibits vitamin K epoxide reductase."] },
  { id:461, cat:"Glucose Metabolism (Gluconeogenesis, Glycogenesis, Glycogenolysis)", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A child with hepatomegaly and severe fasting hypoglycaemia has glucose-6-phosphatase deficiency. This is:", opts:["McArdle disease","Pompe disease","Von Gierke disease","Cori disease","Andersen disease"], ans:2, exp:"Von Gierke disease (GSD I) = glucose-6-phosphatase deficiency, presenting with severe fasting hypoglycaemia, hepatomegaly, lactic acidosis, hyperuricaemia.", optExp: ["McArdle = muscle phosphorylase deficiency.","Pompe = lysosomal α-glucosidase.",null,"Cori = debranching enzyme deficiency.","Andersen = branching enzyme deficiency."] },
  { id:462, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"A child with short stature, single palmar crease, hypotonia, and flat midface most likely has:", opts:["Turner syndrome","Down syndrome (trisomy 21)","Patau syndrome (trisomy 13)","Edwards syndrome (trisomy 18)","Klinefelter syndrome"], ans:1, exp:"Trisomy 21 (Down syndrome): flat midface, single palmar crease (simian crease), hypotonia, short stature, characteristic upward palpebral slant.", optExp: ["Turner: short, webbed neck, female-only.",null,"Patau: cleft lip/palate, polydactyly.","Edwards: clenched fists, rocker bottom feet.","Klinefelter: tall, hypogonadism, in males."] },
  { id:463, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"A male infant has clenched fists with overlapping fingers, rocker-bottom feet, micrognathia, and severe heart defects. Likely diagnosis:", opts:["Down syndrome","Patau syndrome (trisomy 13)","Edwards syndrome (trisomy 18)","Turner syndrome","Cri-du-chat syndrome"], ans:2, exp:"Trisomy 18 (Edwards): clenched fists, rocker-bottom feet, low-set ears, severe cardiac defects, poor survival (<1 year).", optExp: ["Trisomy 21 features differ.","Trisomy 13 has cleft lip/palate, polydactyly.",null,"Turner is monosomy X, female phenotype.","Cri-du-chat has cat-like cry, 5p deletion."] },
  { id:464, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"A patient with recurrent Neisseria meningitidis infections likely has a deficiency in:", opts:["C1 inhibitor deficiency","C3 complement deficiency","Late complement component deficiency (C5–C9)","IgG antibody deficiency","CD4+ T cell deficiency"], ans:2, exp:"Recurrent Neisseria infections suggest MAC (C5-C9) deficiency — MAC is critical for lysing Gram-negative organisms.", optExp: ["C1 inhibitor deficiency → hereditary angioedema.","C3 deficiency causes severe pyogenic infections, not specifically Neisseria.",null,"IgG deficiency causes recurrent encapsulated bacteria.","CD4+ deficiency causes opportunistic infections."] },
  { id:465, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"A patient with rheumatoid arthritis has chronic joint inflammation with pannus formation. The predominant infiltrate is:", opts:["Lymphocytes and macrophages","Neutrophils only","Eosinophils only","Mast cells only","Erythrocytes only"], ans:0, exp:"RA is chronic autoimmune inflammation with mononuclear cell infiltrate, immune complex deposition, and synovial hyperplasia.", optExp: [null,"Neutrophils dominate acute inflammation, not RA pannus.","Eosinophils suggest allergy/parasites.","Mast cells in allergy.","Erythrocytes are not inflammatory cells."] },
  { id:466, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"A patient with cirrhosis is at increased risk of toxicity from drugs metabolised by:", opts:["Kidney metabolism only","Hepatic CYP450 metabolism","Gut flora metabolism only","Plasma esterase metabolism","Lung tissue metabolism"], ans:1, exp:"Cirrhotic livers have reduced CYP450 capacity, so drugs metabolised by Phase I hepatic pathways accumulate.", optExp: ["Renal-cleared drugs are less affected by liver disease.",null,"Gut flora alterations less relevant.","Plasma esterases less affected.","Lung metabolism is minor."] },
  { id:467, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"A pregnant woman in labour suddenly develops respiratory distress, hypotension, and DIC. Most likely:", opts:["Amniotic fluid embolism","Pulmonary embolism","Fat embolism","Air embolism","Septic shock"], ans:0, exp:"Amniotic fluid embolism is a rare but catastrophic complication of labour, presenting with sudden cardiorespiratory collapse and DIC.", optExp: [null,"PE less specific to labour.","Fat embolism follows fractures.","Air embolism is iatrogenic.","Sepsis has different features."] },
  { id:468, cat:"Beta Oxidation & Lipid Metabolism", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"A patient with a 4-day fast has ketones in the urine because:", opts:["High glucagon activating ketogenesis","High glucose levels","High insulin levels","Fully active TCA cycle","Increased lactic acid production"], ans:0, exp:"Fasting → low insulin, high glucagon → lipolysis → beta-oxidation → excess acetyl-CoA → ketogenesis in the liver.", optExp: [null,"Glucose is LOW in fasting.","Insulin is LOW in fasting.","OAA is depleted (used for gluconeogenesis), so TCA is limited.","Lactic acidosis is anaerobic glycolysis, not fasting."] },
  { id:469, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Lactic acidosis in shock results from:", opts:["Insufficient oxygen availability leading to anaerobic metabolism","Excess insulin secretion","Liver dysfunction only","Hyperventilation response","Hyperthermia response only"], ans:0, exp:"Tissue hypoxia in shock forces anaerobic glycolysis, producing lactate. Lactic acidosis is a key feature of shock.", optExp: [null,"Not insulin-related.","Liver clears lactate; dysfunction worsens but is not the cause.","Hyperventilation is respiratory alkalosis.","Hyperthermia is separate."] },
  { id:470, cat:"Pharmacology: Pharmacodynamics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Naloxone is a:", opts:["μ-opioid agonist drug","μ-opioid antagonist drug","β-adrenergic agonist drug","Anticholinergic drug","GABA agonist drug"], ans:1, exp:"Naloxone competitively antagonises μ-opioid receptors, reversing opioid respiratory depression in overdose.", optExp: ["Morphine is an agonist.",null,"β-agonists are for asthma/anaphylaxis (β2/β1).","Atropine etc.","Benzos/alcohol affect GABA."] },
  { id:471, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Phagocytosis is:", opts:["Cell ingestion of small particles by endocytosis","Cell ingestion of large particles by endocytosis","Receptor-mediated endocytosis of specific ligands","Exocytosis of intracellular vesicles","Passive diffusion across the cell membrane"], ans:1, exp:"Phagocytosis = engulfment of large particles (>0.5 μm) such as bacteria or apoptotic cells, mainly by neutrophils/macrophages.", optExp: ["That is pinocytosis.",null,"RME is for specific molecules.","Exocytosis is outward.","Not passive."] },
  { id:472, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"Aquaporins are:", opts:["Sodium channel proteins","Water channel proteins","ATP synthase proteins","Glucose transporter proteins","Calcium pump proteins"], ans:1, exp:"Aquaporins are integral membrane proteins forming pores selective for water (e.g. AQP1 in red cells, AQP2 in renal collecting duct).", optExp: ["Different channels.",null,"ATP synthase is for energy.","GLUT transporters.","SERCA/PMCA."] },
  { id:473, cat:"Membrane Potentials & Action Potentials", year:"Year 1", block:"Principles", deck:"Physiology", q:"The Nernst equation calculates:", opts:["Membrane capacitance value","Equilibrium potential for an ion","Buffer capacity calculation","Renal clearance rate","Cardiac output measurement"], ans:1, exp:"Nernst equation gives the equilibrium potential (E_ion) for a single ion across a membrane based on its concentration gradient.", optExp: ["Capacitance is a separate property.",null,"Buffer chemistry is separate.","Pharmacokinetic measure.","Haemodynamic measure."] },
  { id:474, cat:"Muscle Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"In cardiac excitation-contraction coupling, Ca²⁺ entry through L-type channels triggers further Ca²⁺ release via:", opts:["Voltage sensor DHPR-RyR1 coupling mechanism","Calcium-induced calcium release through RyR2 channels","Sodium influx mechanism","Chloride efflux mechanism","Direct ATP binding to contractile proteins"], ans:1, exp:"In cardiac muscle, Ca²⁺ entering via L-type channels triggers RyR2 on the SR to release stored Ca²⁺ (CICR). Skeletal muscle uses mechanical DHPR-RyR1 coupling.", optExp: ["That is skeletal muscle.",null,"Different ion.","Different ion.","Not direct."] },
  { id:475, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"Glutamate is the main:", opts:["Main inhibitory neurotransmitter in the CNS","Main excitatory neurotransmitter in the CNS","Primary monoamine neurotransmitter","Acetylcholine structural analogue","Central peptide hormone"], ans:1, exp:"Glutamate is the principal excitatory CNS neurotransmitter, acting on AMPA, NMDA, kainate receptors.", optExp: ["GABA/glycine are inhibitory.",null,"Monoamines are dopamine, NE, serotonin.","ACh is separate.","Not a peptide."] },
  { id:476, cat:"Nervous System", year:"Year 1", block:"Principles", deck:"Physiology", q:"GABA is:", opts:["Excitatory monoamine neurotransmitter","Main inhibitory neurotransmitter in the CNS","Peptide hormone in the brain","Amino acid-derived hormone","Adrenergic agonist compound"], ans:1, exp:"GABA (γ-aminobutyric acid) is the primary inhibitory CNS neurotransmitter, acting on GABA-A (ionotropic) and GABA-B (metabotropic) receptors.", optExp: ["Glutamate is excitatory.",null,"GABA is amino acid-derived, not a peptide hormone.","Not a circulating hormone.","Not adrenergic."] },
  { id:477, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Cortisol acts via which receptor type?", opts:["G-protein coupled receptor","Receptor tyrosine kinase","Intracellular nuclear receptor","Ligand-gated ion channel","Voltage-gated ion channel"], ans:2, exp:"Cortisol is lipid-soluble; it crosses the membrane and binds glucocorticoid receptors that alter gene transcription.", optExp: ["Adrenergic etc.","Insulin etc.",null,"Nicotinic etc.","Not a receptor type."] },
  { id:478, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Affinity maturation of antibodies occurs via:", opts:["Somatic hypermutation in germinal centres","Immunoglobulin class switching mechanism","Allelic exclusion process","V(D)J recombination during B cell development","Phagocytosis of pathogens by B cells"], ans:0, exp:"Somatic hypermutation in germinal centres of lymph nodes selects B cells with higher antibody affinity for repeated exposure.", optExp: [null,"Different process.","Allelic exclusion is for one allele expression.","V(D)J creates initial diversity but not affinity maturation per se.","Not the mechanism."] },
  { id:479, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Free radicals damage cells primarily through:", opts:["Direct cell membrane fusion","Lipid peroxidation and DNA damage","Increased ATP production only","Glycolysis activation only","Inhibition of necrotic cell death"], ans:1, exp:"ROS (e.g. superoxide, H₂O₂) oxidise membrane lipids, proteins, and DNA, causing cell injury and death.", optExp: ["Not a real mechanism.",null,"Free radicals deplete ATP.","Not their effect.","They cause necrosis."] },
  { id:480, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Endogenous antioxidants include all EXCEPT:", opts:["Glutathione","Superoxide dismutase (SOD)","Catalase","Vitamin C","NADH"], ans:4, exp:"NADH is a reducing equivalent but not an antioxidant. Glutathione, SOD, catalase, vitamins C/E are antioxidants.", optExp: ["Major antioxidant.","Converts O2- to H2O2.","Converts H2O2 to water.","Water-soluble antioxidant.",null] },
  { id:481, cat:"Genetics: Genome & Chromosomes", year:"Year 1", block:"Principles", deck:"Genetics", q:"In a nucleosome, DNA wraps around:", opts:["Ribosomal RNA molecules","Histone octamer core proteins","Centromere proteins complex","Nuclear membrane proteins","Sugar-phosphate backbone strands"], ans:1, exp:"~147 bp of DNA wraps around a histone octamer (2 each of H2A, H2B, H3, H4) to form a nucleosome.", optExp: ["DNA is paired with histones, not RNA.",null,"Centromere proteins are separate.","Not membrane-bound.","Backbone is part of DNA structure."] },
  { id:482, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Interferons are mainly important against:", opts:["Bacteria","Viruses","Fungi","Parasites","Self cells"], ans:1, exp:"Type I interferons (α, β) are key antiviral cytokines, inducing antiviral state in neighbouring cells.", optExp: ["Different cytokine profile.",null,"Different mechanisms.","Different mechanisms.","Not their target."] },
  { id:483, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"T regulatory cells (Tregs) function to:", opts:["Kill virally infected cells","Suppress immune response and maintain tolerance","Produce antibody molecules","Engulf pathogens via phagocytosis","Activate complement cascade"], ans:1, exp:"Tregs (CD4+CD25+FOXP3+) dampen immune responses and prevent autoimmunity.", optExp: ["CD8+ T cells do this.",null,"B cells/plasma cells.","Neutrophils/macrophages.","Complement is innate."] },
  { id:484, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Cachexia in cancer is mediated mainly by:", opts:["Insulin hormone exclusively","TNF-α and other pro-inflammatory cytokines","Growth hormone primarily","Cortisol hormone alone","Unknown mediator mechanism"], ans:1, exp:"Cancer cachexia involves TNF-α, IL-6, and other cytokines that increase catabolism and reduce appetite.", optExp: ["Insulin causes anabolism.",null,"GH would build muscle.","Cortisol contributes but not alone.","Mediators are well characterised."] },
  { id:485, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"The mesoderm gives rise to all EXCEPT:", opts:["Heart and blood vessels","Skeletal muscle and bone","Kidneys and gonads","Gut epithelium and intestinal lining","Dermis of skin"], ans:3, exp:"Gut epithelium is endoderm-derived. Mesoderm gives rise to muscle, bone, cardiovascular, urogenital, dermis.", optExp: ["Cardiogenic mesoderm.","Paraxial mesoderm.","Intermediate mesoderm.",null,"Dermis from somitic mesoderm."] },
  { id:486, cat:"Embryology: Trilaminar Disc", year:"Year 1", block:"Principles", deck:"Embryology", q:"Neural crest cells derive from and give rise to all EXCEPT:", opts:["Melanocytes","Schwann cells","Adrenal medulla","Most of cardiac septum","Liver hepatocytes"], ans:4, exp:"Liver hepatocytes are endoderm-derived. Neural crest contributes to melanocytes, PNS, adrenal medulla, parts of heart, etc.", optExp: ["Neural crest derivative.","Neural crest derivative.","Neural crest derivative.","Neural crest contribution.",null] },
  { id:487, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"S1 heart sound is produced by:", opts:["Semilunar valve closure","Atrioventricular valve closure at ventricular systole","Atrial muscle contraction","Ventricular filling phase","Ductus arteriosus closure"], ans:1, exp:"S1 ('lub') = closure of mitral and tricuspid valves at the start of systole. S2 ('dub') = SL closure.", optExp: ["That is S2.",null,"Atrial kick is silent normally.","S3 reflects rapid filling.","Postnatal event, not heart sound."] },
  { id:488, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"S2 heart sound is produced by:", opts:["Mitral and tricuspid valve closure","Aortic and pulmonary valve closure at ventricular diastole","Atrial muscle contraction","Rapid ventricular filling phase","Ventricular ejection phase"], ans:1, exp:"S2 = closure of aortic and pulmonary valves, marking end of systole.", optExp: ["That is S1.",null,"Atrial kick is silent.","S3 reflects this.","No specific sound."] },
  { id:489, cat:"Pharmacology: Introduction & Receptors", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Atropine is a:", opts:["Nicotinic acetylcholine agonist","Muscarinic acetylcholine antagonist","β-adrenergic receptor agonist","α-adrenergic receptor antagonist","Opioid receptor agonist"], ans:1, exp:"Atropine competitively blocks muscarinic ACh receptors → ↑ HR, dry mouth, dilated pupils, bronchodilation.", optExp: ["Nicotine is the agonist.",null,"Salbutamol is β2 agonist.","Doxazosin etc.","Morphine etc."] },
  { id:490, cat:"Pharmacology: Antibiotics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Tetracyclines are bacteriostatic via:", opts:["Inhibits bacterial cell wall synthesis","Blocks 30S ribosomal subunit translation","Inhibits folate synthesis pathway","Disrupts bacterial cell membranes","Inhibits bacterial topoisomerase enzyme"], ans:1, exp:"Tetracyclines bind 30S ribosomal subunit, blocking aminoacyl-tRNA entry to the A site — bacteriostatic.", optExp: ["β-lactams.",null,"Sulfa.","Polymyxins.","Quinolones."] },
  { id:491, cat:"Embryology: Fetal Period", year:"Year 1", block:"Principles", deck:"Embryology", q:"The teratogenic period of greatest risk is generally:", opts:["Week 1 post-conception","Weeks 3–8 during organogenesis","Weeks 20–30 of gestation","Last trimester of pregnancy","Pre-conception period"], ans:1, exp:"Most teratogens cause major malformations during weeks 3-8 (organogenesis). Before week 3 = all-or-none. After week 8 = mainly growth/functional defects.", optExp: ["Pre-implantation: all-or-none.",null,"Mainly functional/growth effects.","Mainly functional effects.","No embryo yet."] },
  { id:492, cat:"Genetics: Inheritance Patterns", year:"Year 1", block:"Principles", deck:"Genetics", q:"In a pedigree, an autosomal dominant condition typically shows:", opts:["Skips generations in families","Affects only male individuals","Vertical transmission pattern through generations","Affects only female individuals","Requires two carrier parents"], ans:2, exp:"Autosomal dominant patterns show vertical transmission (every generation), both sexes affected equally.", optExp: ["Recessive may appear to skip generations.","X-linked recessive favours males.",null,"Not sex-specific.","That is recessive."] },
  { id:493, cat:"Pathology: Inflammation", year:"Year 1", block:"Principles", deck:"Pathology", q:"Bradykinin in inflammation causes:", opts:["Causes blood vessel constriction","Causes vasodilation and increased vascular permeability with pain","Induces cellular death directly","Stimulates phagocytic activity primarily","Promotes antibody synthesis"], ans:1, exp:"Bradykinin causes vasodilation, vascular permeability, and is a potent mediator of pain. ACE inhibitors raise bradykinin → cough.", optExp: ["Vasoconstriction would be opposite.",null,"Not direct cell death.","Not a phagocytic signal.","Not its function."] },
  { id:494, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Heparin's mechanism of action is:", opts:["Inhibits vitamin K-dependent clotting factors","Activates antithrombin III to enhance thrombin inhibition","Inhibits platelet aggregation","Provides direct thrombin inhibition","Promotes fibrinolysis"], ans:1, exp:"Heparin binds antithrombin III, accelerating its inactivation of thrombin (IIa) and factor Xa.", optExp: ["That is warfarin.",null,"Aspirin/clopidogrel.","Dabigatran is direct.","tPA itself."] },
  { id:495, cat:"Pathology: Thrombosis & Embolism", year:"Year 1", block:"Principles", deck:"Pathology", q:"Warfarin acts by:", opts:["Provides direct thrombin inhibition","Inhibits vitamin K-dependent clotting factor synthesis","Activates antithrombin III","Blocks platelet aggregation","Activates plasminogen"], ans:1, exp:"Warfarin inhibits vitamin K-dependent gamma-carboxylation of clotting factors II, VII, IX, X (and proteins C/S).", optExp: ["Dabigatran is direct thrombin inhibitor.",null,"That is heparin.","Antiplatelet drugs do that.","tPA does that."] },
  { id:496, cat:"Pharmacology: Pharmacokinetics", year:"Year 1", block:"Principles", deck:"Pharmacology", q:"Steady state plasma concentration is achieved after approximately:", opts:["After 1 half-life","After 2 half-lives","After 4-5 half-lives","After 10 half-lives","Never achieved in clinical practice"], ans:2, exp:"With regular dosing, steady state (input rate = output rate) is reached after ~4-5 half-lives (about 94-97% of steady state).", optExp: ["50% of steady state.","75%.",null,"Excessive.","Eventually reached."] },
  { id:497, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"The most abundant white blood cell in healthy adults is:", opts:["Neutrophil","Lymphocyte","Monocyte","Eosinophil","Basophil"], ans:0, exp:"Neutrophils make up 50-70% of circulating WBCs; lymphocytes ~20-40%; monocytes ~2-10%; eosinophils ~1-4%; basophils <1%.", optExp: [null,"Second most common.","Smaller proportion.","Smaller proportion.","Rarest."] },
  { id:498, cat:"Adaptive Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Pentameric structure with 10 antigen-binding sites is a feature of:", opts:["IgG","IgA dimer","IgM with pentameric structure","IgD","IgE"], ans:2, exp:"Serum IgM is a pentamer (5 monomers, 10 binding sites), making it highly avid and effective at complement activation.", optExp: ["IgG is monomeric.","IgA is dimeric in secretions.",null,"IgD is monomeric.","IgE is monomeric."] },
  { id:499, cat:"Glycolysis & Bioenergetics", year:"Year 1", block:"Principles", deck:"Biochemistry", q:"Insulin signalling activates which transporter for glucose uptake into muscle and fat?", opts:["GLUT1","GLUT2","GLUT3","GLUT4","SGLT1"], ans:3, exp:"GLUT4 is insulin-responsive; insulin → translocation of GLUT4 to the plasma membrane in muscle and adipose tissue.", optExp: ["GLUT1 is widespread, insulin-independent.","GLUT2 is in liver, β-cells.","GLUT3 is in neurons.",null,"SGLT1 is gut/kidney sodium-glucose cotransporter."] },
  { id:500, cat:"Genetics: Mutations & Disease", year:"Year 1", block:"Principles", deck:"Genetics", q:"Sickle cell carriers (heterozygotes) have a survival advantage against:", opts:["Tuberculosis infection","Cholera bacterial infection","Malaria parasitic infection","HIV viral infection","Influenza viral infection"], ans:2, exp:"Sickled red cells are inhospitable to P. falciparum, giving heterozygotes a survival advantage in malarial regions — explaining persistence of the allele.", optExp: ["TB resistance is unrelated.","Possibly CF.",null,"HIV resistance is CCR5-Δ32.","Not selected."] },
  { id:501, cat:"Membrane Physiology", year:"Year 1", block:"Principles", deck:"Physiology", q:"The Na/K-ATPase belongs to which class of transporters?", opts:["Uniporter","Symporter","Antiporter","Channel protein","Pore-forming protein"], ans:2, exp:"Na/K-ATPase is a primary active antiporter (exchanger) — moves Na⁺ out and K⁺ in against gradients using ATP.", optExp: ["Uniporter moves one ion.","Symporter moves two same direction.",null,"Not a passive channel.","Not a pore."] },
  { id:502, cat:"Hormone Signalling", year:"Year 1", block:"Principles", deck:"Physiology", q:"Thyroid hormones (T3/T4) bind:", opts:["G-protein-coupled receptor","Receptor tyrosine kinase","Nuclear receptor","Ligand-gated ion channel","Voltage-gated ion channel"], ans:2, exp:"T3 (and T4 → T3 in cells) binds nuclear thyroid hormone receptors, modifying gene transcription — slow but long-lasting effects.", optExp: ["Not GPCR.","Not RTK.",null,"Not LGIC.","Not voltage-gated."] },
  { id:503, cat:"Genetics: Cell Division (Mitosis & Meiosis)", year:"Year 1", block:"Principles", deck:"Genetics", q:"After S phase but before mitosis, each chromosome consists of:", opts:["One chromatid","Two sister chromatids joined at centromere","Four chromatids","Half a chromatid","No chromatids"], ans:1, exp:"DNA replication in S phase doubles each chromosome to two sister chromatids joined at the centromere, separated in mitotic anaphase.", optExp: ["Pre-S phase configuration.",null,"Tetraploid would be too many.","Not a real state.","Not real state."] },
  { id:504, cat:"Pathology: Neoplasia", year:"Year 1", block:"Principles", deck:"Pathology", q:"Common sites for metastatic cancer to spread are:", opts:["Skin only","Lung, liver, bone, and brain","Heart only","Spleen only","Pancreas only"], ans:1, exp:"Common metastatic sites are lung, liver, bone (especially axial), and brain — reflecting blood flow and microenvironment.", optExp: ["Skin is uncommon as primary site.",null,"Heart metastasis is rare.","Spleen metastasis is uncommon.","Pancreatic mets are not the typical pattern."] },
  { id:505, cat:"Embryology: Early Development", year:"Year 1", block:"Principles", deck:"Embryology", q:"The syncytiotrophoblast is responsible for:", opts:["Forms the embryonic disc","Invades endometrium and produces hCG","Forms the bilaminar disc","Produces fetal blood cells","Forms hyaline cartilage"], ans:1, exp:"Syncytiotrophoblast erodes maternal tissue to embed the blastocyst and secretes hCG to maintain corpus luteum.", optExp: ["Inner cell mass becomes the embryo.",null,"Embryoblast forms the disc.","Liver makes fetal blood later.","Unrelated to trophoblast."] },
  { id:506, cat:"Innate Immunity", year:"Year 1", block:"Principles", deck:"Immunology", q:"Macrophages in liver are specifically called:", opts:["Microglia","Kupffer cells","Langerhans cells","Osteoclasts","Alveolar macrophages"], ans:1, exp:"Kupffer cells are liver-resident macrophages lining sinusoids. Microglia = brain, Langerhans = skin, osteoclasts = bone, alveolar = lung.", optExp: ["Brain macrophages.",null,"Skin macrophages.","Bone-resorbing cells (also macrophage-derived).","Lung macrophages."] },
  { id:507, cat:"Histology: Bone & Cartilage", year:"Year 1", block:"Principles", deck:"Histology", q:"Cartilage receives nutrients via:", opts:["Central artery","Diffusion from perichondrium","Lymphatic vessels","Direct synovial fluid uptake","Nerve-mediated transport"], ans:1, exp:"Cartilage is avascular and aneural; chondrocytes rely on diffusion through the matrix from the perichondrium.", optExp: ["No central artery.",null,"No lymphatics in cartilage.","Synovial fluid plays a role in joints but main mechanism is diffusion.","Not innervated."] },
  { id:508, cat:"Anatomy: Cardiovascular", year:"Year 1", block:"Principles", deck:"Anatomy", q:"The pericardium consists of:", opts:["Single fibrous layer","Fibrous and serous layers","Three serous layers","Inner endocardium only","Muscle layers only"], ans:1, exp:"Pericardium = tough outer fibrous + inner serous (parietal lines fibrous; visceral = epicardium on heart). Pericardial fluid in between.", optExp: ["Two main components.",null,"Two serous layers.","Endocardium is the heart's inner lining.","Myocardium is muscle."] },
  { id:509, cat:"Histology: Muscle", year:"Year 1", block:"Principles", deck:"Histology", q:"Cardiac muscle nuclei are typically:", opts:["Multiple nuclei arranged at the periphery of the cell","One to two nuclei located centrally within the cell","Completely absent from cardiac muscle cells","Many nuclei distributed randomly throughout the cytoplasm","Nuclei embedded exclusively within the intercalated discs"], ans:1, exp:"Cardiac myocytes have 1-2 centrally located nuclei. Skeletal muscle has many peripheral nuclei.", optExp: ["That is skeletal.",null,"Cells have nuclei.","Usually 1-2, not many.","Discs are at cell ends."] },
  { id:510, cat:"Pathology: Cell Injury & Death", year:"Year 1", block:"Principles", deck:"Pathology", q:"Lipofuscin pigment in cells indicates:", opts:["Iron overload in hepatocytes","Accumulation of indigestible cellular debris from normal wear and tear","Excessive bilirubin deposition in tissues","Abnormal melanin synthesis in melanocytes","Pathological calcium deposition in cardiac tissue"], ans:1, exp:"Lipofuscin is a yellow-brown 'wear and tear' pigment from oxidised membrane lipids, accumulating in long-lived cells (heart, neurons, liver).", optExp: ["Haemosiderin = iron.",null,"Bilirubin causes jaundice.","Melanin is in pigmented cells.","Calcium phosphate is mineralisation."] }
];

export const DECK_MAP = Object.fromEntries(
  Array.from(new Set(QUESTIONS.map(q => q.deck))).map(d => [
    d, Array.from(new Set(QUESTIONS.filter(q => q.deck === d).map(q => q.cat)))
  ])
);

export const CATEGORIES = Array.from(new Set(QUESTIONS.map(q => q.cat)));

// Apply any user edits stored in localStorage
const _qEdits = (() => { try { return JSON.parse(localStorage.getItem("pq_question_edits")) || {}; } catch { return {}; } })();
for (const q of QUESTIONS) { if (_qEdits[q.id]) Object.assign(q, _qEdits[q.id]); }

function loadGenerated() { try { return JSON.parse(localStorage.getItem("pq_generated") || "[]"); } catch { return []; } }
export const GENERATED_QUESTIONS = loadGenerated();
export const ALL_QUESTIONS = [...QUESTIONS, ...GENERATED_QUESTIONS];
